// Render puede tener cold starts que superan 15s en la primera petición.
// Subimos el timeout para evitar falsos "Servidor no disponible" al arrancar.
const API_TIMEOUT_MS = 90000;

// Versión del service worker (ver `web/sw.js`). Se usa para forzar refresh si el usuario se queda con JS antiguo.
const APP_SW_VERSION = "v46";

// Workspace tenant por defecto del producto (branding de software). Mantiene compatibilidad con slugs legacy.
const DEFAULT_TENANT_WORKSPACE_SLUG = "verifika2";
const LEGACY_TENANT_WORKSPACE_SLUGS = new Set(["modernia", "grupomodernia", "grupo-modernia"]);
const DEFAULT_TENANT_WORKSPACE_NAME = "Modernia";
const normalizeSlugLike = (value) =>
  String(value || "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, "-")
    .replace(/[^a-z0-9\-]+/g, "")
    .replace(/\-+/g, "-")
    .replace(/^\-+|\-+$/g, "");

const normalizeTenantWorkspaceSlug = (value, fallback = DEFAULT_TENANT_WORKSPACE_SLUG) => {
  const raw = String(value || "").trim();
  if (!raw) return fallback;
  const normalized = normalizeSlugLike(raw);
  if (LEGACY_TENANT_WORKSPACE_SLUGS.has(normalized)) return fallback;
  return raw;
};

const fetchWithTimeout = async (input, init = {}, timeoutMs = API_TIMEOUT_MS) => {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), Math.max(1000, Number(timeoutMs) || API_TIMEOUT_MS));
  try {
    return await fetch(input, { ...(init || {}), signal: controller.signal });
  } finally {
    clearTimeout(timer);
  }
};

const setUiToast = (title, detail = "") => {
  const toast = document.getElementById("uiErrorToast");
  if (!toast) return;
  toast.classList.remove("hidden");
  toast.innerHTML = "";
  const strong = document.createElement("strong");
  strong.textContent = title || "";
  toast.appendChild(strong);
  if (detail) {
    const pre = document.createElement("pre");
    pre.textContent = String(detail).slice(0, 2000);
    toast.appendChild(pre);
  }
};

const hideUiToast = () => {
  const toast = document.getElementById("uiErrorToast");
  if (!toast) return;
  toast.classList.add("hidden");
  toast.innerHTML = "";
};

const probeDbHealth = async () => {
  try {
    const res = await fetchWithTimeout(
      "/api/health",
      { cache: "no-store", credentials: "same-origin" },
      4500
    );
    const body = await res.text().catch(() => "");
    return { ok: res.ok, status: res.status, body: String(body || "").trim() };
  } catch (err) {
    const msg = err?.name === "AbortError" ? "Tiempo de espera agotado." : "No se pudo conectar con el servidor.";
    return { ok: false, status: 0, body: msg };
  }
};

const sanitizeApiUrl = (value) => {
  const raw = String(value || "");
  if (!raw) return raw;
  const [base, query] = raw.split("?", 2);
  if (!query) return base;
  const scrubKeys = new Set(["token", "password", "activar_token", "portal_token"]);
  const parts = query
    .split("&")
    .filter(Boolean)
    .map((part) => {
      const [k, v = ""] = part.split("=", 2);
      const key = String(k || "").trim();
      if (!key) return "";
      if (scrubKeys.has(key)) return `${key}=***`;
      return `${key}=${v}`;
    })
    .filter(Boolean);
  return parts.length ? `${base}?${parts.join("&")}` : base;
};

const api = async (path) => {
  let res;
  try {
    res = await fetchWithTimeout(path, { cache: "no-store", credentials: "same-origin" });
  } catch (err) {
    const message = err?.name === "AbortError"
      ? "Tiempo de espera agotado."
      : "No se pudo conectar con el servidor.";
    const error = new Error(message);
    error.cause = err;
    error.status = 0;
    throw error;
  }
  let data = null;
  try {
    data = await res.json();
  } catch {
    data = null;
  }
  if (!res.ok) {
    const msg =
      (data && data.detail)
      || (data && data.error && data.error !== "API error" ? data.error : "")
      || (data && data.error)
      || `HTTP ${res.status}`;
    const safePath = sanitizeApiUrl(path);
    const error = new Error(safePath ? `${msg} · ${safePath}` : msg);
    error.status = res.status;
    error.data = data;
    if (res.status === 401) {
      error.isAuthError = true;
      handleAuthExpired();
    }
    throw error;
  }
  return data;
};

const apiPost = async (url, payload = {}) => {
  let res;
  try {
    res = await fetchWithTimeout(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      credentials: "same-origin",
      body: JSON.stringify(payload),
    });
  } catch (err) {
    const message = err?.name === "AbortError"
      ? "Tiempo de espera agotado."
      : "No se pudo conectar con el servidor.";
    const error = new Error(message);
    error.cause = err;
    error.status = 0;
    throw error;
  }

  let data = null;
  try {
    data = await res.json();
  } catch {
    data = null;
  }

  if (!res.ok || data?.error) {
    const msg =
      (data && data.detail)
      || (data && data.error && data.error !== "API error" ? data.error : "")
      || (data && data.error)
      || `HTTP ${res.status}`;
    const safeUrl = sanitizeApiUrl(url);
    const error = new Error(safeUrl ? `${msg} · ${safeUrl}` : msg);
    error.status = res.status;
    error.data = data;
    throw error;
  }

  return data;
};

const getGeoLocation = async (timeoutMs = 3500) => {
  try {
    if (!navigator.geolocation) return null;
    return await new Promise((resolve) => {
      let done = false;
      const timer = setTimeout(() => {
        if (done) return;
        done = true;
        resolve(null);
      }, Math.max(1200, Number(timeoutMs) || 3500));
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          if (done) return;
          done = true;
          clearTimeout(timer);
          const c = pos?.coords;
          if (!c) return resolve(null);
          resolve({ lat: c.latitude, lon: c.longitude, acc: c.accuracy, source: "browser" });
        },
        () => {
          if (done) return;
          done = true;
          clearTimeout(timer);
          resolve(null);
        },
        { enableHighAccuracy: true, maximumAge: 60000, timeout: Math.max(1200, Number(timeoutMs) || 3500) }
      );
    });
  } catch {
    return null;
  }
};

const randomId = () => {
  const bytes = new Uint8Array(16);
  crypto.getRandomValues(bytes);
  return Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("");
};

const setCrmMode = (mode = "") => {
  if (!document.body) return;
  document.body.classList.toggle("crm-seguros", mode === "seguros");
  document.body.classList.toggle("crm-fin", mode === "fin");
};

const DENSITY_STORAGE_KEY = "crm_density_mode";
const DENSITY_NORMAL = "normal";
const DENSITY_COMPACT = "compact";

const UPLOAD_IMAGE_COMPRESS_MIN_BYTES = 500 * 1024;
const UPLOAD_IMAGE_MAX_SIDE = 2200;
const UPLOAD_IMAGE_QUALITY = 0.82;
const S3_MULTIPART_MIN_BYTES = 10 * 1024 * 1024;
const S3_MULTIPART_CONCURRENCY = 3;

const guessMimeType = (file) => {
  const explicit = String(file?.type || "").trim().toLowerCase();
  if (explicit) return explicit;
  const name = String(file?.name || "").trim().toLowerCase();
  if (name.endsWith(".pdf")) return "application/pdf";
  if (name.endsWith(".jpg") || name.endsWith(".jpeg")) return "image/jpeg";
  if (name.endsWith(".png")) return "image/png";
  if (name.endsWith(".webp")) return "image/webp";
  if (name.endsWith(".gif")) return "image/gif";
  if (name.endsWith(".svg")) return "image/svg+xml";
  if (name.endsWith(".doc")) return "application/msword";
  if (name.endsWith(".docx")) return "application/vnd.openxmlformats-officedocument.wordprocessingml.document";
  if (name.endsWith(".xls")) return "application/vnd.ms-excel";
  if (name.endsWith(".xlsx")) return "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
  return "application/octet-stream";
};

const isCompressibleImage = (file) => {
  const mime = String(file?.type || "").toLowerCase();
  if (!mime.startsWith("image/")) return false;
  if (mime.includes("gif") || mime.includes("svg")) return false;
  return true;
};

const loadImageElement = (file) =>
  new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const img = new Image();
      img.onload = () => resolve(img);
      img.onerror = () => reject(new Error("No se pudo leer la imagen."));
      img.src = reader.result;
    };
    reader.onerror = () => reject(new Error("No se pudo leer la imagen."));
    reader.readAsDataURL(file);
  });

const maybeCompressUploadFile = async (file, statusEl) => {
  if (!file || !isCompressibleImage(file) || file.size < UPLOAD_IMAGE_COMPRESS_MIN_BYTES) {
    return { file, optimized: false };
  }
  try {
    if (statusEl) statusEl.textContent = "Optimizando imagen...";
    const img = await loadImageElement(file);
    const width = img.naturalWidth || img.width || 0;
    const height = img.naturalHeight || img.height || 0;
    if (!width || !height) return { file, optimized: false };
    const scale = Math.min(1, UPLOAD_IMAGE_MAX_SIDE / Math.max(width, height));
    const targetW = Math.max(1, Math.round(width * scale));
    const targetH = Math.max(1, Math.round(height * scale));
    const canvas = document.createElement("canvas");
    canvas.width = targetW;
    canvas.height = targetH;
    const ctx = canvas.getContext("2d");
    if (!ctx) return { file, optimized: false };
    ctx.drawImage(img, 0, 0, targetW, targetH);
    const compressedBlob = await new Promise((resolve) => {
      canvas.toBlob(resolve, "image/jpeg", UPLOAD_IMAGE_QUALITY);
    });
    if (!compressedBlob) return { file, optimized: false };
    if (compressedBlob.size >= file.size * 0.95) {
      return { file, optimized: false };
    }
    const baseName = (file.name || "imagen").replace(/\.[^.]+$/, "");
    const optimizedFile = new File([compressedBlob], `${baseName}.jpg`, {
      type: "image/jpeg",
      lastModified: Date.now(),
    });
    return { file: optimizedFile, optimized: true, originalSize: file.size, optimizedSize: optimizedFile.size };
  } catch {
    return { file, optimized: false };
  }
};

const uploadBlobToSignedUrl = (url, file, statusEl, contentTypeOverride = "") =>
  new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    xhr.open("PUT", url, true);
    const contentType = String(contentTypeOverride || "").trim() || guessMimeType(file);
    xhr.setRequestHeader("Content-Type", contentType);
    xhr.upload.onprogress = (event) => {
      if (!statusEl || !event.lengthComputable) return;
      const pct = Math.max(0, Math.min(100, Math.round((event.loaded / event.total) * 100)));
      statusEl.textContent = `Subiendo a la nube... ${pct}%`;
    };
    xhr.onload = () => {
      if (xhr.status >= 200 && xhr.status < 300) {
        resolve();
        return;
      }
      let message = `S3 error ${xhr.status}`;
      const text = String(xhr.responseText || "");
      const msgMatch = text.match(/<Message>([^<]+)<\/Message>/i);
      if (msgMatch && msgMatch[1]) {
        message = msgMatch[1];
      }
      reject(new Error(message));
    };
    xhr.onerror = () => reject(new Error("Error de red durante la subida."));
    xhr.send(file);
  });

const uploadBlobToSignedUrlWithFetch = async (url, file, contentTypeOverride = "") => {
  const contentType = String(contentTypeOverride || "").trim() || guessMimeType(file);
  const putRes = await fetch(url, {
    method: "PUT",
    headers: { "Content-Type": contentType },
    body: file,
  });
  if (!putRes.ok) {
    let message = `S3 error ${putRes.status}`;
    try {
      const text = await putRes.text();
      const msgMatch = text.match(/<Message>([^<]+)<\/Message>/i);
      if (msgMatch && msgMatch[1]) {
        message = msgMatch[1];
      }
    } catch {}
    throw new Error(message);
  }
};

const uploadMultipartPartToSignedUrl = (url, blob, onPartProgress) =>
  new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    xhr.open("PUT", url, true);
    xhr.setRequestHeader("Content-Type", "application/octet-stream");
    xhr.upload.onprogress = (event) => {
      if (!event.lengthComputable) return;
      onPartProgress?.(event.loaded);
    };
    xhr.onload = () => {
      if (xhr.status >= 200 && xhr.status < 300) {
        onPartProgress?.(blob.size);
        resolve();
        return;
      }
      let message = `S3 part error ${xhr.status}`;
      const text = String(xhr.responseText || "");
      const msgMatch = text.match(/<Message>([^<]+)<\/Message>/i);
      if (msgMatch && msgMatch[1]) {
        message = msgMatch[1];
      }
      reject(new Error(message));
    };
    xhr.onerror = () => reject(new Error("Error de red durante subida multipart."));
    xhr.send(blob);
  });

const uploadFileMultipartToS3 = async (file, prefix, statusEl) => {
  const start = await fetch("/api/s3_multipart_start", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      filename: file.name || "archivo.bin",
      content_type: guessMimeType(file),
      prefix: prefix || "docs",
      size: file.size || 0,
    }),
  }).then((res) => res.json());
  if (start.error) {
    throw new Error(start.error);
  }
  const key = start.key || "";
  const uploadId = start.upload_id || "";
  const partSize = Math.max(5 * 1024 * 1024, Number(start.part_size || 8 * 1024 * 1024));
  if (!key || !uploadId) {
    throw new Error("No se pudo iniciar multipart.");
  }

  const partCount = Math.max(1, Math.ceil(file.size / partSize));
  const loadedByPart = new Array(partCount).fill(0);
  let nextPart = 1;

  const updateOverallProgress = () => {
    if (!statusEl) return;
    const loaded = loadedByPart.reduce((sum, value) => sum + value, 0);
    const pct = file.size
      ? Math.max(0, Math.min(100, Math.round((loaded / file.size) * 100)))
      : 0;
    statusEl.textContent = `Subiendo a la nube... ${pct}%`;
  };

const uploadOnePart = async (partNumber) => {
    const startByte = (partNumber - 1) * partSize;
    const endByte = Math.min(startByte + partSize, file.size);
    const blob = file.slice(startByte, endByte);
    const presign = await apiPost("/api/s3_multipart_presign", {
      key,
      upload_id: uploadId,
      part_number: partNumber,
    });
    if (presign.error || !presign.url) {
      throw new Error(presign.error || "No se pudo firmar parte multipart.");
    }
    await uploadMultipartPartToSignedUrl(presign.url, blob, (loaded) => {
      loadedByPart[partNumber - 1] = loaded;
      updateOverallProgress();
    });
  };

  const worker = async () => {
    while (true) {
      const current = nextPart;
      nextPart += 1;
      if (current > partCount) return;
      await uploadOnePart(current);
    }
  };

  try {
    if (statusEl) statusEl.textContent = "Preparando subida por bloques...";
    const workers = Array.from(
      { length: Math.min(S3_MULTIPART_CONCURRENCY, partCount) },
      () => worker()
    );
    await Promise.all(workers);
    const complete = await apiPost("/api/s3_multipart_complete", {
      key,
      upload_id: uploadId,
    });
    if (complete.error) {
      throw new Error(complete.error);
    }
    return {
      key: complete.key || key,
      public_url: complete.public_url || start.public_url || "",
    };
  } catch (err) {
    try {
      await apiPost("/api/s3_multipart_abort", {
        key,
        upload_id: uploadId,
      });
    } catch {}
    throw err;
  }
};

const uploadFileToS3 = async (file, prefix, statusEl) => {
  if (!file) return null;
  const optimized = await maybeCompressUploadFile(file, statusEl);
  const fileToUpload = optimized.file || file;
  const contentType = guessMimeType(fileToUpload);
  if ((fileToUpload.size || 0) >= S3_MULTIPART_MIN_BYTES) {
    const multipartResult = await uploadFileMultipartToS3(fileToUpload, prefix, statusEl);
    if (statusEl && optimized.optimized && optimized.originalSize && optimized.optimizedSize) {
      const saved = Math.max(0, optimized.originalSize - optimized.optimizedSize);
      const pct = optimized.originalSize
        ? Math.round((saved / optimized.originalSize) * 100)
        : 0;
      statusEl.textContent = `Subida completada (multipart). Imagen optimizada (-${pct}%).`;
    } else if (statusEl) {
      statusEl.textContent = "Subida completada (multipart).";
    }
    return multipartResult;
  }
	    if (statusEl) statusEl.textContent = "Firmando subida...";
  const presign = await apiPost("/api/s3_presign", {
    filename: fileToUpload.name || "archivo.pdf",
    content_type: contentType || "application/octet-stream",
    prefix: prefix || "seguros",
  });
  if (presign.error) {
    throw new Error(presign.error);
  }
  if (!presign.url) {
    throw new Error("Presign inválido.");
  }
  try {
    await uploadBlobToSignedUrl(presign.url, fileToUpload, statusEl, contentType);
  } catch (xhrErr) {
    if (statusEl) statusEl.textContent = "Reintentando subida...";
    await uploadBlobToSignedUrlWithFetch(presign.url, fileToUpload, contentType);
  }
  if (statusEl && optimized.optimized && optimized.originalSize && optimized.optimizedSize) {
    const saved = Math.max(0, optimized.originalSize - optimized.optimizedSize);
    const pct = optimized.originalSize
      ? Math.round((saved / optimized.originalSize) * 100)
      : 0;
    statusEl.textContent = `Subida completada. Imagen optimizada (-${pct}%).`;
  } else if (statusEl) {
    statusEl.textContent = "Subida completada.";
  }
  return presign;
};

const extractS3KeyFromUrl = (value = "") => {
  const raw = String(value || "").trim();
  if (!raw) return "";
  if (raw.startsWith("s3://")) {
    return raw.slice(5).replace(/^\/+/, "");
  }
  try {
    const u = new URL(raw);
    const host = String(u.hostname || "").toLowerCase();
    const isAws = host.endsWith("amazonaws.com");
    const isS3 = host.includes(".s3.") || host === "s3.amazonaws.com" || host.includes(".s3-");
    if (!isAws || !isS3) return "";
    const key = decodeURIComponent(String(u.pathname || "").replace(/^\/+/, ""));
    return key;
  } catch {
    return "";
  }
};

const buildPhotoSrc = (photoUrl = "") => {
  const raw = String(photoUrl || "").trim();
  if (!raw) return "";
  if (raw.startsWith("data:image/")) return raw;
  if (raw.startsWith("/api/s3_redirect?key=")) return raw;
  const key = extractS3KeyFromUrl(raw);
  if (key) return `/api/s3_redirect?key=${encodeURIComponent(key)}`;
  return raw;
};

const fileToBase64 = (file) =>
  new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = () => reject(new Error("No se pudo leer el archivo."));
    reader.readAsDataURL(file);
  });

const buildSegurosOcrPayload = async (file, statusEl) => {
  const maxInline = 2_000_000;
  if (!file) return null;
  if (file.size > maxInline) {
    try {
      const upload = await uploadFileToS3(file, "seguros", statusEl);
      if (upload?.key) {
        return { s3_key: upload.key, filename: file.name };
      }
    } catch (err) {
      if (statusEl) statusEl.textContent = `Error al subir: ${err.message}`;
      // Intentar fallback a base64 si la subida falla
      try {
        const fileBase64 = await fileToBase64(file);
        return { file_base64: fileBase64, filename: file.name };
      } catch {
        return null;
      }
    }
  }
  const fileBase64 = await fileToBase64(file);
  return { file_base64: fileBase64, filename: file.name };
};

const startSegurosOcrJob = async (payload) =>
  postJsonWithRetryBasic("/api/seguros_ocr_async", payload, {
    maxRetries: 5,
    baseDelayMs: 450,
    timeoutMs: 30000,
  });

const postJsonWithRetryBasic = async (url, payload, options = {}) => {
  const maxRetries = Math.max(1, Number(options.maxRetries || 4));
  const baseDelayMs = Math.max(100, Number(options.baseDelayMs || 300));
  const timeoutMs = Math.max(5000, Number(options.timeoutMs || 30000));
  let lastError = null;
  for (let attempt = 0; attempt < maxRetries; attempt += 1) {
    try {
      const controller =
        typeof AbortController !== "undefined" ? new AbortController() : null;
      const timeoutId = controller
        ? setTimeout(() => controller.abort(), timeoutMs)
        : null;
      const res = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload || {}),
        signal: controller ? controller.signal : undefined,
      });
      if (timeoutId) clearTimeout(timeoutId);
      const text = await res.text();
      let data = {};
      try {
        data = text ? JSON.parse(text) : {};
      } catch (_) {
        data = { error: text || `HTTP ${res.status}` };
      }
      const transient =
        res.status === 502 ||
        res.status === 503 ||
        /database is locked/i.test(String(data?.error || data?.detail || ""));
      if (!res.ok || data?.error) {
        if (transient && attempt < maxRetries - 1) {
          await new Promise((resolve) => setTimeout(resolve, baseDelayMs * (attempt + 1)));
          continue;
        }
      }
      return data;
    } catch (err) {
      lastError = err;
      const timeout = err?.name === "AbortError";
      if (attempt >= maxRetries - 1) {
        if (timeout) throw new Error("Tiempo de espera agotado. Inténtalo de nuevo.");
        throw err;
      }
      await new Promise((resolve) => setTimeout(resolve, baseDelayMs * (attempt + 1)));
    }
  }
  throw lastError || new Error("Error de red");
};

const runSegurosOcrDirectPayload = async (payload, options = {}) =>
  postJsonWithRetryBasic("/api/seguros_ocr", payload, {
    maxRetries: options.maxRetries || 4,
    baseDelayMs: options.baseDelayMs || 450,
    timeoutMs: options.timeoutMs || 120000,
  });

const runSegurosOcrDirect = async (file, extraPayload = {}) => {
  const fileBase64 = await fileToBase64(file);
  return runSegurosOcrDirectPayload({
    ...extraPayload,
    file_base64: fileBase64,
    filename: file.name || "poliza.pdf",
  });
};

const pollOcrJob = async (jobId, onUpdate, timeoutMs = 3 * 60 * 1000) => {
  const started = Date.now();
  let queuedSince = 0;
  let delay = 1200;
  let readErrors = 0;
  while (Date.now() - started < timeoutMs) {
    let data = null;
    try {
      data = await api(`/api/ocr_job?id=${encodeURIComponent(jobId)}`);
      readErrors = 0;
    } catch (_err) {
      readErrors += 1;
      if (readErrors >= 5) {
        throw new Error("Fallo al consultar el estado OCR.");
      }
      await new Promise((resolve) => setTimeout(resolve, delay));
      delay = Math.min(delay + 400, 5000);
      continue;
    }
    const status = data.status === "pending" ? "queued" : data.status;
    if (onUpdate) onUpdate({ ...data, status });
    if (status === "queued") {
      if (!queuedSince) queuedSince = Date.now();
      if (Date.now() - queuedSince > 70 * 1000) {
        throw new Error("Cola OCR saturada.");
      }
    } else if (status === "processing") {
      queuedSince = 0;
    }
    if (status === "done") {
      return data.result || null;
    }
    if (status === "error") {
      throw new Error(data.error || "OCR falló");
    }
    await new Promise((resolve) => setTimeout(resolve, delay));
    delay = Math.min(delay + 300, 4000);
  }
  throw new Error("OCR tardó demasiado");
};

const normalizeServicio = (value) => String(value || "").toLowerCase();

const buildClienteNombreFromTomador = (tomador) => {
  const split = splitNombreApellidos(tomador || "", "Física");
  const apellidos = split.apellidos || "";
  const nombre = split.nombre || "";
  if (apellidos && nombre) return `${apellidos}, ${nombre}`.trim();
  return (tomador || "").trim();
};

const tokenSetFromText = (value) =>
  normalizeName(value)
    .split(/\s+/)
    .filter(Boolean);

const jaccardSimilarity = (a, b) => {
  if (!Array.isArray(a) || !Array.isArray(b) || !a.length || !b.length) return 0;
  const aSet = new Set(a);
  const bSet = new Set(b);
  let inter = 0;
  aSet.forEach((token) => {
    if (bSet.has(token)) inter += 1;
  });
  const union = new Set([...aSet, ...bSet]).size || 1;
  return inter / union;
};

const scoreNameSimilarity = (left, right) => {
  const a = normalizeName(left || "");
  const b = normalizeName(right || "");
  if (!a || !b) return 0;
  if (a === b) return 1;
  if (a.includes(b) || b.includes(a)) return 0.9;
  return jaccardSimilarity(tokenSetFromText(a), tokenSetFromText(b));
};

const buildNameCandidates = (value) => {
  const raw = normalizeName(value || "");
  if (!raw) return [];
  const stopWords = new Set([
    "A",
    "AL",
    "ANTE",
    "CON",
    "DE",
    "DEL",
    "EL",
    "EN",
    "LA",
    "LAS",
    "LOS",
    "PARA",
    "POLIZA",
    "RENOVACION",
    "SEGURO",
    "SU",
    "Y",
  ]);
  const tokens = raw
    .split(/\s+/)
    .filter((token) => token && token.length > 2 && !stopWords.has(token));
  const candidates = [raw];
  if (tokens.length) {
    candidates.push(tokens.join(" "));
    if (tokens.length >= 2) {
      candidates.push(tokens.slice(0, 2).join(" "));
      candidates.push(tokens.slice(-2).join(" "));
    }
  }
  return Array.from(new Set(candidates.filter((item) => item.length >= 3)));
};

const buildRowMap = (row, columns) =>
  columns.reduce((acc, col, idx) => {
    acc[col] = row[idx];
    return acc;
  }, {});

const compareOcrToRow = (rowMap, fields) => {
  const issues = [];
  let score = 100;
  const rowTomador = normalizeName(rowMap.tomador || "");
  const ocrTomador = normalizeName(fields.tomador || "");
  if (rowTomador && ocrTomador) {
    const sim = jaccardSimilarity(tokenSetFromText(rowTomador), tokenSetFromText(ocrTomador));
    if (sim < 0.35) {
      issues.push("Tomador no coincide");
      score -= 15;
    }
  }
  const rowNif = normalizeDocumento(rowMap.nif || rowMap.dni || "");
  const ocrNif = normalizeDocumento(fields.nif || fields.dni || "");
  if (rowNif && ocrNif) {
    if (rowNif !== ocrNif) {
      issues.push("DNI/NIF no coincide");
      score -= 15;
    }
  }
  const rowPoliza = String(rowMap.poliza_numero || "").trim();
  const ocrPoliza = String(fields.poliza_numero || "").trim();
  if (rowPoliza && ocrPoliza) {
    if (rowPoliza !== ocrPoliza) {
      issues.push("Nº póliza no coincide");
      score -= 15;
    }
  }
  const rowComp = resolveCompanyKey(rowMap.compania || "");
  const ocrComp = resolveCompanyKey(fields.compania || "");
  if (rowComp && ocrComp) {
    if (rowComp !== ocrComp) {
      issues.push("Compañía no coincide");
      score -= 12;
    }
  }
  score = Math.max(0, Math.min(100, score));
  return { issues, score };
};

const getOcrLevel = (score, missingCount) => {
  if (missingCount >= 3) return { level: "baja", label: "Baja", color: "#b33b2e" };
  if (score >= 80) return { level: "alta", label: "Alta", color: "#2f7a50" };
  if (score >= 55) return { level: "media", label: "Media", color: "#c4871c" };
  return { level: "baja", label: "Baja", color: "#b33b2e" };
};

const getOrDash = (value) => (value === null || value === undefined || value === "" ? "-" : value);

const showOcrCompareModal = (rowMap, fields, meta = {}) =>
  new Promise((resolve) => {
    let modal = document.getElementById("ocrCompareModal");
    if (!modal) {
      modal = document.createElement("div");
      modal.id = "ocrCompareModal";
      modal.className = "modal";
      modal.innerHTML = `
        <div class="modal-content ocr-compare-content">
          <div class="modal-header">
            <h3>Comparativa OCR</h3>
            <button type="button" class="ghost" data-ocr-close>✕</button>
          </div>
          <div class="modal-body">
            <div class="ocr-compare-summary"></div>
            <div class="ocr-compare-grid"></div>
          </div>
          <div class="modal-actions">
            <button type="button" class="secondary" data-ocr-cancel>Cancelar</button>
            <button type="button" data-ocr-apply>Aplicar OCR</button>
          </div>
        </div>
      `;
      document.body.appendChild(modal);
    }
    const summary = modal.querySelector(".ocr-compare-summary");
    const grid = modal.querySelector(".ocr-compare-grid");
    const closeBtn = modal.querySelector("[data-ocr-close]");
    const cancelBtn = modal.querySelector("[data-ocr-cancel]");
    const applyBtn = modal.querySelector("[data-ocr-apply]");

    const badge = `
      <span class="ocr-badge ${meta.level || "media"}">
        ${meta.label || "Media"} · ${Math.round(meta.score || 0)}%
      </span>
    `;
    const missingText = meta.missing?.length
      ? `Campos faltantes: ${meta.missing.join(", ")}`
      : "OCR completo en campos clave.";
    const issueText = meta.issues?.length
      ? `No coinciden: ${meta.issues.join(", ")}`
      : "Coincidencias principales correctas.";
    summary.innerHTML = `
      <div class="ocr-compare-line">${badge}</div>
      <div class="muted">${missingText}</div>
      <div class="muted">${issueText}</div>
    `;

    const rows = [
      { label: "Tomador", row: rowMap.tomador, ocr: fields.tomador },
      { label: "DNI/NIF", row: rowMap.nif || rowMap.dni, ocr: fields.nif || fields.dni },
      { label: "Compañía", row: rowMap.compania, ocr: fields.compania },
      { label: "Ramo", row: rowMap.ramo, ocr: fields.ramo },
      { label: "Nº póliza", row: rowMap.poliza_numero, ocr: fields.poliza_numero },
      { label: "Fecha efecto", row: rowMap.fecha_efecto, ocr: fields.fecha_efecto },
      { label: "Fecha vencimiento", row: rowMap.fecha_vencimiento, ocr: fields.fecha_vencimiento },
      { label: "Prima total", row: rowMap.prima_total, ocr: fields.prima_total },
    ];
    grid.innerHTML = rows
      .map(
        (row) => `
        <div class="ocr-compare-row">
          <div class="ocr-compare-label">${row.label}</div>
          <div class="ocr-compare-val">${getOrDash(row.row)}</div>
          <div class="ocr-compare-val">${getOrDash(row.ocr)}</div>
        </div>
      `
      )
      .join("");

    const close = (value) => {
      modal.classList.remove("open");
      modal.classList.add("hidden");
      resolve(value);
    };

    closeBtn.onclick = () => close(false);
    cancelBtn.onclick = () => close(false);
    applyBtn.onclick = () => close(true);

    modal.classList.remove("hidden");
    modal.classList.add("open");
  });

const runSegurosBdtRowOcr = async (recordId, file, statusEl, rowMap = {}) => {
  if (!recordId || !file) return;
  if (statusEl) statusEl.textContent = "Procesando OCR...";
  let data;
  try {
    const payload = await buildSegurosOcrPayload(file, statusEl);
    if (!payload) return;
    const job = await startSegurosOcrJob(payload);
    if (!job || job.error || !job.job_id) {
      if (statusEl) statusEl.textContent = job?.detail || job?.error || "No se pudo iniciar OCR.";
      return;
    }
    if (statusEl) statusEl.textContent = "OCR en cola...";
    data = await pollOcrJob(job.job_id, (row) => {
      if (statusEl && row.status === "processing") {
        statusEl.textContent = "Procesando OCR...";
      }
    });
  } catch (err) {
    if (statusEl) statusEl.textContent = err?.message || "Error al procesar OCR.";
    return;
  }
  if (data?.error) {
    if (statusEl) statusEl.textContent = data.detail || data.error || "OCR falló.";
    return;
  }
  const fields = data.fields || {};
  const required = ["tomador", "compania", "poliza_numero", "fecha_efecto"];
  const missing = required.filter((key) => !String(fields[key] || "").trim());
  const compare = compareOcrToRow(rowMap, fields);
  const levelMeta = getOcrLevel(compare.score, missing.length);
  if (statusEl) {
    statusEl.innerHTML = `<span class="ocr-badge ${levelMeta.level}">${levelMeta.label}</span>`;
  }
  const ok = await showOcrCompareModal(rowMap, fields, {
    missing,
    issues: compare.issues,
    score: compare.score,
    level: levelMeta.level,
    label: levelMeta.label,
  });
  if (!ok) return;
  const enrichPayload = { empresa_nombre: FINCAS_COMPANY, id: recordId, ...fields };
  if (fields.nif || fields.dni) {
    const lookup = await lookupClienteByNif(fields.nif || fields.dni);
    if (lookup?.found) {
      enrichPayload.cliente_id = lookup.cliente?.id || "";
    }
  }
  let upload = null;
  try {
    upload = await uploadFileToS3(file, "seguros", statusEl);
  } catch (err) {
    if (statusEl) statusEl.textContent = `OCR aplicado. Error al subir: ${err.message}`;
  }
  try {
    await apiPost("/api/seguros_enrich", enrichPayload);
  } catch {
    if (statusEl) statusEl.textContent = "OCR aplicado, pero falló al actualizar el registro.";
    return;
  }
  if (upload && upload.key) {
   await apiPost("/api/seguros_update", {
      empresa_nombre: FINCAS_COMPANY,
      id: recordId,
      poliza_key: upload.key,
      poliza_url: upload.public_url || "",
   });
  }
  if (statusEl) statusEl.textContent = "OCR aplicado y póliza cargada.";
  loadSegurosCrm();
};

const showClienteDocOcrModal = (fields = {}, meta = {}) =>
  new Promise((resolve) => {
    let modal = document.getElementById("clienteDocOcrModal");
    if (!modal) {
      modal = document.createElement("div");
      modal.id = "clienteDocOcrModal";
      modal.className = "modal";
      modal.innerHTML = `
        <div class="modal-content ocr-compare-content">
          <div class="modal-header">
            <h3>OCR póliza cliente</h3>
            <button type="button" class="ghost" data-cliente-ocr-close>✕</button>
          </div>
          <div class="modal-body">
            <p class="muted cliente-ocr-hint"></p>
            <div class="ocr-compare-grid cliente-ocr-grid"></div>
          </div>
          <div class="modal-actions">
            <button type="button" class="secondary" data-cliente-ocr-cancel>Cancelar</button>
            <button type="button" data-cliente-ocr-save>Guardar en Seguros</button>
          </div>
        </div>
      `;
      document.body.appendChild(modal);
    }
    const hintEl = modal.querySelector(".cliente-ocr-hint");
    const grid = modal.querySelector(".cliente-ocr-grid");
    const closeBtn = modal.querySelector("[data-cliente-ocr-close]");
    const cancelBtn = modal.querySelector("[data-cliente-ocr-cancel]");
    const saveBtn = modal.querySelector("[data-cliente-ocr-save]");
    if (hintEl) {
      const quality = meta.qualityLabel || "";
      hintEl.textContent = quality
        ? `Revisa los campos antes de guardar. Calidad OCR: ${quality}.`
        : "Revisa y corrige los campos antes de guardar.";
    }
    const inputRows = [
      ["tomador", "Tomador"],
      ["dni", "DNI/NIF"],
      ["compania", "Compañía"],
      ["ramo", "Ramo"],
      ["poliza_numero", "Nº póliza"],
      ["fecha_efecto", "Fecha efecto"],
      ["fecha_vencimiento", "Fecha vencimiento"],
      ["direccion", "Dirección riesgo"],
      ["prima_neta", "Prima neta"],
      ["prima_total", "Prima total"],
    ];
    grid.innerHTML = "";
    inputRows.forEach(([key, label]) => {
      const rawValue = fields[key] || "";
      const value = key.startsWith("fecha_")
        ? normalizeDateInput(rawValue)
        : String(rawValue || "");
      const type = key.startsWith("fecha_") ? "date" : "text";
      const line = document.createElement("label");
      line.className = "ocr-compare-row";
      const labelEl = document.createElement("span");
      labelEl.className = "ocr-compare-label";
      labelEl.textContent = label;
      const input = document.createElement("input");
      input.type = type;
      input.value = value;
      input.setAttribute("data-cliente-ocr-field", key);
      line.appendChild(labelEl);
      line.appendChild(input);
      grid.appendChild(line);
    });

    const close = (value) => {
      modal.classList.remove("open");
      modal.classList.add("hidden");
      resolve(value);
    };
    closeBtn.onclick = () => close(null);
    cancelBtn.onclick = () => close(null);
    saveBtn.onclick = () => {
      const out = {};
      inputRows.forEach(([key]) => {
        const input = modal.querySelector(`[data-cliente-ocr-field="${key}"]`);
        out[key] = input ? String(input.value || "").trim() : "";
      });
      if (out.fecha_efecto && !out.fecha_vencimiento) {
        out.fecha_vencimiento = addOneYear(out.fecha_efecto);
      }
      close(out);
    };
    modal.classList.remove("hidden");
    modal.classList.add("open");
  });

const postJsonWithDbRetry = async (url, payload, options = {}) => {
  const maxRetries = Math.max(1, Number(options.maxRetries || 5));
  const baseDelayMs = Math.max(50, Number(options.baseDelayMs || 350));
  const timeoutMs = Math.max(3000, Number(options.timeoutMs || 20000));
  let lastError = null;
  for (let attempt = 0; attempt < maxRetries; attempt += 1) {
    try {
      const controller =
        typeof AbortController !== "undefined" ? new AbortController() : null;
      const timeoutId = controller
        ? setTimeout(() => controller.abort(), timeoutMs)
        : null;
      const res = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload || {}),
        signal: controller ? controller.signal : undefined,
      });
      if (timeoutId) {
        clearTimeout(timeoutId);
      }
      const text = await res.text();
      let data = {};
      try {
        data = text ? JSON.parse(text) : {};
      } catch (_) {
        data = { error: text || `HTTP ${res.status}` };
      }
      const errText = String(data?.error || data?.detail || "");
      const locked = /database is locked/i.test(errText) || res.status === 502 || res.status === 503;
      if (!res.ok || data?.error) {
        if (locked && attempt < maxRetries - 1) {
          await new Promise((resolve) => setTimeout(resolve, baseDelayMs * (attempt + 1)));
          continue;
        }
        throw new Error(data?.error || data?.detail || `HTTP ${res.status}`);
      }
      return data;
    } catch (err) {
      lastError = err;
      const isLocked = /database is locked/i.test(String(err?.message || ""));
      const isTimeout = err?.name === "AbortError";
      if ((!isLocked && !isTimeout) || attempt >= maxRetries - 1) {
        if (isTimeout) {
          throw new Error("Tiempo de espera agotado. Inténtalo de nuevo.");
        }
        throw err;
      }
      await new Promise((resolve) => setTimeout(resolve, baseDelayMs * (attempt + 1)));
    }
  }
  throw lastError || new Error("Error de base de datos");
};

const runClienteSegurosDocOcr = async (row, statusEl, buttonEl) => {
  if (!row) return;
  if (buttonEl) buttonEl.disabled = true;
  const setStatus = (text) => {
    if (statusEl) statusEl.textContent = text;
  };
  const docKey = String(row.doc_key || "").trim();
  if (!docKey) {
    setStatus("Documento sin clave S3. Sube el archivo desde CRM Seguros para usar OCR.");
    if (buttonEl) buttonEl.disabled = false;
    return;
  }
  try {
    setStatus("Procesando OCR...");
    const job = await startSegurosOcrJob({
      s3_key: docKey,
      filename: row.nombre || "poliza.pdf",
    });
    let result = null;
    if (!job || job.error || !job.job_id) {
      setStatus("OCR en cola falló. Reintentando en modo directo...");
      result = await runSegurosOcrDirectPayload(
        { s3_key: docKey, filename: row.nombre || "poliza.pdf" },
        { timeoutMs: 180000 }
      );
    } else {
      result = await pollOcrJob(job.job_id, (jobRow) => {
        if (jobRow.status === "processing") {
          setStatus("Leyendo póliza...");
        }
      });
    }
    if (!result || result.error) {
      setStatus(result?.detail || result?.error || "OCR sin datos.");
      return;
    }
    const extracted = result.fields || {};
    const quality = result.ocr_quality || {};
    const edited = await showClienteDocOcrModal(extracted, {
      qualityLabel: quality.calidad || "",
    });
    if (!edited) {
      setStatus("OCR cancelado.");
      return;
    }
    const now = new Date();
    const mesCreacion = now.toLocaleString("es-ES", { month: "long" });
    const payloadBase = {
      cliente_id: state.currentClienteId || row.cliente_id || "",
      tomador: edited.tomador || "",
      compania: edited.compania || "",
      ramo: edited.ramo || "",
      poliza_numero: edited.poliza_numero || "",
      fecha_efecto: edited.fecha_efecto || "",
      fecha_vencimiento: edited.fecha_vencimiento || "",
      prima_neta: toNumber(edited.prima_neta || ""),
      prima_total: toNumber(edited.prima_total || ""),
      poliza_key: docKey,
      poliza_url: row.doc_url || "",
      ocr_quality: quality,
      calidad_ocr: quality.calidad || "",
      campos_ocr: Array.isArray(quality.campos) ? quality.campos.join(",") : "",
    };
    if (!payloadBase.cliente_id) {
      setStatus("Cliente no identificado en la ficha.");
      return;
    }
    let seguroId = String(row.seguro_id || row.referencia_id || "").trim();
    if (seguroId) {
      const enrichResp = await postJsonWithDbRetry("/api/seguros_enrich", {
          empresa_nombre: FINCAS_COMPANY,
          id: seguroId,
          cliente_id: payloadBase.cliente_id,
          tomador: payloadBase.tomador,
          compania: payloadBase.compania,
          ramo: payloadBase.ramo,
          poliza_numero: payloadBase.poliza_numero,
          fecha_efecto: payloadBase.fecha_efecto,
          fecha_vencimiento: payloadBase.fecha_vencimiento,
          prima_neta: payloadBase.prima_neta,
          prima_total: payloadBase.prima_total,
      });
      if (enrichResp?.error) {
        throw new Error(enrichResp.error);
      }
      const updateResp = await postJsonWithDbRetry("/api/seguros_update", {
          empresa_nombre: FINCAS_COMPANY,
          id: seguroId,
          cliente_id: payloadBase.cliente_id,
          poliza_numero: payloadBase.poliza_numero,
          fecha_efecto: payloadBase.fecha_efecto,
          fecha_vencimiento: payloadBase.fecha_vencimiento,
          poliza_key: payloadBase.poliza_key,
          poliza_url: payloadBase.poliza_url,
      });
      if (updateResp?.error) {
        throw new Error(updateResp.error);
      }
    } else {
      const createResp = await postJsonWithDbRetry("/api/seguros", {
          empresa_nombre: FINCAS_COMPANY,
          cliente_id: payloadBase.cliente_id,
          mes_creacion: mesCreacion,
          estado: "Contratada",
          tomador: payloadBase.tomador,
          compania: payloadBase.compania,
          ramo: payloadBase.ramo,
          poliza_numero: payloadBase.poliza_numero,
          fecha_efecto: payloadBase.fecha_efecto,
          fecha_vencimiento: payloadBase.fecha_vencimiento,
          prima_neta: payloadBase.prima_neta,
          prima_total: payloadBase.prima_total,
          poliza_key: payloadBase.poliza_key,
          poliza_url: payloadBase.poliza_url,
          ocr_quality: payloadBase.ocr_quality,
      });
      if (createResp?.error) {
        throw new Error(createResp.error);
      }
      seguroId = String(createResp.id || "").trim();
    }
    if (row.id) {
      await postJsonWithDbRetry("/api/gestoria_docs_update", {
        id: row.id,
        referencia_tipo: "seguros",
        referencia_id: seguroId || row.referencia_id || "",
        estado: "Recibido",
        calidad_ocr: payloadBase.calidad_ocr,
        campos_ocr: payloadBase.campos_ocr,
      });
    }
    setStatus("Póliza procesada y vinculada.");
    if (state.currentClienteId) {
      openClienteDetail(state.currentClienteId);
    }
  } catch (err) {
    setStatus(err?.message || "Error al aplicar OCR.");
  } finally {
    if (buttonEl) buttonEl.disabled = false;
  }
};

const openS3File = async (key, fallbackUrl) => {
  let popup = null;
  try {
    // Abrimos primero para evitar bloqueo de popups tras await.
    popup = window.open("", "_blank", "noopener");
  } catch {}
  if (key) {
    const data = await api(`/api/s3_url?key=${encodeURIComponent(key)}`);
    if (data && data.url) {
      if (popup) {
        popup.location.href = data.url;
      } else {
        window.open(data.url, "_blank", "noopener");
      }
      return;
    }
  }
  if (fallbackUrl) {
    if (popup) {
      popup.location.href = fallbackUrl;
    } else {
      window.open(fallbackUrl, "_blank", "noopener");
    }
    return;
  }
  if (popup) {
    popup.close();
  }
};

const getCurrentUser = () => {
  if (state.currentUser) {
    return state.currentUser;
  }
  const saved = localStorage.getItem("crm_current_user");
  if (saved) {
    state.currentUser = saved;
    return saved;
  }
  return "";
};

const setCurrentUser = (name) => {
  state.currentUser = name || "";
  if (state.currentUser) {
    localStorage.setItem("crm_current_user", state.currentUser);
  } else {
    localStorage.removeItem("crm_current_user");
  }
};

const UI = window.CRMUI || null;
const AuthModule = window.CRMAppAuth || null;
const RoutingModule = window.CRMAppRouting || null;

// Diagnóstico mínimo para no quedarnos con pantallas "vacías" sin feedback.
// En Render, si hay un error JS, lo mostramos en un banner visible.
(function setupClientDiagnostics() {
  const banner = document.getElementById("uiErrorToast") || document.getElementById("renewalAlert");
  if (!banner) return;
	const show = (title, detail) => {
    try {
      banner.classList.remove("hidden");
      banner.innerHTML = "";
      const strong = document.createElement("strong");
      strong.textContent = title;
      const pre = document.createElement("pre");
      pre.style.whiteSpace = "pre-wrap";
      pre.style.marginTop = "8px";
      pre.textContent = String(detail || "").slice(0, 2000);
      banner.appendChild(strong);
      if (detail) banner.appendChild(pre);
    } catch {}
  };
  window.addEventListener("error", (event) => {
    const err = event?.error;
    const detail = (err?.message ? `${err.message}\n` : "")
      + (err?.stack || event?.message || "Error desconocido");
    show("Error en la interfaz", detail);
  });
	  window.addEventListener("unhandledrejection", (event) => {
	    const reason = event?.reason;
	    const isAuthError =
	      (reason && Number(reason.status || 0) === 401)
	      || (reason && reason.isAuthError === true)
	      || /no autenticad/i.test(String(reason?.message || reason || ""));
	    const isPermissionError =
	      (reason && Number(reason.status || 0) === 403)
	      || /sin permisos para este servicio/i.test(String(reason?.message || reason || ""));
	    // Si expira sesión y alguna promesa no la captura, evitamos ensuciar la UI:
	    // `api()` ya llama a `handleAuthExpired()` en 401.
	    if (isAuthError) {
	      try {
	        event.preventDefault();
	      } catch {}
	      return;
	    }
	    // Si el backend bloquea una llamada por permisos, no debe romper la experiencia con un banner global.
	    // Esto suele ocurrir en widgets opcionales (cross-servicio) y debe fallar de forma silenciosa.
	    if (isPermissionError) {
	      try {
	        console.warn("Promise rejection ignored (permissions):", reason);
	      } catch {}
	      try {
	        event.preventDefault();
	      } catch {}
	      return;
	    }
	    const detail = (reason?.message ? `${reason.message}\n` : "")
	      + (reason?.stack || String(reason || "Promise rechazada"));
	    show("Error interno (promesa)", detail);
	    try {
      // Safari/Chrome: evita el mensaje "Unhandled Promise Rejection" en consola cuando ya lo mostramos en UI.
      event.preventDefault();
    } catch {}
  });
})();

