const syncWorkspaceClientOptions = (rows = []) => {
  state.workspaceClientOptions = Array.isArray(rows) ? rows : [];
  state.workspaceClientOptionMap = new Map();
  state.workspaceClientOptionById = new Map();
  if (!workspaceClientOptions) return;
  workspaceClientOptions.innerHTML = state.workspaceClientOptions
    .map((row) => {
      const label = `${row.nombre || "-"}${row.nif ? ` · ${row.nif}` : ""}`;
      state.workspaceClientOptionMap.set(label, row);
      state.workspaceClientOptionById.set(String(row.id || ""), row);
      return `<option value="${label}"></option>`;
    })
    .join("");
};

const findWorkspaceClientByLookup = (lookup = "", clienteId = "") => {
  const idKey = String(clienteId || "").trim();
  if (idKey && state.workspaceClientOptionById instanceof Map && state.workspaceClientOptionById.has(idKey)) {
    return state.workspaceClientOptionById.get(idKey) || null;
  }
  const label = String(lookup || "").trim();
  if (label && state.workspaceClientOptionMap instanceof Map && state.workspaceClientOptionMap.has(label)) {
    return state.workspaceClientOptionMap.get(label) || null;
  }
  const normalized = normalizeSimple(label);
  if (!normalized) return null;
  return (state.workspaceClientOptions || []).find((row) => {
    const rowLabel = `${row.nombre || ""}${row.nif ? ` · ${row.nif}` : ""}`;
    return normalizeSimple(rowLabel) === normalized || normalizeSimple(row.nombre || "") === normalized;
  }) || null;
};

const fetchWorkspaceClientOptions = async (query = "") => {
  if (!state.currentWorkspaceId) return;
  const params = new URLSearchParams({ workspace_id: state.currentWorkspaceId, limit: "60" });
  if (query) params.set("q", query);
  const data = await api(`/api/workspace_clientes?${params.toString()}`);
  syncWorkspaceClientOptions(data.rows || []);
};

const loadWorkspaceClients = async (query = "") => {
  if (!state.currentWorkspaceId) return [];
  const params = new URLSearchParams({ workspace_id: state.currentWorkspaceId, limit: "120" });
  if (query) params.set("q", query);
  const data = await api(`/api/workspace_clientes?${params.toString()}`);
  const rows = Array.isArray(data.rows) ? data.rows : [];
  state.currentWorkspaceClients = rows;
  syncWorkspaceClientOptions(rows);
  renderWorkspaceClientBase(rows);
  const currentId = String(state.currentWorkspaceClientId || "");
  const stillExists = rows.some((row) => String(row.id || "") === currentId);
  if (stillExists && currentId) {
    openWorkspaceClient360(currentId, { silent: true }).catch(() => {});
  } else if (rows.length) {
    openWorkspaceClient360(rows[0].id, { prefetchedRow: rows[0], silent: true }).catch(() => {});
  } else {
    state.currentWorkspaceClientId = "";
    state.currentWorkspaceClientData = null;
    renderWorkspaceClientDetail(null);
  }
  return rows;
};

const getWorkspaceEnabledModules = (modules = []) =>
  modules.filter((row) => Number(row.enabled || 0) === 1).map((row) => row.modulo_key);

const renderWorkspaceKpis = (summary = {}) => {
  if (!workspaceKpis) return;
  const items = [
    ["Workspaces", summary.workspaces_total || 0, "Clientes operativos"],
    ["Empresas operativas", summary.empresas_total || 0, "Sociedades enlazadas a workspaces"],
    ["Módulos activos", summary.modulos_activos_total || 0, "Capacidades habilitadas"],
  ];
  workspaceKpis.innerHTML = items
    .map(
      ([title, value, subtitle]) => `
        <div class="card kpi-card">
          <h3>${title}</h3>
          <div class="kpi-value">${numberFormatter.format(Number(value) || 0)}</div>
          <div class="muted">${subtitle}</div>
        </div>
      `
    )
    .join("");
};

const renderWorkspaceHealth = (data = {}) => {
  if (workspaceHealthScore) {
    const score = Number(data.readiness_score || 0);
    const summary = data.summary || {};
    const companyLabel = getWorkspaceCompanyContextLabel();
    workspaceHealthScore.innerHTML = `
      <div class="workspace-health-score-card">
          <div class="workspace-health-ring">${score}%</div>
          <div>
          <strong>Readiness de ${companyLabel}</strong>
          <div class="muted">
            ${numberFormatter.format(Number(summary.clientes || 0))} clientes finales ·
            ${numberFormatter.format(Number(summary.documentos || 0))} documentos ·
            ${numberFormatter.format(Number(summary.facturas || 0))} movimientos
          </div>
        </div>
      </div>
    `;
  }
  if (workspaceChecklist) {
    const items = Array.isArray(data.checklist) ? data.checklist : [];
    workspaceChecklist.innerHTML = items.length
      ? `
          <div class="workspace-checklist">
            ${items
              .map(
                (item) => `
                  <div class="workspace-check-item${Number(item.done || 0) === 1 ? " is-done" : ""}">
                    <strong>${item.label || "-"}</strong>
                    <div class="muted">${item.hint || ""}</div>
                  </div>
                `
              )
              .join("")}
          </div>
        `
      : "<p class='muted'>Sin checklist disponible.</p>";
  }
  if (workspaceModuleHealth) {
    const rows = Array.isArray(data.module_health) ? data.module_health : [];
    workspaceModuleHealth.innerHTML = rows.length
      ? `
          <div class="workspace-module-health-list">
            ${rows
              .map(
                (row) => `
                  <div class="workspace-module-health-row status-${row.status || "disabled"}">
                    <div>
                      <strong>${row.nombre || row.key || "-"}</strong>
                      <div class="muted">${row.metric_value || 0} ${row.metric_label || ""}</div>
                    </div>
                    <div class="workspace-module-health-meta">
                      <span>${row.enabled ? (row.status || "activo") : "desactivado"}</span>
                      <span>${row.next_step || ""}</span>
                    </div>
                  </div>
                `
              )
              .join("")}
          </div>
        `
      : "<p class='muted'>Sin módulos evaluados.</p>";
  }
  if (workspaceOnboardingActions) {
    const status = String(data.go_live_status || "bloqueado");
    const actions = Array.isArray(data.onboarding_actions) ? data.onboarding_actions : [];
    const badge = status === "listo" ? "Listo para go-live" : status === "implantacion" ? "En implantación" : "Bloqueado";
    workspaceOnboardingActions.innerHTML = `
      <div class="workspace-document-head">
        <span class="workspace-document-total">${badge}</span>
        <span class="muted">${actions.length ? `${actions.length} acciones recomendadas` : "Sin bloqueos prioritarios"}</span>
      </div>
      ${
        actions.length
          ? `
              <div class="workspace-billing-list">
                ${actions
                  .map(
                    (item) => `
                      <div class="workspace-billing-row">
                        <div>
                          <strong>${item.label || "-"}</strong>
                          <div class="muted">Prioridad ${item.priority || "media"}</div>
                        </div>
                        <div class="workspace-billing-meta">
                          <button type="button" class="secondary ghost" data-workspace-jump="${item.target || ""}">Ir</button>
                        </div>
                      </div>
                    `
                  )
                  .join("")}
              </div>
            `
          : "<p class='muted'>El workspace ya tiene una base suficiente para implantación comercial.</p>"
      }
    `;
    workspaceOnboardingActions.querySelectorAll("[data-workspace-jump]").forEach((button) => {
      button.addEventListener("click", () => {
        const target = document.getElementById(button.dataset.workspaceJump || "");
        target?.scrollIntoView({ behavior: "smooth", block: "start" });
      });
    });
  }
};

