  workspaceRrhhHub.querySelectorAll("[data-rrhh-roster-save]").forEach((button) => {
    button.addEventListener("click", async () => {
      if (!isWorkspaceRrhhManager()) return;
      const userId = String(button.dataset.rrhhRosterSave || "").trim();
      if (!userId) return;
      const row = button.closest("[data-rrhh-roster-user]");
      if (!row) return;
      const status = workspaceRrhhHub.querySelector("#workspaceRrhhRosterStatus");
      const empresaId = String(row.querySelector("[data-rrhh-roster-empresa]")?.value || "").trim();
      const nif = String(row.querySelector("[data-rrhh-roster-nif]")?.value || "").trim();
      const email = String(row.querySelector("[data-rrhh-roster-email]")?.value || "").trim();
      const telefono = String(row.querySelector("[data-rrhh-roster-telefono]")?.value || "").trim();
      const jornada = String(row.querySelector("[data-rrhh-roster-jornada]")?.value || "Completa").trim();
      const horas = String(row.querySelector("[data-rrhh-roster-horas]")?.value || "").trim();
      const activo = row.querySelector("[data-rrhh-roster-activo]")?.checked ? 1 : 0;
      if (!empresaId) {
        if (status) status.textContent = "Selecciona empresa antes de guardar.";
        return;
      }
      const user = getWorkspaceTimeEligibleUsers().find((u) => String(u.id || "").trim() === userId) || null;
      const fullName = `${user?.nombre || ""} ${user?.apellido || ""}`.trim() || user?.usuario || user?.email || "";
      const employees = Array.isArray(state.workspaceTimeEmployees) ? state.workspaceTimeEmployees : [];
      const existing = employees.find((e) => Number(e.usuario_manual || 0) === 1 && String(e.usuario_id || "").trim() === userId) || null;
      button.disabled = true;
      try {
        if (status) status.textContent = "Guardando ficha...";
        await apiPost("/api/workspace_registro_personal", {
          id: existing?.id || "",
          workspace_id: state.currentWorkspaceId,
          empresa_id: empresaId,
          usuario_id: userId,
          nombre: fullName || existing?.nombre || "Empleado",
          nif: nif || existing?.nif || "",
          email: email || user?.email || existing?.email || "",
          telefono: telefono || existing?.telefono || "",
          tipo_jornada: jornada,
          horas_pactadas_dia: horas,
          activo,
          empresa_manual: 1,
        });
        if (status) status.textContent = "Ficha guardada.";
        upsertWorkspaceEmployeeLocal({
          id: existing?.id || "",
          workspace_id: state.currentWorkspaceId,
          empresa_id: empresaId,
          empresa_nombre: (state.currentWorkspaceDetail?.companies || []).find((c) => String(c.id || "") === String(empresaId || ""))?.nombre || "",
          usuario_id: userId,
          usuario_manual: 1,
          nombre: fullName || existing?.nombre || "Empleado",
          nif: nif || existing?.nif || "",
          email: email || user?.email || existing?.email || "",
          telefono: telefono || existing?.telefono || "",
          tipo_jornada: jornada,
          horas_pactadas_dia: horas,
          activo,
          empresa_manual: 1,
        });
        renderWorkspaceRrhhHub();
        await refreshWorkspaceTimeSetup();
        renderCompanyCards();
        await refreshWorkspaceRrhh();
      } catch (error) {
        if (status) status.textContent = error.message || "No se pudo guardar.";
      } finally {
        button.disabled = false;
      }
    });
  });

  workspaceRrhhHub.querySelectorAll("[data-rrhh-persona]").forEach((btn) => {
    btn.addEventListener("click", async () => {
      const personaId = String(btn.dataset.rrhhPersona || "").trim();
      if (!personaId) return;
      // Si estamos dentro de la ficha de un miembro, navegar desde la barra lateral debe
      // cambiar realmente la ficha (si no, parece que “se quedan” los datos del anterior).
      if (isWorkspaceRrhhManager() && String(state.workspaceRrhhEquipoView || "") === "member") {
        const employees = Array.isArray(state.workspaceTimeEmployees) ? state.workspaceTimeEmployees : [];
        const emp = employees.find((row) => String(row?.id || "").trim() === personaId) || null;
        const userId = emp && Number(emp.usuario_manual || 0) === 1 ? String(emp.usuario_id || "").trim() : "";
        state.workspaceRrhhEquipoView = "member";
        state.workspaceRrhhEquipoMemberKey = `emp:${personaId}`;
        state.workspaceRrhhEquipoMemberPersonaId = personaId;
        state.workspaceRrhhEquipoMemberUserId = userId;
        state.workspaceRrhhEquipoMemberTab = state.workspaceRrhhEquipoMemberTab || "personal";
      }
      state.workspaceRrhhSelectedPersonaId = personaId;
      state.workspaceRrhhScopeAll = false;
      await refreshWorkspaceRrhh();
    });
  });

  workspaceRrhhHub.querySelectorAll("[data-rrhh-open-time]").forEach((button) => {
    button.addEventListener("click", () => {
      focusWorkspaceEngine("registro_horario", workspaceTimeSummary, { forceTenantView: true });
    });
  });

  const payrollBtn = workspaceRrhhHub.querySelector("[data-rrhh-payroll-export]");
  if (payrollBtn) {
    payrollBtn.addEventListener("click", () => {
      if (!isWorkspaceRrhhManager()) return;
      if (!state.currentWorkspaceId) return;
      const month = normalizeMonthValue(state.workspaceRrhhMonth || state.workspaceTimeMonth || "");
      if (!month) {
        alert("Selecciona un mes para exportar.");
        return;
      }
      const companyQuery = state.currentWorkspaceCompanyId ? `&empresa_id=${encodeURIComponent(state.currentWorkspaceCompanyId)}` : "";
      const url = `/api/workspace_rrhh_payroll_export?workspace_id=${encodeURIComponent(state.currentWorkspaceId)}&month=${encodeURIComponent(month)}${companyQuery}`;
      window.open(url, "_blank");
    });
  }

  const employeeSearch = workspaceRrhhHub.querySelector("#workspaceRrhhEmployeeSearch");
