const stringifyWorkspaceBudgetLines = (lines = []) =>
  (Array.isArray(lines) ? lines : [])
    .map((line) => [
      line.categoria || "",
      line.concepto || "",
      Number(line.cantidad || 0) || 0,
      line.unidad || "",
      Number(line.precio_unitario || 0) || 0,
      Number(line.descuento_pct || 0) || 0,
    ].join(" | "))
    .join("\n");

const computeWorkspaceBudgetTotals = ({ servicio = "", subtotal = "", impuestos = "", lineas = [], num_vecinos = "", num_locales = "", num_trasteros = "", num_aparcamientos = "" } = {}) => {
  const normalizedService = String(servicio || "").trim().toLowerCase();
  const lineSubtotal = (Array.isArray(lineas) ? lineas : []).reduce((sum, line) => {
    const cantidad = Number(line.cantidad || 0) || 0;
    const precio = Number(line.precio_unitario || 0) || 0;
    const dto = Math.max(0, Math.min(100, Number(line.descuento_pct || 0) || 0));
    return sum + cantidad * precio * (1 - dto / 100);
  }, 0);
  const fincasSuggested = Math.max(
    60,
    (Number(num_vecinos || 0) || 0) * 5
      + (Number(num_locales || 0) || 0)
      + (Number(num_trasteros || 0) || 0)
      + (Number(num_aparcamientos || 0) || 0)
  );
  const suggested = normalizedService === "fincas" ? (lineSubtotal > 0 ? lineSubtotal : fincasSuggested) : lineSubtotal;
  const manualSubtotal = Number(subtotal || 0) || 0;
  const effectiveSubtotal = manualSubtotal > 0 ? manualSubtotal : suggested;
  const tax = Number(impuestos || 0) || 0;
  return {
    suggested: Number(suggested.toFixed(2)),
    subtotal: Number(effectiveSubtotal.toFixed(2)),
    total: Number((effectiveSubtotal + tax).toFixed(2)),
  };
};

const syncWorkspaceBudgetComputedFields = ({ forceSubtotal = false, forceTotal = false } = {}) => {
  if (!workspaceBudgetForm) return;
  const linesText = workspaceBudgetForm.querySelector('[name="lineas_texto"]')?.value || "";
  const subtotalInput = workspaceBudgetForm.querySelector('[name="subtotal"]');
  const totalInput = workspaceBudgetForm.querySelector('[name="total"]');
  const suggestedInput = workspaceBudgetForm.querySelector('[name="subtotal_sugerido"]');
  const lineas = parseWorkspaceBudgetLinesText(linesText);
  const computed = computeWorkspaceBudgetTotals({
    servicio: workspaceBudgetForm.querySelector('[name="servicio"]')?.value,
    subtotal: subtotalInput?.value,
    impuestos: workspaceBudgetForm.querySelector('[name="impuestos"]')?.value,
    lineas,
    num_vecinos: workspaceBudgetForm.querySelector('[name="num_vecinos"]')?.value,
    num_locales: workspaceBudgetForm.querySelector('[name="num_locales"]')?.value,
    num_trasteros: workspaceBudgetForm.querySelector('[name="num_trasteros"]')?.value,
    num_aparcamientos: workspaceBudgetForm.querySelector('[name="num_aparcamientos"]')?.value,
  });
  if (suggestedInput) suggestedInput.value = computed.suggested.toFixed(2);
  if (subtotalInput && (forceSubtotal || !subtotalInput.value)) subtotalInput.value = computed.subtotal.toFixed(2);
  if (totalInput && (forceTotal || !totalInput.value)) totalInput.value = computed.total.toFixed(2);
  const hiddenLines = workspaceBudgetForm.querySelector('[name="lineas"]');
  if (hiddenLines) hiddenLines.value = JSON.stringify(lineas);
};

const renderWorkspaceBudgetSummary = (rows = []) => {
  if (!workspaceBudgetSummary) return;
  const items = Array.isArray(rows) ? rows : [];
  const total = items.reduce((sum, row) => sum + (Number(row.total || 0) || 0), 0);
  const accepted = items.filter((row) => String(row.estado || "").toLowerCase() === "aceptado").length;
  const estudio = items.filter((row) => normalizeSimple(row.estado || "") === "estudio").length;
  const rejected = items.filter((row) => normalizeSimple(row.estado || "") === "rechazado").length;
  const encargoPending = items.filter((row) => normalizeSimple(row.estado || "") === "aceptado" && !["firmada", "firmado"].includes(normalizeSimple(row.encargo_estado || ""))).length;
  workspaceBudgetSummary.innerHTML = `
    <div class="workspace-mini-kpis">
      <div class="workspace-mini-kpi"><span>Presupuestos</span><strong>${numberFormatter.format(items.length)}</strong></div>
      <div class="workspace-mini-kpi"><span>Total propuesto</span><strong>${euroFormatter.format(total)}</strong></div>
      <div class="workspace-mini-kpi"><span>Aceptados</span><strong>${numberFormatter.format(accepted)}</strong></div>
      <div class="workspace-mini-kpi"><span>En estudio</span><strong>${numberFormatter.format(estudio)}</strong></div>
      <div class="workspace-mini-kpi"><span>Rechazados</span><strong>${numberFormatter.format(rejected)}</strong></div>
      <div class="workspace-mini-kpi"><span>Encargo pendiente</span><strong>${numberFormatter.format(encargoPending)}</strong></div>
    </div>
  `;
};

const getWorkspaceBudgetTemplatesForService = (service) => {
  const key = String(service || "").trim().toLowerCase();
  return WORKSPACE_BUDGET_TEMPLATES[key] || WORKSPACE_BUDGET_TEMPLATES.gestoria;
};

const applyWorkspaceBudgetServiceMode = () => {
  if (!workspaceBudgetForm) return;
  const service = String(workspaceBudgetForm.querySelector('[name="servicio"]')?.value || "gestoria").trim().toLowerCase();
  const templates = getWorkspaceBudgetTemplatesForService(service);
  if (workspaceBudgetTemplateSelect) {
    const current = String(workspaceBudgetTemplateSelect.value || "").trim();
    workspaceBudgetTemplateSelect.innerHTML = templates.map((template) => `<option value="${template.key}">${template.label}</option>`).join("");
    const nextValue = templates.some((template) => template.key === current) ? current : templates[0]?.key || "";
    workspaceBudgetTemplateSelect.value = nextValue;
  }
  if (workspaceBudgetConfigHelp) {
    const activeTemplate = templates.find((template) => template.key === String(workspaceBudgetTemplateSelect?.value || "").trim()) || templates[0];
    workspaceBudgetConfigHelp.textContent = activeTemplate?.help || "";
  }
  workspaceBudgetForm.querySelectorAll("[data-budget-fincas='1']").forEach((field) => {
    field.classList.toggle("hidden", service !== "fincas");
  });
  const lineasField = workspaceBudgetForm.querySelector('[name="lineas_texto"]');
  if (lineasField) {
    if (service === "gestoria") {
      lineasField.placeholder = "Conceptos libres de gestoría. Una línea por servicio si quieres detalle, o déjalo vacío y trabaja con subtotal/total manual.";
    } else if (service === "reformas") {
      lineasField.placeholder = "Una línea por partida. Formato: categoría | concepto | cantidad | unidad | precio | dto%";
    } else {
      lineasField.placeholder = "Opcional. Puedes añadir extras sobre la cuota calculada: categoría | concepto | cantidad | unidad | precio | dto%";
    }
  }
};

const applyWorkspaceBudgetTemplate = ({ force = false } = {}) => {
  if (!workspaceBudgetForm || !workspaceBudgetTemplateSelect) return;
  const service = String(workspaceBudgetForm.querySelector('[name="servicio"]')?.value || "gestoria").trim().toLowerCase();
  const templates = getWorkspaceBudgetTemplatesForService(service);
  const template = templates.find((item) => item.key === String(workspaceBudgetTemplateSelect.value || "").trim()) || templates[0];
  if (!template) return;
  if (workspaceBudgetConfigHelp) workspaceBudgetConfigHelp.textContent = template.help || "";
  const titleInput = workspaceBudgetForm.querySelector('[name="titulo"]');
  const linesInput = workspaceBudgetForm.querySelector('[name="lineas_texto"]');
  if (titleInput && template.title && (force || !String(titleInput.value || "").trim())) {
    titleInput.value = template.title;
  }
  if (linesInput && Array.isArray(template.lineas) && (force || !String(linesInput.value || "").trim())) {
    linesInput.value = stringifyWorkspaceBudgetLines(template.lineas);
  }
  syncWorkspaceBudgetComputedFields({ forceSubtotal: service !== "gestoria", forceTotal: true });
};

const fillWorkspaceBudgetForm = (record = null) => {
  if (!workspaceBudgetForm) return;
  hydrateWorkspaceCompanySelects();
  const companies = state.currentWorkspaceDetail?.companies || [];
  const payload = {
    id: "",
    workspace_id: state.currentWorkspaceId || "",
    empresa_id: state.currentWorkspaceCompanyId || companies[0]?.id || "",
    cliente_id: "",
    cliente_lookup: "",
    cliente_nif: "",
    cliente_telefono: "",
    cliente_email: "",
    servicio: "reformas",
    referencia_tipo: "",
    referencia_id: "",
    titulo: "",
    estado: "Borrador",
    fecha: "",
    fecha_seguimiento: "",
    motivo_estado: "",
    responsable: "",
    forma_pago: "",
    encargo_estado: "",
    fecha_encargo: "",
    observaciones: "",
    subtotal_sugerido: "",
    subtotal: "",
    impuestos: "0",
    total: "",
    num_vecinos: "",
    num_locales: "",
    num_trasteros: "",
    num_aparcamientos: "",
    lineas_texto: "",
    plantilla_key: "",
    seguimiento_accion_id: "",
    encargo_accion_id: "",
    ...(record || {}),
  };
  ["id", "workspace_id", "empresa_id", "cliente_id", "cliente_nif", "cliente_telefono", "cliente_email", "servicio", "referencia_tipo", "referencia_id", "titulo", "estado", "fecha", "fecha_seguimiento", "motivo_estado", "responsable", "forma_pago", "encargo_estado", "fecha_encargo", "observaciones", "subtotal_sugerido", "subtotal", "impuestos", "total", "num_vecinos", "num_locales", "num_trasteros", "num_aparcamientos", "lineas_texto", "seguimiento_accion_id", "encargo_accion_id"].forEach((field) => {
    const input = workspaceBudgetForm.querySelector(`[name="${field}"]`);
    if (input) input.value = payload[field] ?? "";
  });
  if (workspaceBudgetClienteLookup) workspaceBudgetClienteLookup.value = payload.cliente_lookup || "";
  applyWorkspaceBudgetServiceMode();
  if (workspaceBudgetTemplateSelect) {
    const templates = getWorkspaceBudgetTemplatesForService(payload.servicio);
    workspaceBudgetTemplateSelect.value = payload.plantilla_key && templates.some((item) => item.key === payload.plantilla_key) ? payload.plantilla_key : (templates[0]?.key || "");
  }
  syncWorkspaceBudgetComputedFields({ forceSubtotal: !record, forceTotal: !record });
};

const renderWorkspaceBudgetList = (rows = []) => {
  if (!workspaceBudgetList) return;
  state.workspaceBudgetRows = Array.isArray(rows) ? rows : [];
  renderWorkspaceBudgetSummary(state.workspaceBudgetRows);
  if (!state.workspaceBudgetRows.length) {
    workspaceBudgetList.innerHTML = "<p class='muted'>Sin presupuestos registrados todavía.</p>";
    return;
  }
  workspaceBudgetList.innerHTML = `
    <div class="workspace-billing-list">
      ${state.workspaceBudgetRows.map((row) => `
        <div class="workspace-billing-row">
          <div>
            <strong>${row.titulo || "Presupuesto"}</strong>
            <div class="muted">${row.empresa_nombre || "-"}${row.cliente_nombre ? ` · ${row.cliente_nombre}` : ""}</div>
            <div class="muted">${row.servicio || "-"}${row.lineas_total ? ` · ${numberFormatter.format(Number(row.lineas_total || 0))} partidas` : ""}${row.fecha_seguimiento ? ` · seguimiento ${row.fecha_seguimiento}` : ""}</div>
            ${row.motivo_estado ? `<div class="muted">${row.motivo_estado}</div>` : ""}
          </div>
          <div class="workspace-billing-meta">
            <span>${row.fecha || "Sin fecha"}</span>
            <span>${euroFormatter.format(Number(row.total || 0))}</span>
            <span>${row.estado || "Borrador"}</span>
            <a class="secondary ghost button-inline" href="/api/workspace_presupuesto_pdf?id=${encodeURIComponent(row.id || "")}&workspace_id=${encodeURIComponent(state.currentWorkspaceId || "")}" target="_blank" rel="noreferrer">PDF</a>
            ${normalizeSimple(row.estado || "") === "aceptado" ? `<a class="secondary ghost button-inline" href="/api/workspace_presupuesto_encargo_pdf?id=${encodeURIComponent(row.id || "")}&workspace_id=${encodeURIComponent(state.currentWorkspaceId || "")}" target="_blank" rel="noreferrer">Encargo</a>` : ""}
            ${normalizeSimple(row.estado || "") !== "estudio" ? `<button type="button" class="secondary ghost" data-budget-status="${row.id}" data-budget-next="Estudio">Estudio</button>` : ""}
            ${normalizeSimple(row.estado || "") !== "aceptado" ? `<button type="button" class="secondary ghost" data-budget-status="${row.id}" data-budget-next="Aceptado">Aceptar</button>` : ""}
            ${normalizeSimple(row.estado || "") !== "rechazado" ? `<button type="button" class="secondary ghost" data-budget-status="${row.id}" data-budget-next="Rechazado">Rechazar</button>` : ""}
            <button type="button" class="secondary ghost" data-budget-edit="${row.id}">Editar</button>
          </div>
        </div>
      `).join("")}
    </div>
  `;
  workspaceBudgetList.querySelectorAll("[data-budget-edit]").forEach((button) => {
    button.addEventListener("click", () => {
      const row = state.workspaceBudgetRows.find((item) => String(item.id || "") === String(button.dataset.budgetEdit || ""));
      if (!row) return;
      const calc = (() => {
        try { return JSON.parse(row.calculo_json || "{}") || {}; } catch { return {}; }
      })();
      fillWorkspaceBudgetForm({
        ...row,
        ...calc,
        cliente_lookup: row.cliente_nombre ? `${row.cliente_nombre}${row.cliente_nif ? ` · ${row.cliente_nif}` : ""}` : "",
        cliente_nif: row.cliente_nif || "",
        cliente_telefono: row.cliente_telefono || "",
        cliente_email: row.cliente_email || "",
        lineas_texto: stringifyWorkspaceBudgetLines(row.lineas || []),
        subtotal_sugerido: calc.cuota_sugerida || row.subtotal || "",
      });
      if (workspaceBudgetStatus) workspaceBudgetStatus.textContent = "Editando presupuesto existente.";
      workspaceBudgetForm?.scrollIntoView({ behavior: "smooth", block: "start" });
    });
  });
  workspaceBudgetList.querySelectorAll("[data-budget-status]").forEach((button) => {
    button.addEventListener("click", async () => {
      const row = state.workspaceBudgetRows.find((item) => String(item.id || "") === String(button.dataset.budgetStatus || ""));
      if (!row) return;
      const nextStatus = String(button.dataset.budgetNext || "").trim();
      const defaultFollowup =
        nextStatus === "Estudio"
          ? new Date(Date.now() + 7 * 86400000).toISOString().slice(0, 10)
          : nextStatus === "Rechazado"
          ? new Date(Date.now() + 30 * 86400000).toISOString().slice(0, 10)
          : "";
      try {
        button.disabled = true;
        const data = await fetch("/api/workspace_presupuestos", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            ...row,
            workspace_id: state.currentWorkspaceId || "",
            estado: nextStatus,
            fecha_seguimiento: row.fecha_seguimiento || defaultFollowup,
            cliente_lookup: row.cliente_nombre || "",
            cliente_nif: row.cliente_nif || "",
            cliente_telefono: row.cliente_telefono || "",
            cliente_email: row.cliente_email || "",
            lineas: row.lineas || [],
          }),
        }).then((res) => res.json());
        if (data?.error) throw new Error(data.error);
        await loadWorkspaceDetail(state.currentWorkspaceId);
      } catch (error) {
        alert(error.message || "No se pudo actualizar el presupuesto.");
        button.disabled = false;
      }
    });
  });
};

const hydrateWorkspaceBillingTargetSelect = () => {
  if (!workspaceCollectionsForm) return;
  const select = workspaceCollectionsForm.querySelector('[name="factura_id"]');
  if (!select) return;
  const rows = Array.isArray(state.workspaceBillingRows) ? state.workspaceBillingRows : [];
  select.innerHTML = rows.length
    ? rows
        .map((row) => {
          const ref = [row.serie, row.numero].filter(Boolean).join("-");
          const label = `${ref || "Factura"} · ${row.concepto || "Sin concepto"} · ${euroFormatter.format(Number(row.total || 0))}`;
          return `<option value="${row.id}">${label}</option>`;
        })
        .join("")
    : "<option value=''>Sin facturas</option>";
};

const hydrateWorkspaceRemittanceTargets = () => {
  if (!workspaceRemittancesForm) return;
  const select = workspaceRemittancesForm.querySelector('[name="factura_ids"]');
  if (!select) return;
  const rows = (state.workspaceBillingRows || []).filter((row) => Number(row.saldo_pendiente || 0) > 0 && !row.remesa_id);
  select.innerHTML = rows.length
    ? rows
        .map((row) => {
          const ref = [row.serie, row.numero].filter(Boolean).join("-");
          return `<option value="${row.id}">${ref || row.id} · ${row.concepto || "Factura"} · ${euroFormatter.format(Number(row.saldo_pendiente || 0))}</option>`;
        })
        .join("")
    : "<option value=''>Sin pendientes remesables</option>";
};

