const hydrateWorkspaceCompanySelects = () => {
  const companies = state.currentWorkspaceDetail?.companies || [];
  const defaultCompanyId = state.currentWorkspaceCompanyId || companies[0]?.id || "";
  const html = companies.map((row) => `<option value="${row.id}">${row.nombre || "-"}</option>`).join("");
  [workspaceBillingForm, workspaceBudgetForm, workspaceInboxForm, workspaceSeriesForm, workspaceTimeForm, workspaceTimeEmployeeForm, workspaceFincasCommunityForm, workspaceRemittancesForm, workspaceFincasProviderForm].forEach((form) => {
    const select = form?.querySelector('[name="empresa_id"]');
    if (select) {
      select.innerHTML = html;
      if (defaultCompanyId) {
        select.value = defaultCompanyId;
      }
      if (!String(select.value || "").trim() && companies[0]?.id) {
        select.value = companies[0].id;
      }
    }
  });
};

const ensureWorkspaceCompaniesLoaded = async () => {
  const current = state.currentWorkspaceDetail?.companies || [];
  if (current.length || !state.currentWorkspaceId) {
    return current;
  }
  const detail = await safeWorkspaceApi(`/api/workspace_detail?id=${encodeURIComponent(state.currentWorkspaceId)}`, null);
  if (detail?.workspace) {
    state.currentWorkspaceDetail = {
      ...(state.currentWorkspaceDetail || {}),
      ...detail,
    };
  }
  return state.currentWorkspaceDetail?.companies || [];
};

const fillWorkspaceInboxForm = (record = null) => {
  if (!workspaceInboxForm) return;
  hydrateWorkspaceCompanySelects();
  const companies = state.currentWorkspaceDetail?.companies || [];
  const payload = {
    id: "",
    workspace_id: state.currentWorkspaceId || "",
    empresa_id: state.currentWorkspaceCompanyId || companies[0]?.id || "",
    cliente_id: "",
    suggested_cliente_id: "",
    servicio: "",
    nombre: "",
    tipo: "",
    clasificacion: "",
    canal_entrada: "Email",
    prioridad: "Normal",
    estado: "Pendiente",
    origen_tipo: "",
    origen_id: "",
    notas: "",
    ...(record || {}),
  };
  ["id", "workspace_id", "empresa_id", "cliente_id", "suggested_cliente_id", "servicio", "nombre", "tipo", "clasificacion", "canal_entrada", "prioridad", "estado", "origen_tipo", "origen_id", "notas"].forEach((field) => {
    const input = workspaceInboxForm.querySelector(`[name="${field}"]`);
    if (input) input.value = payload[field] ?? "";
  });
  if (workspaceInboxClienteLookup) {
    workspaceInboxClienteLookup.value = payload.cliente_lookup || payload.suggested_cliente_lookup || "";
  }
};

const renderWorkspaceInboxList = (rows = []) => {
  if (!workspaceInboxList) return;
  if (!rows.length) {
    workspaceInboxList.innerHTML = "<p class='muted'>Sin documentos en inbox.</p>";
    return;
  }
  workspaceInboxList.innerHTML = `
    <div class="workspace-billing-list">
      ${rows
        .map((row) => {
          const hint = `${row.nombre || ""} ${row.tipo || ""} ${row.clasificacion || ""}`.toLowerCase();
          const isInvoice = /(factura|ticket|recibo|gasto|albaran)/i.test(hint);
          const ocrStatus = String(row.ocr_status || "").toLowerCase();
          const ocrBusy = ["pending", "processing"].includes(ocrStatus);
          const canOcrFactura = isInvoice && row.doc_key && !row.factura_id && !ocrBusy;
          const ocrLine = row.ocr_status
            ? `OCR: ${row.ocr_status}${row.ocr_method ? ` · ${row.ocr_method}` : ""}${row.factura_id ? " · vinculada" : ""}`
            : "";
          const ocrErrorLine = row.ocr_error ? `OCR error: ${String(row.ocr_error).slice(0, 120)}` : "";
          return `
            <div class="workspace-billing-row">
              <div>
                <strong>${row.nombre || "Documento"}</strong>
                <div class="muted">${row.empresa_nombre || "-"} · ${row.servicio || "sin servicio"} · ${row.estado || "Pendiente"}</div>
                ${ocrLine ? `<div class="muted">${ocrLine}</div>` : ""}
                ${ocrErrorLine ? `<div class="workspace-document-suggestion">${ocrErrorLine}</div>` : ""}
                ${row.suggested_cliente_nombre ? `<div class="workspace-document-suggestion">Cliente sugerido: ${row.suggested_cliente_nombre}</div>` : ""}
                ${row.requerimiento_titulo ? `<div class="muted">Requerimiento: ${row.requerimiento_titulo}</div>` : ""}
              </div>
              <div class="workspace-billing-meta">
                <span>${row.canal_entrada || "Manual"}</span>
                <span>${row.prioridad || "Normal"}</span>
                ${row.doc_url ? `<a class="secondary ghost button-inline" href="${row.doc_url}" target="_blank" rel="noreferrer">Abrir</a>` : ""}
                ${canOcrFactura ? `<button type="button" class="secondary ghost" data-inbox-ocr="${row.id}">OCR factura</button>` : ""}
                ${row.suggested_cliente_id && !row.cliente_id ? `<button type="button" class="secondary ghost" data-inbox-accept="${row.id}">Aceptar sugerido</button>` : ""}
                ${row.estado !== "Procesado" ? `<button type="button" class="secondary ghost" data-inbox-process="${row.id}">Procesar</button>` : ""}
                <button type="button" class="secondary ghost" data-inbox-edit="${row.id}">Editar</button>
              </div>
            </div>
          `;
        })
        .join("")}
    </div>
  `;
  workspaceInboxList.querySelectorAll("[data-inbox-edit]").forEach((button) => {
    button.addEventListener("click", () => {
      const record = rows.find((row) => String(row.id || "") === String(button.dataset.inboxEdit || ""));
      if (!record) return;
      const lookup = record.suggested_cliente_nombre || record.cliente_nombre || "";
      fillWorkspaceInboxForm({ ...record, suggested_cliente_lookup: lookup });
    });
  });
  const runInboxAction = async (id, action) => {
    try {
      const data = await fetch("/api/workspace_inbox_review", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ workspace_id: state.currentWorkspaceId, id, action, usuario: getCurrentUser() }),
      }).then((res) => res.json());
      if (data?.error) throw new Error(data.error);
      await loadWorkspaceDetail(state.currentWorkspaceId);
      if (workspaceInboxStatus) workspaceInboxStatus.textContent = `Documento ${data.estado || "actualizado"}.`;
    } catch (error) {
      if (workspaceInboxStatus) workspaceInboxStatus.textContent = error.message || "No se pudo revisar el documento.";
    }
  };
  workspaceInboxList.querySelectorAll("[data-inbox-accept]").forEach((button) => {
    button.addEventListener("click", () => runInboxAction(button.dataset.inboxAccept || "", "accept_suggestion"));
  });
  workspaceInboxList.querySelectorAll("[data-inbox-process]").forEach((button) => {
    button.addEventListener("click", () => runInboxAction(button.dataset.inboxProcess || "", "mark_processed"));
  });
  workspaceInboxList.querySelectorAll("[data-inbox-ocr]").forEach((button) => {
    button.addEventListener("click", () => runInboxAction(button.dataset.inboxOcr || "", "factura_ocr"));
  });
};

