const fillWorkspaceTimeForm = (record = null) => {
  if (!workspaceTimeForm) return;
  hydrateWorkspaceCompanySelects();
  const companies = state.currentWorkspaceDetail?.companies || [];
  const defaultProfile = !record ? findCurrentUserTimeProfile() : null;
  const payload = {
    id: "",
    workspace_id: state.currentWorkspaceId || "",
    empresa_id: defaultProfile?.employee?.empresa_id || state.currentWorkspaceCompanyId || companies[0]?.id || "",
    persona_id: defaultProfile?.employee?.id || "",
    persona_nombre: defaultProfile?.employee?.nombre || "",
    tipo_jornada: defaultProfile?.employee?.tipo_jornada || "Completa",
    horas_pactadas_dia: defaultProfile?.employee?.horas_pactadas_dia || "",
    fecha: new Date().toISOString().slice(0, 10),
    hora_inicio: "",
    hora_fin: "",
    pausa_min: 0,
    metodo_registro: "Manual",
    estado: "Abierto",
    notas: "",
    ...(record || {}),
  };
  ["id", "workspace_id", "empresa_id", "persona_id", "persona_nombre", "tipo_jornada", "horas_pactadas_dia", "fecha", "hora_inicio", "hora_fin", "pausa_min", "metodo_registro", "estado", "notas"].forEach((field) => {
    const input = workspaceTimeForm.querySelector(`[name="${field}"]`);
    if (!input) return;
    let value = payload[field] ?? "";
    if (input.type === "date") {
      value = String(value || "").trim().slice(0, 10);
      if (value && !/^\d{4}-\d{2}-\d{2}$/.test(value)) value = "";
    } else if (input.type === "number") {
      value = String(value || "").trim();
      if (value && Number.isNaN(Number(value))) value = "";
    }
    input.value = value;
  });
  const lookup = workspaceTimeForm.querySelector('[name="persona_id_lookup"]');
  if (lookup) {
    lookup.value = payload.persona_id || "";
  }
};

const getWorkspaceTimeEligibleUsers = () => {
  const sourceRows = (state.workspaceTimeUsers && state.workspaceTimeUsers.length)
    ? state.workspaceTimeUsers
    : state.usersList;
  const seen = new Set();
  const deduped = (sourceRows || []).filter((user) => {
    if (Number(user.activo ?? 1) !== 1) return false;
    const id = String(user?.id || "").trim();
    if (!id) return false;
    if (seen.has(id)) return false;
    seen.add(id);
    return true;
  });
  return deduped.sort((a, b) => {
    const nameA = `${a.nombre || ""} ${a.apellido || ""}`.trim();
    const nameB = `${b.nombre || ""} ${b.apellido || ""}`.trim();
    return nameA.localeCompare(nameB, "es", { sensitivity: "base" });
  });
};

const hydrateWorkspaceTimeUserSelect = () => {
  const select = workspaceTimeEmployeeForm?.querySelector('[name="usuario_id_lookup"]');
  if (!select) return;
  const currentValue = String(select.value || "").trim();
  const users = getWorkspaceTimeEligibleUsers();
  select.innerHTML = `<option value="">Selecciona usuario</option>${
    users.map((user) => {
      const fullName = `${user.nombre || ""} ${user.apellido || ""}`.trim() || user.usuario || user.email || "Usuario";
      const suffix = user.servicio ? ` · ${user.servicio}` : "";
      return `<option value="${user.id || ""}">${fullName}${suffix}</option>`;
    }).join("")
  }`;
  if (currentValue && users.some((user) => String(user.id || "") === currentValue)) {
    select.value = currentValue;
  }
};

const refreshWorkspaceTimeSetup = async () => {
  if (!state.currentWorkspaceId) return;
  await ensureWorkspaceCompaniesLoaded();
  const companyQuery = state.currentWorkspaceCompanyId
    ? `&empresa_id=${encodeURIComponent(state.currentWorkspaceCompanyId)}`
    : "";
  const timeUsers = await safeWorkspaceApi(
    `/api/workspace_registro_usuarios?workspace_id=${encodeURIComponent(state.currentWorkspaceId)}${companyQuery}&limit=300`,
    { rows: [] }
  );
  state.workspaceTimeUsers = timeUsers.rows || [];
  hydrateWorkspaceCompanySelects();
  hydrateWorkspaceTimeUserSelect();
};

const runWorkspaceTimeAlertSweep = async () => {
  if (!state.currentWorkspaceId) return;
  const now = Date.now();
  if (state.workspaceTimeLastAlertSweep && now - state.workspaceTimeLastAlertSweep < 5 * 60 * 1000) {
    return;
  }
  state.workspaceTimeLastAlertSweep = now;
  await safeWorkspaceApi(
    `/api/workspace_registro_horario_alerts_run?workspace_id=${encodeURIComponent(state.currentWorkspaceId)}`,
    { ok: true }
  );
  await loadWorkspaceNotifications();
};

const refreshWorkspaceTimeSweepStatus = async () => {
  if (!workspaceTimeSweepStatus) return;
  if (!state.currentWorkspaceId) {
    workspaceTimeSweepStatus.textContent = "Barrido automático: sin workspace.";
    return;
  }
  if (!isWorkspaceTimeManager()) {
    workspaceTimeSweepStatus.textContent = "Barrido automático: visible solo para administradores.";
    if (workspaceTimeSweepRunNow) workspaceTimeSweepRunNow.classList.add("hidden");
    return;
  }
  const companyQuery = state.currentWorkspaceCompanyId
    ? `&empresa_id=${encodeURIComponent(state.currentWorkspaceCompanyId)}`
    : "";
  const data = await safeWorkspaceApi(
    `/api/workspace_registro_sweep_status?workspace_id=${encodeURIComponent(state.currentWorkspaceId)}${companyQuery}`,
    null
  );
  const enabled = data?.enabled !== false;
  const interval = Number(data?.interval_seconds || 300) || 300;
  const last = String(data?.last_run_at || "").trim();
  const err = String(data?.last_error || "").trim();
  const notif = Number(data?.last_notifications || 0) || 0;
  const workspaces = Number(data?.last_workspaces || 0) || 0;
  const bits = [];
  bits.push(`Barrido automático: ${enabled ? "activo" : "desactivado"}`);
  bits.push(`cada ${Math.max(60, interval)}s`);
  if (last) bits.push(`último: ${last.slice(0, 19).replace("T", " ")}`);
  bits.push(`workspaces: ${workspaces}`);
  bits.push(`notifs: ${notif}`);
  if (err) bits.push(`error: ${err.slice(0, 120)}`);
  workspaceTimeSweepStatus.textContent = bits.join(" · ");
  if (workspaceTimeSweepRunNow) workspaceTimeSweepRunNow.classList.remove("hidden");
};

