const renderWorkspaceTimePeriodLock = (rows = []) => {
  if (!workspaceTimePeriodStatus || !workspaceTimePeriodToggle) return;
  if (!isWorkspaceTimeManager()) {
    workspaceTimePeriodToggle.classList.add("hidden");
    workspaceTimePeriodStatus.textContent = "Disponible solo para administradores del workspace.";
    return;
  }
  const month = String(state.workspaceTimeMonth || "").trim();
  if (!month) {
    workspaceTimePeriodToggle.classList.add("hidden");
    workspaceTimePeriodStatus.textContent = "Selecciona un mes para ver el estado.";
    return;
  }
  const row = (Array.isArray(rows) ? rows : []).find((r) => String(r.month || "").slice(0, 7) === month) || null;
  state.workspaceTimePeriodRow = row;
  const locked = Number(row?.locked || 0) === 1;
  const lockedAt = String(row?.locked_at || "").trim();
  const lockedBy = String(row?.locked_by || "").trim();
  const summaryBits = [];
  if (typeof row?.entries_total !== "undefined") summaryBits.push(`${Number(row.entries_total || 0)} fichajes`);
  if (typeof row?.minutos_total !== "undefined") {
    const minutes = Math.max(0, Number(row.minutos_total || 0) || 0);
    const hh = Math.floor(minutes / 60);
    const mm = Math.floor(minutes % 60);
    summaryBits.push(`${String(hh).padStart(2, "0")}:${String(mm).padStart(2, "0")}`);
  }
  const summaryText = summaryBits.length ? ` · ${summaryBits.join(" · ")}` : "";
  if (locked) {
    workspaceTimePeriodStatus.textContent = `Mes ${month} bloqueado${lockedAt ? ` (${lockedAt.slice(0, 10)})` : ""}${lockedBy ? ` por ${lockedBy}` : ""}${summaryText}.`;
    workspaceTimePeriodToggle.textContent = "Desbloquear mes";
  } else {
    workspaceTimePeriodStatus.textContent = `Mes ${month} abierto${summaryText}.`;
    workspaceTimePeriodToggle.textContent = "Bloquear mes";
  }
  workspaceTimePeriodToggle.dataset.month = month;
  workspaceTimePeriodToggle.dataset.locked = locked ? "1" : "0";
  workspaceTimePeriodToggle.classList.remove("hidden");
};

const renderWorkspaceTimeList = (rows = []) => {
  if (!workspaceTimeList) return;
  if (!rows.length) {
    workspaceTimeList.innerHTML = "<p class='muted'>Sin fichajes todavía.</p>";
    return;
  }
  workspaceTimeList.innerHTML = `
    <div class="workspace-billing-list">
      ${rows
        .map(
          (row) => `
            <div class="workspace-billing-row">
              <div>
                <strong>${row.persona_nombre || "-"}</strong>
                <div class="muted">${row.empresa_nombre || "-"} · ${row.fecha || "-"}${row.tipo_jornada ? ` · ${row.tipo_jornada}` : ""}</div>
              </div>
              <div class="workspace-billing-meta">
                <span>${row.hora_inicio || "-"}${row.hora_fin ? ` - ${row.hora_fin}` : ""}</span>
                <span>Pausa ${numberFormatter.format(Number(row.pausa_min || 0))} min</span>
                <span>${row.minutos_trabajados ? `${Math.floor(Number(row.minutos_trabajados || 0) / 60)}h ${Number(row.minutos_trabajados || 0) % 60}m` : "Pendiente cierre"}</span>
                <span>${row.estado || "Abierto"}</span>
                ${!row.hora_fin ? `<button type="button" class="secondary ghost" data-time-close="${row.id}">Cerrar</button>` : ""}
                <button type="button" class="secondary ghost" data-time-edit="${row.id}">Editar</button>
              </div>
            </div>
          `
        )
        .join("")}
    </div>
  `;
  workspaceTimeList.querySelectorAll("[data-time-edit]").forEach((button) => {
    button.addEventListener("click", () => {
      const record = rows.find((row) => String(row.id || "") === String(button.dataset.timeEdit || ""));
      if (record) fillWorkspaceTimeForm(record);
    });
  });
  workspaceTimeList.querySelectorAll("[data-time-close]").forEach((button) => {
    button.addEventListener("click", async () => {
      const record = rows.find((row) => String(row.id || "") === String(button.dataset.timeClose || ""));
      if (!record) return;
      const now = new Date();
      const currentTime = `${String(now.getHours()).padStart(2, "0")}:${String(now.getMinutes()).padStart(2, "0")}`;
      try {
        const data = await fetch("/api/workspace_registro_horario", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ ...record, workspace_id: state.currentWorkspaceId, hora_fin: currentTime, estado: "Cerrado" }),
        }).then((res) => res.json());
        if (data?.error) throw new Error(data.error);
        await loadWorkspaceDetail(state.currentWorkspaceId);
        if (workspaceTimeStatus) workspaceTimeStatus.textContent = `Fichaje cerrado a las ${currentTime}.`;
      } catch (error) {
        if (workspaceTimeStatus) workspaceTimeStatus.textContent = error.message || "No se pudo cerrar el fichaje.";
      }
    });
  });
};

