const loadWorkspaceDetail = async (workspaceId) => {
  if (!workspaceId) return;
  state.currentWorkspaceId = workspaceId;
  try {
    localStorage.setItem("crm.currentWorkspaceId", String(workspaceId || ""));
  } catch {}
  // Evita cargar un workspace con DB todavía "fría" (Render/PG): si no, se muestran fichas vacías y
  // el usuario siente que "se han borrado" configuraciones.
  {
    const health = await probeDbHealth();
    if (!health.ok) {
      const attempt = Number(state.workspaceDetailRetryAttempt || 0) || 0;
      const nextAttempt = Math.min(8, attempt + 1);
      state.workspaceDetailRetryAttempt = nextAttempt;
      const delayMs = Math.min(45000, 1200 * Math.pow(1.6, nextAttempt));
      setUiToast("Base de datos no disponible", `${health.body || `HTTP ${health.status}`} · Reintentando en ${Math.round(delayMs / 1000)}s...`);
      window.setTimeout(() => {
        loadWorkspaceDetail(workspaceId).catch(() => {});
      }, delayMs);
      return;
    }
    state.workspaceDetailRetryAttempt = 0;
  }
  hideUiToast();
  const authUser = getAuthScopeUser();
  const canManageWorkspace = Boolean(authUser && isPrivilegedUser(authUser));
  if (canManageWorkspace) {
    await safeWorkspaceApi("/api/usuarios", { rows: [] }).then((data) => {
      state.usersList = data.rows || [];
      populateResponsableSelects();
      populateAsesorSelects();
      refreshSegurosColaboradoresList();
    });
  } else {
    state.usersList = authUser ? [authUser] : [];
    populateResponsableSelects();
    populateAsesorSelects();
  }
  // Reset inmediato para evitar que, si falla la carga, se queden datos “pegados” del workspace/persona anterior.
  state.currentWorkspaceClients = [];
  state.currentWorkspaceData = {};
  state.workspaceTimeEmployees = [];
  state.workspaceTimeSummary = null;
  let detail = null;
  detail = await safeWorkspaceApi(`/api/workspace_detail?id=${encodeURIComponent(workspaceId)}`, null);
  if (!detail || !detail.workspace) {
    clearCurrentWorkspaceUi();
    updateWorkspaceEntryChrome();
    const attempt = Number(state.workspaceDetailRetryAttempt || 0) || 0;
    const nextAttempt = Math.min(8, attempt + 1);
    state.workspaceDetailRetryAttempt = nextAttempt;
    const delayMs = Math.min(45000, 1200 * Math.pow(1.6, nextAttempt));
    const lastErr = state.lastApiError?.message ? String(state.lastApiError.message) : "No se pudo cargar el workspace.";
    setUiToast("Error cargando el workspace", `${lastErr} · Reintentando en ${Math.round(delayMs / 1000)}s...`);
    window.setTimeout(() => {
      loadWorkspaceDetail(workspaceId).catch(() => {});
    }, delayMs);
    return;
  }
  state.currentWorkspaceDetail = detail;
  state.currentWorkspaceEnabledModules = getWorkspaceEnabledModules(detail.modules || []);
  state.currentWorkspaceName = detail.workspace?.nombre || "";
  if (!state.currentWorkspaceTarget) {
    state.currentWorkspaceTarget = detail.workspace?.slug || detail.workspace?.nombre || "";
  }
  const companies = detail.companies || [];
  const tenantOperationalMode = (state.currentWorkspaceEntryMode || "platform") === "tenant";
  const companyMatch = companies.find((row) => String(row.id || "") === String(state.currentWorkspaceCompanyId || ""));
  state.currentWorkspaceCompanyId = tenantOperationalMode ? "" : (companyMatch?.id || companies[0]?.id || "");
  state.currentWorkspaceCompanyName = tenantOperationalMode ? "" : (companyMatch?.nombre || companies[0]?.nombre || "");
  const companyQuery = state.currentWorkspaceCompanyId
    ? `&empresa_id=${encodeURIComponent(state.currentWorkspaceCompanyId)}`
    : "";
  const timeMonth = normalizeMonthValue(state.workspaceTimeMonth || "");
  state.workspaceTimeMonth = timeMonth;
  const viewHint = String(
    state.currentWorkspaceView
      || new URLSearchParams(window.location.search || "").get("view")
      || ""
  )
    .trim()
    .toLowerCase();
  const minimalForRrhh = viewHint === "rrhh";

  // Pintado rápido del workspace: módulos + estructura, sin esperar a cargar paneles pesados.
  // Esto mejora mucho el "time-to-first-cards" al entrar en Operativa.
  fillWorkspaceForm(detail.workspace || {});
  renderWorkspaceCommercialPack(detail.workspace || {}, detail.commercial_package || {});
  renderWorkspacePermissionMatrix(detail.permission_matrix || []);
  renderWorkspaceLauncher(detail.workspace || {}, detail.modules || []);
  renderWorkspaceCompanySwitcher(companies);
  renderWorkspaceCompanies(companies);
  renderWorkspaceModules(detail.modules || []);
  updateWorkspaceEntryChrome();
  syncCrmLegalAvailability();
  {
    const tenantMode = (state.currentWorkspaceEntryMode || "platform") === "tenant";
    const view = state.currentWorkspaceView || "overview";
    setWorkspaceView(view, { forceTenantView: tenantMode && normalizeSimple(view) !== "operations" });
  }
  renderWorkspaceList(state.workspaces || []);
  renderCompanyCards();

  // Fast boot: 1 request en lugar de 20-25 (mejora enorme en iOS/PWA).
  const bootParams = new URLSearchParams({
    workspace_id: String(workspaceId || ""),
    month: String(timeMonth || ""),
  });
  if (state.currentWorkspaceCompanyId) {
    bootParams.set("empresa_id", String(state.currentWorkspaceCompanyId || ""));
  }
  if (minimalForRrhh) {
    bootParams.set("minimal", "1");
  }
  const boot = await safeWorkspaceApi(`/api/workspace_boot?${bootParams.toString()}`, null);

  const timeUsers = boot?.time_users || await safeWorkspaceApi(
    `/api/workspace_registro_usuarios?workspace_id=${encodeURIComponent(workspaceId)}${companyQuery}&limit=300`,
    { rows: [] }
  );
  state.workspaceTimeUsers = timeUsers.rows || [];

  let members = { rows: [] };
  if (canManageWorkspace) {
    members = await safeWorkspaceApi(`/api/workspace_members?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
  }
  state.currentWorkspaceMembers = members.rows || [];
  let links = { rows: [] };
  if (canManageWorkspace) {
    links = await safeWorkspaceApi(`/api/workspace_links?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
  }
  state.currentWorkspaceLinks = links.rows || [];

  // Evitar "stampede" de decenas de requests al entrar en el workspace.
  let billing = {};
  let docs = { rows: [], summary: {} };
  let billingRows = { rows: [] };
  let budgetRows = { rows: [] };
  let collections = { rows: [] };
  let remittances = { rows: [] };
  let workspaceClients = { rows: [] };
  let health = {};
  let gestoriaOverview = {};
  let segurosOverview = {};
  let finOverview = {};
  let inmoOverview = {};
  let serviceDesks = {};
  let series = { rows: [] };
  let inbox = { rows: [] };
  let portal = { rows: [] };
  let portalRequests = { rows: [] };
  let automations = { rows: [] };
  let automationLogs = { rows: [] };

  // RRHH necesita estos datos para pintar cards y jornada.
  const timeRows = boot?.time_rows || await safeWorkspaceApi(
    `/api/workspace_registro_horario?workspace_id=${encodeURIComponent(workspaceId)}&month=${encodeURIComponent(timeMonth)}${companyQuery}&limit=250`,
    { rows: [] }
  );
  const timeEmployees = boot?.time_employees || await safeWorkspaceApi(
    `/api/workspace_registro_personal?workspace_id=${encodeURIComponent(workspaceId)}${companyQuery}&activos=0&limit=500`,
    { rows: [] }
  );
  const timeSummary = boot?.time_summary || await safeWorkspaceApi(
    `/api/workspace_registro_horario_resumen?workspace_id=${encodeURIComponent(workspaceId)}&month=${encodeURIComponent(timeMonth)}${companyQuery}`,
    {}
  );
  const timePeriods = boot?.time_periods || await safeWorkspaceApi(
    `/api/workspace_registro_periodos?workspace_id=${encodeURIComponent(workspaceId)}${companyQuery}`,
    { rows: [] }
  );
  let fincasCommunities = boot?.fincas_communities || { rows: [] };
  let fincasIncidents = boot?.fincas_incidents || { rows: [] };
  let fincasProviders = boot?.fincas_providers || { rows: [] };
  let fincasMeetings = boot?.fincas_meetings || { rows: [] };

  if (!minimalForRrhh) {
    billing = boot?.billing_summary || await safeWorkspaceApi(`/api/workspace_billing_summary?workspace_id=${encodeURIComponent(workspaceId)}`, {});
    docs = boot?.docs || await safeWorkspaceApi(`/api/workspace_document_hub?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [], summary: {} });
    billingRows = boot?.billing_rows || await safeWorkspaceApi(`/api/workspace_facturacion?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
    budgetRows = boot?.budget_rows || await safeWorkspaceApi(`/api/workspace_presupuestos?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
    collections = boot?.collections || await safeWorkspaceApi(`/api/workspace_cobros?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
    remittances = boot?.remittances || await safeWorkspaceApi(`/api/workspace_remesas?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
    workspaceClients = boot?.clients || await safeWorkspaceApi(`/api/workspace_clientes?workspace_id=${encodeURIComponent(workspaceId)}&limit=60`, { rows: [] });
    health = boot?.health || await safeWorkspaceApi(`/api/workspace_health?workspace_id=${encodeURIComponent(workspaceId)}`, {});
    gestoriaOverview = boot?.gestoria_overview || await safeWorkspaceApi(`/api/workspace_gestoria_overview?workspace_id=${encodeURIComponent(workspaceId)}${companyQuery}`, {});
    segurosOverview = boot?.seguros_overview || await safeWorkspaceApi(`/api/workspace_seguros_overview?workspace_id=${encodeURIComponent(workspaceId)}${companyQuery}`, {});
    finOverview = boot?.fin_overview || await safeWorkspaceApi(`/api/workspace_fin_overview?workspace_id=${encodeURIComponent(workspaceId)}${companyQuery}`, {});
    inmoOverview = boot?.inmo_overview || await safeWorkspaceApi(`/api/workspace_inmo_overview?workspace_id=${encodeURIComponent(workspaceId)}${companyQuery}`, {});
    serviceDesks = boot?.service_desks || await safeWorkspaceApi(`/api/workspace_service_desks?workspace_id=${encodeURIComponent(workspaceId)}${companyQuery}`, {});
    series = boot?.series || await safeWorkspaceApi(`/api/workspace_series?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
    inbox = boot?.inbox || await safeWorkspaceApi(`/api/workspace_inbox?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
    portal = boot?.portal || await safeWorkspaceApi(`/api/workspace_portal?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
    portalRequests = boot?.portal_requests || await safeWorkspaceApi(`/api/workspace_portal_requerimientos?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
    automations = boot?.automations || await safeWorkspaceApi(`/api/workspace_automatizaciones?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
    automationLogs = boot?.automation_logs || await safeWorkspaceApi(`/api/workspace_automatizacion_logs?workspace_id=${encodeURIComponent(workspaceId)}&limit=12`, { rows: [] });
    fincasCommunities = boot?.fincas_communities || await safeWorkspaceApi(`/api/workspace_fincas_comunidades?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
    fincasIncidents = boot?.fincas_incidents || await safeWorkspaceApi(`/api/workspace_fincas_incidencias?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
    fincasProviders = boot?.fincas_providers || await safeWorkspaceApi(`/api/workspace_fincas_proveedores?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
    fincasMeetings = boot?.fincas_meetings || await safeWorkspaceApi(`/api/workspace_fincas_juntas?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
  }
  state.currentWorkspaceClients = workspaceClients.rows || [];
  state.currentWorkspaceData = {
    docs,
    billingRows: billingRows.rows || [],
    budgetRows: budgetRows.rows || [],
    collectionRows: collections.rows || [],
    remittanceRows: remittances.rows || [],
    seriesRows: series.rows || [],
    inboxRows: inbox.rows || [],
    portalRows: portal.rows || [],
    portalRequestRows: portalRequests.rows || [],
    automationRows: automations.rows || [],
    automationLogRows: automationLogs.rows || [],
    timeRows: timeRows.rows || [],
    timeEmployees: timeEmployees.rows || [],
    timeSummary: timeSummary || null,
    timePeriods: timePeriods.rows || [],
    fincasCommunities: fincasCommunities.rows || [],
    fincasIncidents: fincasIncidents.rows || [],
    fincasProviders: fincasProviders.rows || [],
    fincasMeetings: fincasMeetings.rows || [],
  };
  state.workspaceTimeEmployees = timeEmployees.rows || [];
  state.workspaceTimeSummary = timeSummary || null;
  syncWorkspaceClientOptions(workspaceClients.rows || []);
  fillWorkspaceForm(detail.workspace || {});
  renderWorkspaceHealth(health || {});
  renderWorkspaceCommercialPack(detail.workspace || {}, detail.commercial_package || {});
  renderWorkspacePermissionMatrix(detail.permission_matrix || []);
  renderWorkspaceLauncher(detail.workspace || {}, detail.modules || []);
  void refreshWorkspaceHomeAlerts();
  renderWorkspaceCompanySwitcher(companies);
  renderWorkspaceCompanies(companies);
  renderWorkspaceMembers(state.currentWorkspaceMembers || []);
  renderWorkspaceLinks(state.currentWorkspaceLinks || []);
  renderWorkspaceClientBase(workspaceClients.rows || []);
  renderWorkspaceClientDetail(null);
  renderWorkspaceModules(detail.modules || []);
  renderWorkspaceBillingSummary(billing || {});
  renderWorkspaceGestoriaOverview(gestoriaOverview || {});
  renderWorkspaceSegurosOverview(segurosOverview || {});
  renderWorkspaceFinOverview(finOverview || {});
  renderWorkspaceInmoOverview(inmoOverview || {});
  renderWorkspaceServiceDesks(serviceDesks || {});
  renderWorkspaceCopilotHub();
  renderWorkspaceRrhhHub();
  if (state.currentWorkspaceView === "motores") {
    const engine = state.currentWorkspaceEngineView || "documental";
    if (engine === "registro_horario") {
      if (isWorkspaceTimeManager()) {
        await refreshWorkspaceTimeSetup();
        await refreshWorkspaceTimeSweepStatus();
        await runWorkspaceTimeAlertSweep();
      } else {
        applyWorkspaceTimeMode();
      }
    }
    if (engine === "rrhh") {
      await refreshWorkspaceRrhh();
    }
  }
  fillWorkspaceBillingForm();
  fillWorkspaceBudgetForm();
  fillWorkspaceCollectionsForm();
  fillWorkspaceRemittancesForm();
  fillWorkspaceSeriesForm();
  fillWorkspaceInboxForm();
  fillWorkspacePortalRequestForm();
  fillWorkspaceAutomationForm();
  fillWorkspaceTimeEmployeeForm();
  fillWorkspaceTimeForm();
  fillWorkspaceFincasCommunityForm();
  fillWorkspaceFincasIncidentForm();
  fillWorkspaceFincasProviderForm();
  fillWorkspaceFincasMeetingForm();
  renderWorkspaceCompanyScopedData();
  updateWorkspaceEntryChrome();
  syncCrmLegalAvailability();
  {
    const tenantMode = (state.currentWorkspaceEntryMode || "platform") === "tenant";
    const view = state.currentWorkspaceView || "overview";
    setWorkspaceView(view, { forceTenantView: tenantMode && normalizeSimple(view) !== "operations" });
  }
  if ((workspaceClients.rows || []).length) {
    await openWorkspaceClient360((workspaceClients.rows || [])[0].id, {
      prefetchedRow: (workspaceClients.rows || [])[0],
      silent: true,
    });
  } else {
    state.currentWorkspaceClientId = "";
    state.currentWorkspaceClientData = null;
    renderWorkspaceClientDetail(null);
  }
  renderWorkspaceList(state.workspaces || []);
  renderCompanyCards();
};

const loadWorkspaceCentral = async () => {
  // Si la DB está fría, /api/workspaces puede tardar 30s por timeout. Mejor gatear con /api/health (rápido)
  // y reintentar con backoff.
  const health = await probeDbHealth();
  if (!health.ok) {
    clearCurrentWorkspaceUi();
    renderWorkspaceList([]);
    try {
      setUiToast(
        "Base de datos no disponible",
        `${health.body || `HTTP ${health.status}`} · Reintentando cargar el workspace en unos segundos...`
      );
    } catch {}
    updateWorkspaceEntryChrome();
    const attempt = Number(state.workspaceCentralRetryAttempt || 0) || 0;
    const nextAttempt = Math.min(7, attempt + 1);
    state.workspaceCentralRetryAttempt = nextAttempt;
    const delayMs = Math.min(45000, 1000 * Math.pow(1.8, nextAttempt));
    window.setTimeout(() => {
      loadWorkspaceCentral().catch(() => {});
    }, delayMs);
    return;
  }
  const data = await safeWorkspaceApi("/api/workspaces", null);
  if (!data) {
    clearCurrentWorkspaceUi();
    renderWorkspaceList([]);
    // Evita un alert bloqueante: en Render esto suele ser un reinicio/deploy o cold start.
    try {
      const last = state.lastApiError || {};
      if (document.body.classList.contains("auth-locked") || last.status === 401) {
        // Si hemos caído a login, no mostramos toast extra.
      } else if (last.status) {
        setUiToast("Error al cargar", last.message || `HTTP ${last.status}`);
      } else {
        setUiToast("Servidor no disponible", (last.message || "Reintentando...").trim() || "Reintentando...");
      }
    } catch {}
    updateWorkspaceEntryChrome();
    // Reintento con backoff simple.
    const attempt = Number(state.workspaceCentralRetryAttempt || 0) || 0;
    const nextAttempt = Math.min(6, attempt + 1);
    state.workspaceCentralRetryAttempt = nextAttempt;
    const delayMs = Math.min(30000, 1000 * Math.pow(2, nextAttempt));
    window.setTimeout(() => {
      loadWorkspaceCentral().catch(() => {});
    }, delayMs);
    return;
  }
  hideUiToast();
  state.workspaceCentralRetryAttempt = 0;
  state.workspaces = data.rows || [];
  renderWorkspaceKpis(data.summary || {});
  renderWorkspaceList(state.workspaces);
  renderHoldingOrgChart();
  const targetedWorkspace = findWorkspaceRecord(
    state.workspaces,
    normalizeTenantWorkspaceSlug(state.currentWorkspaceTarget || "", "")
  );
  const selectedId =
    targetedWorkspace?.id
      || (state.workspaces.some((row) => String(row.id || "") === String(state.currentWorkspaceId || ""))
      ? state.currentWorkspaceId
      : (state.workspaces[0] && state.workspaces[0].id) || "");
	  if (selectedId) {
	    await loadWorkspaceDetail(selectedId);
	  } else {
	    clearCurrentWorkspaceUi();
	    {
	      const tenantMode = (state.currentWorkspaceEntryMode || "platform") === "tenant";
	      const view = state.currentWorkspaceView || "overview";
	      setWorkspaceView(view, { forceTenantView: tenantMode && normalizeSimple(view) !== "operations" });
	    }
	    renderCompanyCards();
	  }
	  updateWorkspaceEntryChrome();
	};

const renderHoldingOrgChart = () => {
  if (!holdingOrgChart) {
    return;
  }
  const selectedYear = yearSelect?.value;
  const companies = state.empresas.map((empresa) => empresa.nombre);
  const siblings = companies.filter((name) => name !== AIE_COMPANY);
  const aieMembers = siblings;
  const resumenMap = new Map(
    state.resumen.map((item) => [item.empresa, item])
  );
  const buildNode = (name, isAie) => {
    const item = resumenMap.get(name);
    const lines = item ? buildCompanyMeta(item, selectedYear) : [];
    const metaHtml = lines
      .map((line) => `<div class="muted">${line}</div>`)
      .join("");
    return `
      <div class="org-node${isAie ? " org-aie" : ""}" data-empresa="${name}">
        <h4>${name}</h4>
        ${metaHtml}
        ${isAie ? '<div class="muted">Subsidiaria AIE</div>' : ""}
        <button type="button">Entrar</button>
      </div>
    `;
  };
  const root = `
    <ul>
      <li>
        <div class="org-node">
          <h4>Inmovere Holding</h4>
          <div class="muted">Grupo principal</div>
        </div>
        <ul>
          ${siblings
            .filter((name) => name !== AIE_COMPANY)
            .map(
              (name) => `
            <li>
              ${buildNode(name, false)}
            </li>
          `
            )
            .join("")}
          <li class="org-aie-node">
            ${buildNode(AIE_COMPANY, true)}
            <div class="muted">Socias: ${aieMembers.join(" · ")}</div>
          </li>
        </ul>
      </li>
    </ul>
  `;
  holdingOrgChart.innerHTML = root;
  holdingOrgChart.querySelectorAll(".org-node button").forEach((btn) => {
    btn.addEventListener("click", (event) => {
      const node = event.currentTarget.closest(".org-node");
      if (!node) return;
      const name = node.dataset.empresa;
      if (name) {
        openCompany(name);
      }
    });
  });
};

