const renderEditableGrid = (grid, fields, data, target) => {
  if (!grid) return;
  grid.classList.remove("editable-grid--inmueble", "editable-grid--captacion", "editable-grid--cliente");
  grid.classList.add(`editable-grid--${target}`);
  grid.innerHTML = "";
  const tipoPersonaValue =
    target === "cliente" ? String(data?.tipo_persona || "").toLowerCase() : "";
  const isJuridica = target === "cliente" && tipoPersonaValue === "jurídica";
  const isInmueble = target === "inmueble";
  const sectionCopy = {
    "Prioridad comercial": "Datos que definen el objetivo y la situación comercial del inmueble.",
    "Ubicación y Catastro": "Localización, referencia catastral y soporte de geolocalización.",
    "Características": "Información física y descriptiva útil para comercialización y matching.",
    "Referencia económica": "Importes de trabajo para valoración, adquisición y control interno.",
    "Coordenadas": "Datos técnicos de geolocalización, secundarios frente a la dirección.",
    "Propiedad y origen": "Personas implicadas y origen del expediente comercial.",
    Pipeline: "Estado, prioridad y siguiente paso del expediente.",
    "Notas internas": "Observaciones operativas no visibles para cliente.",
  };
  const inputMap = {};
  const cardMap = {};
  let currentSection = "";
  fields.forEach((field) => {
    if (field && field.hidden) {
      return;
    }
    if (target === "cliente" && field.key === "apellidos" && isJuridica) {
      return;
    }
    if (field.section && field.section !== currentSection) {
      currentSection = field.section;
      const section = document.createElement("div");
      section.className = "form-section";
      section.innerHTML = `
        <strong>${field.section}</strong>
        ${sectionCopy[field.section] ? `<span>${sectionCopy[field.section]}</span>` : ""}
      `;
      grid.appendChild(section);
    }
    const card = document.createElement("div");
    card.className = "card editable-card";
    if (isInmueble) {
      if (field.section === "Ubicación y Catastro") card.classList.add("editable-card--location");
      if (field.section === "Coordenadas") card.classList.add("editable-card--technical");
      if (field.key === "referencia_catastral") card.classList.add("editable-card--catastro");
      if (isMoneyColumnKey(field.key)) card.classList.add("editable-card--money");
    }
    if (target === "cliente") {
      cardMap[field.key] = card;
    }
    const label = document.createElement("h3");
    if (target === "cliente" && field.key === "nombre") {
      label.textContent = isJuridica ? "Nombre social" : "Nombre";
    } else if (target === "cliente" && field.key === "nif") {
      label.textContent = isJuridica ? "CIF" : "DNI";
    } else {
      label.textContent = field.label;
    }
    if (target === "inmueble" || target === "captacion") {
      const requiredBadge = document.createElement("span");
      requiredBadge.className = "editable-field-hint";
      if ((field.key === "direccion") || (field.key === "tipo_inmueble") || (field.key === "precio_objetivo") || (field.key === "honorarios") || (field.key === "situacion_ocupacion") || (field.key === "propietario")) {
        requiredBadge.textContent = "Clave";
      } else if (field.key === "referencia_catastral") {
        requiredBadge.textContent = "Obligatorio desde reservado";
      } else if (field.key === "proxima_accion" || field.key === "asesor") {
        requiredBadge.textContent = "Seguimiento";
      }
      if (requiredBadge.textContent) {
        label.appendChild(requiredBadge);
      }
    }
    card.appendChild(label);

    let input;
    const currentValue =
      data && data[field.key] !== undefined && data[field.key] !== null
        ? data[field.key]
        : "";
    if (field.type === "select") {
      input = document.createElement("select");
      const options = field.options || [];
      const normalizedOptions = options.map((option) => {
        if (option && typeof option === "object") {
          return { value: String(option.value ?? ""), label: String(option.label ?? option.value ?? "") };
        }
        return { value: String(option ?? ""), label: String(option ?? "") };
      });
      normalizedOptions.forEach((option) => {
        input.appendChild(createOption(option.value, option.label));
      });
      const normalizedCurrent = String(currentValue ?? "");
      if (normalizedCurrent && !normalizedOptions.some((opt) => opt.value === normalizedCurrent)) {
        input.appendChild(createOption(normalizedCurrent, normalizedCurrent));
      }
      if (normalizedCurrent) {
        input.value = normalizedCurrent;
      }
    } else if (field.type === "textarea") {
      input = document.createElement("textarea");
      input.rows = 3;
      input.value = currentValue || "";
    } else {
      input = document.createElement("input");
      input.type = field.type || "text";
      if (target === "cliente" && field.key === "nif") {
        input.value = normalizeDocumento(currentValue);
      } else if (target === "cliente" && field.key === "nombre") {
        input.value = formatNombreCliente(currentValue);
      } else if ((target === "cliente" || isInmueble || target === "captacion") && isMoneyColumnKey(field.key)) {
        input.value = formatMoneyInputValue(currentValue);
      } else {
        input.value = currentValue || "";
      }
    }
    input.classList.add("inline-input");
    input.dataset.target = target;
    input.dataset.field = field.key;
    if (target === "cliente" || isInmueble) {
      inputMap[field.key] = input;
    }

    let status;
    if (target === "cliente" && field.key === "nif") {
      status = document.createElement("div");
      status.className = "muted";
      status.textContent = input.value
        ? isValidDocumento(input.value)
          ? "Documento válido"
          : "Documento no válido"
        : "";
    }

    const saveHandler = () => {
      if (target === "cliente" && (field.key === "nombre" || field.key === "apellidos")) {
        saveClienteNombreApellidos();
        return;
      }
      const value =
        target === "cliente" && field.key === "nif"
          ? normalizeDocumento(input.value)
          : input.value;
      if (target === "inmueble") {
        saveInmuebleField(field.key, value);
      } else if (target === "captacion") {
        saveCaptacionField(field.key, value);
      } else if (target === "cliente") {
        saveClienteField(field.key, value);
      }
    };

    if (field.type === "select") {
      input.addEventListener("change", saveHandler);
    } else {
      input.addEventListener("input", () => {
        if (status) {
          const val = input.value;
          status.textContent = val
            ? isValidDocumento(val)
              ? "Documento válido"
              : "Documento no válido"
            : "";
        }
        scheduleSave(`${target}:${field.key}`, saveHandler);
      });
      if ((target === "cliente" || isInmueble || target === "captacion") && isMoneyColumnKey(field.key)) {
        input.addEventListener("blur", () => {
          const parsed = toNumber(input.value);
          if (parsed !== null) {
            input.value = formatMoneyInputValue(parsed);
          }
        });
      }
      input.addEventListener("blur", saveHandler);
    }
    card.appendChild(input);
    if (status) {
      card.appendChild(status);
    }
    if (isInmueble && field.key === "referencia_catastral") {
      const hint = document.createElement("p");
      hint.className = "muted editable-card-help";
      hint.textContent = "Busca la referencia desde la dirección y genera la ficha PDF para dejar constancia en el expediente.";
      card.appendChild(hint);
      const actions = document.createElement("div");
      actions.className = "catastro-actions";
      const openBtn = document.createElement("button");
      openBtn.type = "button";
      openBtn.className = "secondary catastro-button";
      openBtn.innerHTML = buildCatastroButtonInner("Abrir Catastro");
      openBtn.addEventListener("click", () => {
        const ref = String(refInput ? refInput.value : "").trim();
        const address = buildInmuebleDisplayAddress({
          direccion: String(inputMap?.direccion?.value || "").trim(),
          poblacion: String(inputMap?.poblacion?.value || "").trim(),
          provincia: String(inputMap?.provincia?.value || "").trim(),
          codigo_postal: String(inputMap?.codigo_postal?.value || "").trim(),
        });
        const url = buildCatastroUrl(ref, address);
        window.open(url, "_blank", "noopener");
      });
      actions.appendChild(openBtn);
      const lookupBtn = document.createElement("button");
      lookupBtn.type = "button";
      lookupBtn.className = "secondary catastro-button";
      lookupBtn.innerHTML = buildCatastroButtonInner("Buscar referencia");
      lookupBtn.addEventListener("click", async () => {
        await lookupInmuebleCatastro(inputMap, { silent: false });
      });
      actions.appendChild(lookupBtn);
      const syncBtn = document.createElement("button");
      syncBtn.type = "button";
      syncBtn.className = "secondary catastro-button";
      syncBtn.innerHTML = buildCatastroButtonInner("Ficha PDF");
      syncBtn.addEventListener("click", async () => {
        await syncInmuebleCatastroFicha(inputMap);
      });
      actions.appendChild(syncBtn);
      card.appendChild(actions);
    }
    grid.appendChild(card);
  });

  if (target === "cliente" && inputMap.codigo_postal) {
    const cpInput = inputMap.codigo_postal;
    const provinciaInput = inputMap.provincia;
    const poblacionInput = inputMap.poblacion;
    let poblacionSelect = null;
    if (poblacionInput && cardMap.poblacion) {
      poblacionSelect = document.createElement("select");
      poblacionSelect.className = "postal-options hidden";
      poblacionSelect.appendChild(createOption("", "Selecciona población"));
      cardMap.poblacion.appendChild(poblacionSelect);
      poblacionSelect.addEventListener("change", () => {
        const value = poblacionSelect.value;
        if (!value) return;
        poblacionInput.value = value;
        poblacionInput.dataset.auto = "0";
        saveClienteField("poblacion", value);
        if (poblacionSelect.dataset.provincia) {
          provinciaInput.value = poblacionSelect.dataset.provincia;
          saveClienteField("provincia", poblacionSelect.dataset.provincia);
        }
      });
    }
    if (poblacionInput) {
      poblacionInput.addEventListener("input", () => {
        poblacionInput.dataset.auto = "0";
      });
    }
    const applyPostal = () => {
      const fallback = getPostalInfo(cpInput.value);
      fetchPostalLookup(cpInput.value).then((info) => {
        const resolved = info || fallback;
        if (!resolved) return;
        const provinciaValue = resolved.provincia || fallback?.provincia || "";
        const poblacionValue = resolved.poblacion || fallback?.poblacion || "";
        if (provinciaInput && provinciaValue) {
          provinciaInput.value = provinciaValue;
          saveClienteField("provincia", provinciaValue);
        }
        if (poblacionInput && poblacionValue) {
          const shouldAuto =
            !poblacionInput.value || poblacionInput.dataset.auto === "1";
          if (shouldAuto) {
            poblacionInput.value = poblacionValue;
            poblacionInput.dataset.auto = "1";
            saveClienteField("poblacion", poblacionValue);
          }
        }
        if (poblacionSelect) {
          const options = (info && info.opciones) || [];
          const unique = Array.from(
            new Set(options.map((opt) => opt.poblacion).filter(Boolean))
          );
          poblacionSelect.innerHTML = "";
          poblacionSelect.appendChild(createOption("", "Selecciona población"));
          unique.forEach((name) => {
            poblacionSelect.appendChild(createOption(name, name));
          });
          if (unique.length > 1) {
            poblacionSelect.classList.remove("hidden");
            poblacionSelect.dataset.provincia = provinciaValue || "";
          } else {
            poblacionSelect.classList.add("hidden");
            poblacionSelect.dataset.provincia = "";
          }
        }
      });
    };
    cpInput.addEventListener("input", () => {
      cpInput.value = normalizePostalCode(cpInput.value);
      scheduleSave(`cliente:codigo_postal`, () => {
        saveClienteField("codigo_postal", cpInput.value);
        applyPostal();
      });
    });
    cpInput.addEventListener("blur", () => {
      cpInput.value = normalizePostalCode(cpInput.value);
      saveClienteField("codigo_postal", cpInput.value);
      applyPostal();
    });
    applyPostal();
  }

  if (isInmueble) {
    const direccionInput = inputMap.direccion;
    // Lat/Lon no forman parte del formulario: se guardan internamente en background.
    if (direccionInput) {
      direccionInput.addEventListener("blur", () => {
        const street = String(direccionInput.value || "").trim();
        if (!street) return;
        geocodeInmuebleAddress(street, null, null, { force: true });
        scheduleAutoInmuebleCatastroLookup(inputMap);
      });
    }
    ["poblacion", "provincia", "codigo_postal"].forEach((key) => {
      const el = inputMap[key];
      if (!el) return;
      el.addEventListener("blur", () => {
        scheduleAutoInmuebleCatastroLookup(inputMap);
      });
    });
  }
};

let inmuebleGeocodeTimer = null;
let lastGeocodeKey = "";
let lastGeocodeAt = 0;

const renderMapPreview = (container, lat, lon, address = "") => {
  if (!container) return;
  const geocodeState = String(container.dataset.geocode || "").trim();
  if (!lat || !lon) {
    const safeAddress = String(address || "").trim();
    const searchUrl = safeAddress
      ? `https://www.openstreetmap.org/search?query=${encodeURIComponent(safeAddress)}`
      : "https://www.openstreetmap.org/";
    const message = safeAddress
      ? geocodeState === "failed"
        ? `No se pudo geolocalizar ${safeAddress}. Revisa dirección/población/provincia y vuelve a intentar.`
        : `Se intentará geolocalizar ${safeAddress} automáticamente.`
      : "Añade al menos la dirección (mejor si incluyes población o provincia) para dibujar la localización.";
    container.innerHTML = `
      <div class="map-box-empty">
        <strong>Mapa pendiente</strong>
        <p class="muted">${escapeHtml(message)}</p>
        <div class="map-box-meta">
          <a class="muted" href="${searchUrl}" target="_blank" rel="noreferrer">Buscar en OpenStreetMap</a>
        </div>
      </div>
    `;
    return;
  }
  container.dataset.geocode = "ok";
  const center = `${lat},${lon}`;
  // Usamos embed oficial de OpenStreetMap para evitar depender de un proveedor de "static maps" externo.
  const delta = 0.006;
  const bbox = [
    Number(lon) - delta,
    Number(lat) - delta,
    Number(lon) + delta,
    Number(lat) + delta,
  ];
  const embedUrl = `https://www.openstreetmap.org/export/embed.html?bbox=${encodeURIComponent(
    `${bbox[0]},${bbox[1]},${bbox[2]},${bbox[3]}`
  )}&layer=mapnik&marker=${encodeURIComponent(`${lat},${lon}`)}`;
  const osmUrl = `https://www.openstreetmap.org/?mlat=${lat}&mlon=${lon}#map=16/${lat}/${lon}`;
  container.innerHTML = `
    <iframe
      class="map-box-embed"
      title="Mapa de localización ${escapeHtml(address || center)}"
      loading="lazy"
      referrerpolicy="no-referrer"
      src="${embedUrl}"
    ></iframe>
    <div class="map-box-meta">
      <span class="muted">${escapeHtml(address || center)}</span>
      <a class="muted" href="${osmUrl}" target="_blank" rel="noreferrer">Abrir en OpenStreetMap</a>
    </div>
  `;
};

const updateInmuebleMap = (lat, lon, address = "") => {
  renderMapPreview(inmuebleMap, lat, lon, address);
};

const updateCaptacionMap = (lat, lon) => {
  renderMapPreview(captacionMap, lat, lon);
};

const CATASTRO_ICON_HTML = `
  <img class="catastro-logo-img" src="icons/catastro.png" alt="" loading="lazy" />
`.trim();

const buildCatastroButtonInner = (label) =>
  `<span class="catastro-icon catastro-icon--catastro" aria-hidden="true">${CATASTRO_ICON_HTML}</span><span>${label}</span>`;

const buildCatastroUrl = (ref, address) => {
  const cleanRef = String(ref || "")
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, "");
  if (cleanRef.length >= 14) {
    const rc1 = cleanRef.slice(0, 7);
    const rc2 = cleanRef.slice(7, 14);
    return `https://www1.sedecatastro.gob.es/CYCBienInmueble/OVCListaBienes.aspx?RC1=${encodeURIComponent(rc1)}&RC2=${encodeURIComponent(rc2)}`;
  }
  if (String(address || "").trim()) {
    return "https://www.sedecatastro.gob.es/";
  }
  return "https://www.sedecatastro.gob.es/";
};

// Fallback de geocodificación en cliente: si el backend no puede resolver (bloqueo/red/DNS),
// intentamos desde el navegador con proveedores que suelen permitir CORS.
const clientSideGeocodeLookup = async (query) => {
  const q = String(query || "").trim();
  if (!q) return null;

  const candidates = (() => {
    const parts = q.split(",").map((p) => p.trim()).filter(Boolean);
    const first = parts[0] || q;
    let simplified = first;
    simplified = simplified.replace(/\b\d+\s+[A-Z]{1,2}\b$/i, "").trim();
    simplified = simplified.replace(/\b\d+\s+\d+\s*[A-Z]?\b$/i, (m) => m.split(/\s+/)[0]).trim();
    simplified = simplified.replace(/\b(piso|planta|pta\.?|puerta|portal|bloque|esc|escalera)\b.*$/i, "").trim();
    const baseTail = parts.slice(1).join(", ");
    const list = [];
    const push = (value) => {
      const text = String(value || "").replace(/\s+/g, " ").trim();
      if (text && !list.includes(text)) list.push(text);
    };
    push(q);
    if (simplified && simplified !== first) push([simplified, baseTail].filter(Boolean).join(", "));
    if (simplified) push(simplified);
    if (first) push(first);
    return list;
  })();

  const tryPhoton = async (candidate) => {
    const url = `https://photon.komoot.io/api/?q=${encodeURIComponent(candidate)}&limit=1&lang=es`;
    const res = await fetch(url, { headers: { "Accept-Language": "es" } });
    if (!res.ok) return null;
    const payload = await res.json();
    const feat = (payload?.features || [])[0];
    const coords = feat?.geometry?.coordinates || [];
    if (coords.length < 2) return null;
    const lon = Number(coords[0]);
    const lat = Number(coords[1]);
    if (!Number.isFinite(lat) || !Number.isFinite(lon)) return null;
    const props = feat?.properties || {};
    return {
      provider: "photon-browser",
      lat,
      lon,
      display_name: props.name || props.street || props.city || candidate,
    };
  };

  const tryNominatim = async (candidate) => {
    const url = `https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&countrycodes=es&q=${encodeURIComponent(candidate)}`;
    const res = await fetch(url, { headers: { "Accept-Language": "es" } });
    if (!res.ok) return null;
    const rows = await res.json();
    const row = Array.isArray(rows) ? rows[0] : null;
    if (!row) return null;
    const lat = Number(row.lat);
    const lon = Number(row.lon);
    if (!Number.isFinite(lat) || !Number.isFinite(lon)) return null;
    return {
      provider: "nominatim-browser",
      lat,
      lon,
      display_name: row.display_name || candidate,
    };
  };

  const tryArcgis = async (candidate) => {
    const url = `https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates?f=json&maxLocations=1&outFields=Match_addr,Addr_type&sourceCountry=ESP&singleLine=${encodeURIComponent(candidate)}`;
    const res = await fetch(url, { headers: { "Accept-Language": "es" } });
    if (!res.ok) return null;
    const payload = await res.json();
    const row = (payload?.candidates || [])[0];
    if (!row) return null;
    const loc = row.location || {};
    const lat = Number(loc.y);
    const lon = Number(loc.x);
    if (!Number.isFinite(lat) || !Number.isFinite(lon)) return null;
    return {
      provider: "arcgis-browser",
      lat,
      lon,
      display_name: row.address || candidate,
    };
  };

  const providers = [tryPhoton, tryNominatim, tryArcgis];
  for (const candidate of candidates) {
    for (const fn of providers) {
      try {
        const hit = await fn(candidate);
        if (hit) {
          hit.query_used = candidate;
          hit.query_attempts = candidates.slice();
          return hit;
        }
      } catch {}
    }
  }
  return null;
};

const geocodeInmuebleAddress = (direccion, latInput, lonInput, options = {}) => {
  const street = String(direccion || "").trim();
  if (!street) return;
  if (inmuebleMap) inmuebleMap.dataset.geocode = "pending";
  const poblacion = document.querySelector('.inline-input[data-target="inmueble"][data-field="poblacion"]');
  const provincia = document.querySelector('.inline-input[data-target="inmueble"][data-field="provincia"]');
  const codigoPostal = document.querySelector('.inline-input[data-target="inmueble"][data-field="codigo_postal"]');
  const displayAddress = buildInmuebleDisplayAddress({
    direccion: street,
    poblacion: poblacion?.value || "",
    provincia: provincia?.value || "",
    codigo_postal: codigoPostal?.value || "",
  });
  updateInmuebleMap(null, null, displayAddress || street);
  if (inmuebleGeocodeTimer) {
    clearTimeout(inmuebleGeocodeTimer);
  }
  inmuebleGeocodeTimer = setTimeout(() => {
    const now = Date.now();
    const municipioVal = String(poblacion?.value || "").trim();
    const provinciaVal = String(provincia?.value || "").trim();
    const cpVal = String(codigoPostal?.value || "").trim();
    const key = [street, municipioVal, provinciaVal, cpVal].map((v) => normalizeSimple(v)).join("|");
    const force = Boolean(options && options.force);
    const allowRetry = force || !lastGeocodeKey || key !== lastGeocodeKey || (now - lastGeocodeAt) > 20000;
    if (!allowRetry) {
      return;
    }
    lastGeocodeKey = key;
    lastGeocodeAt = now;
    const params = new URLSearchParams({ q: street });
    if (municipioVal) params.set("municipio", municipioVal);
    if (provinciaVal) params.set("provincia", provinciaVal);
    if (cpVal) params.set("codigo_postal", cpVal);
    api(`/api/geocode_lookup?${params.toString()}`)
      .then(async (data) => {
        if (!data?.ok) {
          const fallback = await clientSideGeocodeLookup(displayAddress || street);
          if (fallback) {
            const lat = Number(fallback.lat);
            const lon = Number(fallback.lon);
            if (!Number.isFinite(lat) || !Number.isFinite(lon)) return;
            if (latInput) latInput.value = String(lat);
            if (lonInput) lonInput.value = String(lon);
            saveInmuebleField("lat", lat);
            saveInmuebleField("lon", lon);
            updateInmuebleMap(lat, lon, displayAddress || street);
            return;
          }
          if (inmuebleMap) inmuebleMap.dataset.geocode = "failed";
          updateInmuebleMap(null, null, displayAddress || street);
          return;
        }
        const lat = Number(data.lat);
        const lon = Number(data.lon);
        if (Number.isNaN(lat) || Number.isNaN(lon)) return;
        if (latInput) latInput.value = String(lat);
        if (lonInput) lonInput.value = String(lon);
        saveInmuebleField("lat", lat);
        saveInmuebleField("lon", lon);
        updateInmuebleMap(lat, lon, displayAddress || street);
      })
      .catch(async () => {
        const fallback = await clientSideGeocodeLookup(displayAddress || street);
        if (fallback) {
          const lat = Number(fallback.lat);
          const lon = Number(fallback.lon);
          if (!Number.isFinite(lat) || !Number.isFinite(lon)) return;
          if (latInput) latInput.value = String(lat);
          if (lonInput) lonInput.value = String(lon);
          saveInmuebleField("lat", lat);
          saveInmuebleField("lon", lon);
          updateInmuebleMap(lat, lon, displayAddress || street);
          return;
        }
        if (inmuebleMap) inmuebleMap.dataset.geocode = "failed";
        updateInmuebleMap(null, null, displayAddress || street);
      });
  }, 600);
};

const runInmuebleGeocodeFromUi = () => {
  const direccion = document.querySelector('.inline-input[data-target="inmueble"][data-field="direccion"]')?.value || "";
  if (!String(direccion || "").trim()) {
    showUiError("No se pudo localizar", "Falta dirección/población/provincia.");
    return;
  }
  geocodeInmuebleAddress(direccion, null, null, { force: true });
  scheduleAutoInmuebleCatastroLookup(getInmuebleCatastroInputMapFromDom(), { force: true });
};

const geocodeCaptacionAddress = () => {
  const direccionInput = getCaptacionField("direccion");
  const poblacionInput = getCaptacionField("poblacion");
  const provinciaInput = getCaptacionField("provincia");
  const codigoPostalInput = getCaptacionField("codigo_postal");
  const latInput = getCaptacionField("lat");
  const lonInput = getCaptacionField("lon");
  if (!direccionInput || !captacionMap) return;
  const pieces = [
    String(direccionInput.value || "").trim(),
    String(poblacionInput ? poblacionInput.value : "").trim(),
    String(provinciaInput ? provinciaInput.value : "").trim(),
    "España",
  ].filter(Boolean);
  const address = pieces.join(", ");
  if (!address) return;
  const params = new URLSearchParams({ q: address });
  if (poblacionInput?.value) params.set("municipio", poblacionInput.value);
  if (provinciaInput?.value) params.set("provincia", provinciaInput.value);
  if (codigoPostalInput?.value) params.set("codigo_postal", codigoPostalInput.value);
  api(`/api/geocode_lookup?${params.toString()}`)
    .then((data) => {
      if (!data?.ok) return;
      const lat = Number(data.lat);
      const lon = Number(data.lon);
      if (Number.isNaN(lat) || Number.isNaN(lon)) return;
      if (latInput) latInput.value = String(lat);
      if (lonInput) lonInput.value = String(lon);
      updateCaptacionMap(lat, lon);
    })
    .catch(() => {});
};

const getCaptacionField = (name) =>
  captacionForm ? captacionForm.querySelector(`[name="${name}"]`) : null;

const applyCaptacionOwnerMatch = (cliente, options = {}) => {
  if (!cliente) return;
  const nombreInput = getCaptacionField("propietario");
  const nifInput = getCaptacionField("propietario_nif");
  const telefonoInput = getCaptacionField("propietario_telefono");
  const emailInput = getCaptacionField("propietario_email");
  if (nombreInput && !String(nombreInput.value || "").trim()) {
    nombreInput.value = cliente.nombre || "";
  }
  if (nifInput && cliente.nif) {
    nifInput.value = normalizeNifValue(cliente.nif);
  }
  if (telefonoInput && !String(telefonoInput.value || "").trim()) {
    telefonoInput.value = cliente.telefono || "";
  }
  if (emailInput && !String(emailInput.value || "").trim()) {
    emailInput.value = cliente.email || "";
  }
  if (captacionPropietarios && cliente.id) {
    const selected = new Set(
      Array.from(captacionPropietarios.selectedOptions || [])
        .map((option) => String(option.value || "").trim())
        .filter(Boolean)
    );
    selected.add(String(cliente.id));
    setMultiSelectValues(captacionPropietarios, Array.from(selected));
  }
  if (captacionPropietarioStatus) {
    captacionPropietarioStatus.textContent =
      options.message || `Cliente detectado y vinculado: ${cliente.nombre || cliente.id}`;
  }
};

const syncCaptacionOwnerByNif = async () => {
  const nifInput = getCaptacionField("propietario_nif");
  if (!nifInput) return;
  const nif = normalizeNifValue(nifInput.value);
  nifInput.value = nif;
  if (!nif) {
    if (captacionPropietarioStatus) captacionPropietarioStatus.textContent = "";
    return;
  }
  try {
    const data = await api(`/api/cliente_lookup?nif=${encodeURIComponent(nif)}`);
    if (data?.found && data?.cliente) {
      applyCaptacionOwnerMatch(data.cliente);
      return;
    }
    if (captacionPropietarioStatus) {
      captacionPropietarioStatus.textContent = "No existe cliente con ese DNI/NIF. Se creará al guardar.";
    }
  } catch {
    if (captacionPropietarioStatus) {
      captacionPropietarioStatus.textContent = "No se pudo validar el DNI/NIF ahora mismo.";
    }
  }
};

const syncCaptacionOwnerByName = async () => {
  const nombreInput = getCaptacionField("propietario");
  const nifInput = getCaptacionField("propietario_nif");
  if (!nombreInput) return;
  if (normalizeNifValue(nifInput ? nifInput.value : "")) return;
  if (!String(nombreInput.value || "").trim()) return;
  try {
    const match = await lookupClienteByNombre(nombreInput.value);
    if (!match?.id) return;
    applyCaptacionOwnerMatch(match, { message: `Cliente vinculado por nombre: ${match.nombre}` });
  } catch {}
};

const chooseCatastroCandidate = (candidates = [], title = "Selecciona referencia catastral") => {
  const list = Array.isArray(candidates) ? candidates.filter((item) => item?.referencia_catastral) : [];
  if (!list.length) return null;
  if (list.length === 1) return list[0];
  const message = [
    title,
    "",
    ...list.map(
      (item, index) =>
        `${index + 1}. ${item.label || "Inmueble"} · ${item.referencia_catastral}`
    ),
    "",
    "Escribe el número de la opción.",
  ].join("\n");
  const answer = window.prompt(message, "1");
  const index = Number(answer || 0);
  if (!Number.isInteger(index) || index < 1 || index > list.length) {
    return null;
  }
  return list[index - 1];
};

let inmuebleCatastroTimer = null;
let lastCatastroLookupKey = "";

const buildInmuebleCatastroLookupPayload = (inputMap = {}) => ({
  direccion: String(inputMap?.direccion?.value || "").trim(),
  provincia: String(inputMap?.provincia?.value || "").trim(),
  poblacion: String(inputMap?.poblacion?.value || "").trim(),
  codigo_postal: String(inputMap?.codigo_postal?.value || "").trim(),
});

const getInmuebleCatastroInputMapFromDom = () => ({
  direccion: document.querySelector('.inline-input[data-target="inmueble"][data-field="direccion"]'),
  provincia: document.querySelector('.inline-input[data-target="inmueble"][data-field="provincia"]'),
  poblacion: document.querySelector('.inline-input[data-target="inmueble"][data-field="poblacion"]'),
  codigo_postal: document.querySelector('.inline-input[data-target="inmueble"][data-field="codigo_postal"]'),
  referencia_catastral: document.querySelector('.inline-input[data-target="inmueble"][data-field="referencia_catastral"]'),
});

const scheduleAutoInmuebleCatastroLookup = (inputMap = {}, options = {}) => {
  const force = Boolean(options.force);
  if (!state.currentInmuebleId) return;
  const ref = String(
    inputMap?.referencia_catastral?.value ||
      state.currentInmueble?.referencia_catastral ||
      state.currentInmuebleContext?.inmueble?.referencia_catastral ||
      ""
  ).trim();
  if (!force && ref) return;
  const payload = buildInmuebleCatastroLookupPayload(inputMap);
  if (!payload.direccion) return;
  const key = JSON.stringify(payload).toLowerCase();
  if (!force && key === lastCatastroLookupKey) return;
  lastCatastroLookupKey = key;
  if (inmuebleCatastroTimer) clearTimeout(inmuebleCatastroTimer);
  inmuebleCatastroTimer = setTimeout(() => {
    lookupInmuebleCatastro(inputMap, { silent: true }).catch(() => {});
  }, 900);
};

const lookupCaptacionCatastro = async () => {
  const direccionInput = getCaptacionField("direccion");
  const provinciaInput = getCaptacionField("provincia");
  const poblacionInput = getCaptacionField("poblacion");
  const codigoPostalInput = getCaptacionField("codigo_postal");
  const refInput = getCaptacionField("referencia_catastral");
  if (!direccionInput) return;
  const direccion = String(direccionInput.value || "").trim();
  if (!direccion) {
    if (captacionCatastroStatus) captacionCatastroStatus.textContent = "Indica la dirección para consultar Catastro.";
    return;
  }
  if (captacionCatastroStatus) captacionCatastroStatus.textContent = "Consultando Catastro...";
  try {
    const payload = {
      direccion,
      provincia: provinciaInput ? provinciaInput.value.trim() : "",
      poblacion: poblacionInput ? poblacionInput.value.trim() : "",
      codigo_postal: codigoPostalInput ? codigoPostalInput.value.trim() : "",
      empresa_nombre: resolveCrmInmoEmpresaNombre(),
    };
    const data = await fetch("/api/inmueble_catastro_lookup", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      credentials: "same-origin",
      body: JSON.stringify(payload),
    }).then((res) => res.json());
    if (data?.error) {
      if (captacionCatastroStatus) captacionCatastroStatus.textContent = data.error;
      return;
    }
    if (data?.match_unique && data?.referencia_catastral && refInput) {
      refInput.value = data.referencia_catastral;
      if (captacionCatastroStatus) {
        captacionCatastroStatus.textContent = `Referencia catastral detectada: ${data.referencia_catastral}`;
      }
      return;
    }
    const count = Array.isArray(data?.candidates) ? data.candidates.length : 0;
    const selected = chooseCatastroCandidate(
      data?.candidates || [],
      "Catastro devolvió varias coincidencias para esta dirección"
    );
    if (selected?.referencia_catastral && refInput) {
      refInput.value = selected.referencia_catastral;
      if (captacionCatastroStatus) {
        captacionCatastroStatus.textContent = `Referencia catastral seleccionada: ${selected.referencia_catastral}`;
      }
      return;
    }
    if (captacionCatastroStatus) {
      captacionCatastroStatus.textContent =
        count > 1
          ? `Catastro devolvió ${count} coincidencias. Completa más la dirección o revisa manualmente.`
          : "Catastro no devolvió una coincidencia única.";
    }
  } catch {
    if (captacionCatastroStatus) {
      captacionCatastroStatus.textContent = "No se pudo consultar Catastro ahora mismo.";
    }
  }
};

const lookupInmuebleCatastro = async (inputMap = {}, options = {}) => {
  const silent = Boolean(options.silent);
  const direccionInput = inputMap.direccion;
  const provinciaInput = inputMap.provincia;
  const poblacionInput = inputMap.poblacion;
  const codigoPostalInput = inputMap.codigo_postal;
  const refInput = inputMap.referencia_catastral || inputMap.referencia;
  const direccion = String(direccionInput ? direccionInput.value : "").trim();
  if (!direccion) {
    if (!silent) setInmuebleSaveStatus("Indica la dirección para consultar Catastro.");
    return null;
  }
  if (!silent) setInmuebleSaveStatus("Consultando Catastro...");
  try {
    const payload = {
      direccion,
      provincia: provinciaInput ? provinciaInput.value.trim() : "",
      poblacion: poblacionInput ? poblacionInput.value.trim() : "",
      codigo_postal: codigoPostalInput ? codigoPostalInput.value.trim() : "",
      empresa_nombre: resolveCrmInmoEmpresaNombre(),
    };
    const data = await fetch("/api/inmueble_catastro_lookup", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      credentials: "same-origin",
      body: JSON.stringify(payload),
    }).then((res) => res.json());
    if (data?.error) {
      if (!silent) setInmuebleSaveStatus(data.error);
      return null;
    }
    if (data?.match_unique && data?.referencia_catastral) {
      if (refInput) {
        refInput.value = data.referencia_catastral;
      }
      saveInmuebleField("referencia_catastral", data.referencia_catastral);
      return data.referencia_catastral;
    }
    const count = Array.isArray(data?.candidates) ? data.candidates.length : 0;
    if (!silent) {
      const selected = chooseCatastroCandidate(
        data?.candidates || [],
        "Catastro devolvió varias coincidencias para este inmueble"
      );
      if (selected?.referencia_catastral) {
        if (refInput) {
          refInput.value = selected.referencia_catastral;
        }
        saveInmuebleField("referencia_catastral", selected.referencia_catastral);
        return selected.referencia_catastral;
      }
      setInmuebleSaveStatus(
        count > 1
          ? `Catastro devolvió ${count} coincidencias. Completa más la dirección.`
          : "Catastro no devolvió una coincidencia única."
      );
    }
    return null;
  } catch {
    if (!silent) setInmuebleSaveStatus("No se pudo consultar Catastro.");
    return null;
  }
};

const syncInmuebleCatastroFicha = async (inputMap = {}) => {
  if (!state.currentInmuebleId) return null;
  try {
    // Garantiza RC: si falta, la buscamos desde la dirección antes de pedir la ficha.
    const currentRef = String(
      inputMap?.referencia_catastral?.value ||
        state.currentInmueble?.referencia_catastral ||
        state.currentInmuebleContext?.inmueble?.referencia_catastral ||
        ""
    ).trim();
    if (!currentRef) {
      setInmuebleSaveStatus("Buscando referencia catastral...");
      const ensured = await lookupInmuebleCatastro(inputMap, { silent: false });
      if (!ensured) {
        setInmuebleSaveStatus("No se pudo detectar una referencia catastral única desde la dirección.");
        return null;
      }
    }
    setInmuebleSaveStatus("Obteniendo ficha catastral...");
    const data = await fetch("/api/inmueble_catastro_sync", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      credentials: "same-origin",
      body: JSON.stringify({
        inmueble_id: state.currentInmuebleId,
        usuario: getCurrentUser(),
        empresa_nombre: resolveCrmInmoEmpresaNombre(),
      }),
    }).then((res) => res.json());
    if (data?.error) {
      setInmuebleSaveStatus(data.error);
      return null;
    }
    const updates = data?.updates || {};
    Object.entries(updates).forEach(([key, value]) => {
      if (inputMap[key]) {
        inputMap[key].value = value ?? "";
      }
      if (state.currentInmueble) {
        state.currentInmueble[key] = value;
      }
      if (state.currentInmuebleContext?.inmueble) {
        state.currentInmuebleContext.inmueble[key] = value;
      }
    });
    refreshCurrentInmuebleHeader();
    if (state.currentInmuebleId) {
      loadInmuebleDocs(state.currentInmuebleId);
    }
    const docUrl = data?.document?.url || "";
    setInmuebleSaveStatus(
      docUrl
        ? "Ficha Catastro generada, datos sincronizados y documento guardado."
        : "Datos catastrales sincronizados."
    );
    if (docUrl) {
      window.open(docUrl, "_blank", "noopener");
    }
    return data;
  } catch {
    setInmuebleSaveStatus("No se pudo sincronizar Catastro.");
    return null;
  }
};

