const populateAgendaClientes = (listEl, inputEl, hiddenEl) => {
  if (!listEl) return;
  listEl.innerHTML = "";
  const clientes = Array.isArray(state.clientesList) ? state.clientesList : [];
  clientes.forEach((cliente) => {
    const option = document.createElement("option");
    option.value = formatNombreCliente(cliente.nombre);
    option.dataset.id = cliente.id;
    listEl.appendChild(option);
  });
  if (inputEl) {
    const handler = () => {
      const value = inputEl.value.trim();
      if (!value || !hiddenEl) return;
      const match = clientes.find(
        (c) => formatNombreCliente(c.nombre) === value
      );
      hiddenEl.value = match ? match.id : "";
    };
    inputEl.addEventListener("input", handler);
    inputEl.addEventListener("change", handler);
  }
};

const populateAgendaClientesFromCandidates = (listEl, inputEl, hiddenEl, candidates = []) => {
  if (!listEl) return;
  const cleaned = (Array.isArray(candidates) ? candidates : [])
    .map((row) => {
      const id = String(row.cliente_id || row.id || "").trim();
      const nombreRaw = row.nombre || row.cliente || row.cliente_nombre || row.propietario || "";
      const nombre = formatNombreCliente(nombreRaw);
      return { id, nombre };
    })
    .filter((item) => item.nombre);
  const seen = new Set();
  const unique = cleaned.filter((item) => {
    const key = normalizeSimple(item.nombre);
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
  listEl.innerHTML = "";
  unique.forEach((item) => {
    const option = document.createElement("option");
    option.value = item.nombre;
    option.dataset.id = item.id || "";
    listEl.appendChild(option);
  });
  if (!inputEl || !hiddenEl) return;
  const map = new Map(unique.map((item) => [normalizeSimple(item.nombre), item.id || ""]));
  inputEl._agendaCandidatesMap = map;
  if (inputEl.dataset.agendaBound === "1") return;
  inputEl.dataset.agendaBound = "1";
  const handler = () => {
    const value = normalizeSimple(inputEl.value || "");
    const id = (inputEl._agendaCandidatesMap && inputEl._agendaCandidatesMap.get(value)) || "";
    hiddenEl.value = id || "";
  };
  inputEl.addEventListener("input", handler);
  inputEl.addEventListener("change", handler);
};

const resolveClienteFromInput = (inputEl, hiddenEl) => {
  const clientes = Array.isArray(state.clientesList) ? state.clientesList : [];
  const nombre = inputEl ? inputEl.value.trim() : "";
  let clienteId = hiddenEl ? hiddenEl.value.trim() : "";
  if (!clienteId && nombre) {
    const match = clientes.find(
      (c) => formatNombreCliente(c.nombre) === nombre
    );
    if (match) {
      clienteId = match.id;
      if (hiddenEl) hiddenEl.value = clienteId;
    }
  }
  return { cliente_id: clienteId || "", cliente_nombre: nombre || "" };
};

const gestoriaContabilidadSegurosCache = new Map();
let segurosContabilidadAllCache = null;
let segurosContabilidadClientesCache = null;

const loadSegurosForClienteContabilidad = async (clienteId) => {
  const key = String(clienteId || "").trim();
  if (!key) return [];
  if (gestoriaContabilidadSegurosCache.has(key)) {
    return gestoriaContabilidadSegurosCache.get(key) || [];
  }
  try {
    const payload = await api(`/api/seguros_cliente?cliente_id=${encodeURIComponent(key)}&uploaded_only=0`);
    const rows = Array.isArray(payload?.rows) ? payload.rows : [];
    gestoriaContabilidadSegurosCache.set(key, rows);
    return rows;
  } catch {
    return [];
  }
};

const loadAllSegurosForContabilidad = async () => {
  if (Array.isArray(segurosContabilidadAllCache)) {
    return segurosContabilidadAllCache;
  }
  const empresa = state.empresas.find((e) => e.nombre === FINCAS_COMPANY);
  if (!empresa) return [];
  try {
    const params = new URLSearchParams({
      tabla: "seguros",
      empresa_id: empresa.id,
      include_id: "1",
    });
    const data = await api(`/api/tabla?${params.toString()}`);
    const columns = Array.isArray(data?.columns) ? data.columns : [];
    const rows = Array.isArray(data?.rows) ? data.rows : [];
    const idx = (name) => columns.indexOf(name);
    const idIndex = idx("id");
    const polizaIndex = idx("poliza_numero");
    const companiaIndex = idx("compania");
    const ramoIndex = idx("ramo");
    const clienteIndex = idx("cliente_id");
    segurosContabilidadAllCache = rows
      .map((row) => ({
        id: idIndex >= 0 ? row[idIndex] : "",
        poliza_numero: polizaIndex >= 0 ? row[polizaIndex] : "",
        compania: companiaIndex >= 0 ? row[companiaIndex] : "",
        ramo: ramoIndex >= 0 ? row[ramoIndex] : "",
        cliente_id: clienteIndex >= 0 ? row[clienteIndex] : "",
      }))
      .filter((row) => String(row.id || "").trim());
    return segurosContabilidadAllCache;
  } catch {
    return [];
  }
};

const loadClientesForSegurosContabilidad = async () => {
  if (Array.isArray(segurosContabilidadClientesCache)) {
    return segurosContabilidadClientesCache;
  }
  const empresa = state.empresas.find((e) => e.nombre === FINCAS_COMPANY);
  const params = new URLSearchParams({ servicio: "seguros" });
  if (empresa?.id) {
    params.set("empresa_id", empresa.id);
  }
  try {
    const rows = await api(`/api/clientes_list?${params.toString()}`);
    const list = Array.isArray(rows) ? rows : [];
    list.sort((a, b) => {
      const nameA = normalizeNombre(formatNombreCliente(a.nombre));
      const nameB = normalizeNombre(formatNombreCliente(b.nombre));
      return nameA.localeCompare(nameB, "es", { numeric: true, sensitivity: "base" });
    });
    segurosContabilidadClientesCache = list;
    return list;
  } catch {
    if (Array.isArray(state.clientesList) && state.clientesList.length) {
      segurosContabilidadClientesCache = state.clientesList;
      return state.clientesList;
    }
    return [];
  }
};

