const populateServiciosSelect = (selectEl, selectedValue = "") => {
  if (!selectEl) return;
  selectEl.innerHTML = "";
  selectEl.appendChild(createOption("", "Selecciona servicio"));
  SERVICE_OPTIONS.forEach((service) => {
    selectEl.appendChild(createOption(service, service));
  });
  if (selectedValue) {
    selectEl.value = selectedValue;
  }
};

const populateResponsableSelects = () => {
  if (!responsableSelects || !responsableSelects.length) return;
  const users = state.usersList || [];
  responsableSelects.forEach((selectEl) => {
    if (!selectEl) return;
    const serviceFilter = normalizeSimple(selectEl.dataset.service || "");
    const current = selectEl.value;
    const currentNorm = normalizeSimple(current);
    const used = new Set();
    const addOptionUnique = (value, label) => {
      const finalValue = String(value || "").trim();
      if (!finalValue) return;
      const key = normalizeSimple(finalValue);
      if (used.has(key)) return;
      used.add(key);
      selectEl.appendChild(createOption(finalValue, label || finalValue));
    };
    selectEl.innerHTML = "";
    selectEl.appendChild(createOption("", "Selecciona responsable"));
    if (serviceFilter === "seguros") {
      SEGUROS_RESPONSABLES_FIJOS.forEach((name) => addOptionUnique(name, name));
    }
    users
      .filter((user) => {
        if (!serviceFilter) return true;
        const service = normalizeSimple(user.servicio || "");
        if (!service) return true;
        if (service.includes(serviceFilter)) return true;
        if (["direccion", "administracion"].includes(service)) {
          return true;
        }
        return false;
      })
      .forEach((user) => {
      const label = `${user.nombre || ""} ${user.apellido || ""}`.trim();
      const value = user.usuario || label || user.nombre || "";
      addOptionUnique(value, label || value);
    });
    if (current) {
      selectEl.value = current;
      if (normalizeSimple(selectEl.value) !== currentNorm) {
        addOptionUnique(current, current);
        selectEl.value = current;
      }
    }
  });
};

const populateAsesorSelects = () => {
  if (!asesorSelects || !asesorSelects.length) return;
  asesorSelects.forEach((selectEl) => {
    if (!selectEl) return;
    const serviceFilter = normalizeSimple(selectEl.dataset.service || "");
    const current = String(selectEl.value || "").trim();
    const currentNorm = normalizeSimple(current);
    selectEl.innerHTML = "";
    selectEl.appendChild(createOption("", "Selecciona asesor"));
    if (serviceFilter === "inmobiliaria") {
      INMOBILIARIA_ASESORES.forEach((name) => selectEl.appendChild(createOption(name, name)));
    }
    if (current) {
      selectEl.value = current;
      if (normalizeSimple(selectEl.value) !== currentNorm) {
        // Valor legacy que no está en el catálogo fijo.
        selectEl.appendChild(createOption(current, current));
        selectEl.value = current;
      }
    }
  });
};

const loadUsuarios = () =>
  api("/api/usuarios").then((data) => {
    state.usersList = data.rows || [];
    populateResponsableSelects();
    populateAsesorSelects();
    refreshSegurosColaboradoresList();
    return state.usersList;
  });

const renderAdminServiceSelector = () => {
  if (!adminServiceMulti || !adminServicioInput) return;
  const selected = new Set(parseAdminServices(adminServicioInput.value));
  adminServiceMulti.innerHTML = "";
  ADMIN_SERVICE_OPTIONS.forEach((label) => {
    const key = normalizeSimple(label);
    const wrapper = document.createElement("label");
    wrapper.className = "admin-service-option";
    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.value = label;
    checkbox.checked = selected.has(label);
    checkbox.addEventListener("change", () => {
      const picked = Array.from(
        adminServiceMulti.querySelectorAll('input[type="checkbox"]:checked')
      ).map((el) => el.value);
      adminServicioInput.value = joinAdminServices(picked);
    });
    const span = document.createElement("span");
    span.textContent = label;
    wrapper.appendChild(checkbox);
    wrapper.appendChild(span);
    wrapper.dataset.key = key;
    adminServiceMulti.appendChild(wrapper);
  });
  adminServicioInput.value = joinAdminServices(Array.from(selected));
};

const createAdminServiceCheckboxGroup = (rawValue = "") => {
  const wrapper = document.createElement("div");
  wrapper.className = "admin-service-inline";
  const selected = new Set(parseAdminServices(rawValue));
  ADMIN_SERVICE_OPTIONS.forEach((label) => {
    const item = document.createElement("label");
    item.className = "admin-service-option";
    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.value = label;
    checkbox.checked = selected.has(label);
    const text = document.createElement("span");
    text.textContent = label;
    item.appendChild(checkbox);
    item.appendChild(text);
    wrapper.appendChild(item);
  });
  wrapper.getSelectedServices = () =>
    Array.from(wrapper.querySelectorAll('input[type="checkbox"]:checked')).map((el) => el.value);
  return wrapper;
};

const renderUsuariosSelect = () => {
  if (!userSelect) return;
  userSelect.innerHTML = "";
  state.usersList.forEach((user) => {
    const label = `${user.nombre || ""} ${user.apellido || ""}`.trim();
    const value = user.usuario || label || user.nombre;
    userSelect.appendChild(createOption(value, label));
  });
  const saved = getCurrentUser();
  const hasSaved = saved && state.usersList.some((user) => {
    const value = user.usuario || `${user.nombre || ""} ${user.apellido || ""}`.trim() || user.nombre;
    return normalizeSimple(value) === normalizeSimple(saved);
  });
  if (saved && hasSaved) {
    userSelect.value = saved;
  } else if (state.usersList.length) {
    const fallback = state.usersList[0];
    const fallbackValue = fallback.usuario || `${fallback.nombre || ""} ${fallback.apellido || ""}`.trim() || fallback.nombre || "";
    userSelect.value = fallbackValue;
    setCurrentUser(fallbackValue);
  } else {
    setCurrentUser("");
  }
  syncCurrentUserScope();
  hydrateWorkspaceTimeUserSelect();
};

const renderUsuariosTable = () => {
  if (!adminUsersTable || !adminUsersInfo) return;
  const rows = state.usersList;
  if (!rows.length) {
    adminUsersTable.innerHTML = "<p class='muted'>Sin usuarios.</p>";
    adminUsersInfo.textContent = "";
    if (adminUserDetailCard) adminUserDetailCard.classList.add("hidden");
    return;
  }

  const query = normalizeSimple(adminUsersSearch ? adminUsersSearch.value : "");
  const filtered = rows.filter((row) => {
    if (!query) return true;
    const haystack = normalizeSimple(
      [
        row.nombre || "",
        row.apellido || "",
        row.usuario || "",
        row.email || "",
        row.rol || "",
        row.servicio || "",
      ].join(" ")
    );
    return haystack.includes(query);
  });

  const list = document.createElement("div");
  list.className = "admin-users-list";
  filtered.forEach((row) => {
    const item = document.createElement("button");
    item.type = "button";
    item.className = "admin-user-item";
    item.classList.toggle("active", row.id === state.adminSelectedUserId);
    const name = `${row.nombre || ""} ${row.apellido || ""}`.trim() || row.usuario || "Usuario";
    item.innerHTML = `
      <div class="admin-user-name">${name}</div>
      <div class="admin-user-meta">${row.usuario || "-"} · ${row.rol || "Sin rol"}</div>
      <div class="admin-user-meta">${row.servicio || "Sin servicios"}${Number(row.registro_horario_activo || 0) === 1 ? " · Registro horario" : ""}</div>
    `;
    item.addEventListener("click", () => {
      state.adminSelectedUserId = row.id;
      renderUsuariosTable();
      renderAdminUserDetail();
    });
    list.appendChild(item);
  });

  adminUsersTable.innerHTML = "";
  if (!filtered.length) {
    adminUsersTable.innerHTML = "<p class='muted'>No hay usuarios con ese filtro.</p>";
  } else {
    adminUsersTable.appendChild(list);
  }
  adminUsersInfo.textContent = `Mostrando ${filtered.length} de ${rows.length} usuarios.`;
  if (!rows.some((row) => row.id === state.adminSelectedUserId)) {
    state.adminSelectedUserId = "";
  }
  renderAdminUserDetail();
};

const renderAdminUserDetail = () => {
  if (!adminUserDetail || !adminUserDetailCard || !adminUserDetailTitle) return;
  const user = (state.usersList || []).find((row) => row.id === state.adminSelectedUserId);
  if (!user) {
    adminUserDetailCard.classList.add("hidden");
    adminUserDetail.innerHTML = "";
    return;
  }
  adminUserDetailCard.classList.remove("hidden");
  const fullName = `${user.nombre || ""} ${user.apellido || ""}`.trim() || user.usuario || "Usuario";
  adminUserDetailTitle.textContent = `Ficha · ${fullName}`;
  adminUserDetail.innerHTML = "";
  const form = document.createElement("form");
  form.className = "form-grid admin-detail-grid";
  const status = document.createElement("span");
  status.className = "muted admin-detail-status";

  const buildInput = (labelText, value = "", opts = {}) => {
    const label = document.createElement("label");
    label.className = "admin-detail-field";
    label.textContent = labelText;
    const input = document.createElement("input");
    input.className = "inline-input";
    input.type = opts.type || "text";
    input.value = value || "";
    if (opts.placeholder) input.placeholder = opts.placeholder;
    label.appendChild(input);
    return { label, input };
  };
  const buildSelect = (labelText, options = [], current = "") => {
    const label = document.createElement("label");
    label.className = "admin-detail-field";
    label.textContent = labelText;
    const select = document.createElement("select");
    select.className = "inline-input";
    options.forEach((opt) => {
      select.appendChild(createOption(opt.value, opt.label));
    });
    select.value = current;
    label.appendChild(select);
    return { label, select };
  };
  const buildPasswordInput = (labelText, value = "", opts = {}) => {
    const label = document.createElement("label");
    label.className = "admin-detail-field";
    label.textContent = labelText;
    const shell = document.createElement("div");
    shell.className = "input-with-icon";
    const input = document.createElement("input");
    input.className = "inline-input";
    input.type = "password";
    input.value = value || "";
    if (opts.placeholder) input.placeholder = opts.placeholder;
    const toggle = document.createElement("button");
    toggle.type = "button";
    toggle.className = "icon-btn";
    toggle.setAttribute("aria-label", "Mostrar contraseña");
    toggle.textContent = "👁";
    toggle.addEventListener("click", () => {
      const isHidden = input.type === "password";
      input.type = isHidden ? "text" : "password";
      toggle.textContent = isHidden ? "🙈" : "👁";
      toggle.setAttribute("aria-label", isHidden ? "Ocultar contraseña" : "Mostrar contraseña");
    });
    shell.appendChild(input);
    shell.appendChild(toggle);
    label.appendChild(shell);
    return { label, input, toggle };
  };

  const nombre = buildInput("Nombre", user.nombre || "");
  const apellido = buildInput("Apellido", user.apellido || "");
  const usuario = buildInput("Usuario", user.usuario || "");
  const email = buildInput("Email", user.email || "", { type: "email" });
  const rol = buildSelect(
    "Rol",
    ADMIN_ROLE_OPTIONS.map((item) => ({ value: item, label: item })),
    user.rol || "Lectura"
  );
  const activo = buildSelect(
    "Estado",
    [
      { value: "1", label: "Activo" },
      { value: "0", label: "Inactivo" },
    ],
    user.activo ? "1" : "0"
  );
  const registroHorarioLabel = document.createElement("label");
  registroHorarioLabel.className = "admin-detail-field inline-check";
  const registroHorarioCheck = document.createElement("input");
  registroHorarioCheck.type = "checkbox";
  registroHorarioCheck.checked = Number(user.registro_horario_activo || 0) === 1;
  registroHorarioLabel.appendChild(registroHorarioCheck);
  registroHorarioLabel.appendChild(document.createTextNode(" Vincular a registro horario"));
  const password = buildPasswordInput("Nueva contraseña", "", { placeholder: "Opcional" });

  const serviciosLabel = document.createElement("label");
  serviciosLabel.className = "admin-detail-field admin-detail-services";
  serviciosLabel.textContent = "Servicios permitidos";
  const servicios = createAdminServiceCheckboxGroup(user.servicio || "");
  serviciosLabel.appendChild(servicios);

  [
    nombre.label,
    apellido.label,
    usuario.label,
    email.label,
    rol.label,
    activo.label,
    registroHorarioLabel,
    password.label,
    serviciosLabel,
  ].forEach((node) => form.appendChild(node));

  const actions = document.createElement("div");
  actions.className = "form-actions admin-detail-actions";
  const saveBtn = document.createElement("button");
  saveBtn.type = "submit";
  saveBtn.textContent = "Guardar cambios";
  const inviteBtn = document.createElement("button");
  inviteBtn.type = "button";
  inviteBtn.className = "secondary";
  inviteBtn.textContent = "Enviar invitación";
  const deleteBtn = document.createElement("button");
  deleteBtn.type = "button";
  deleteBtn.className = "secondary danger";
  deleteBtn.textContent = "Eliminar usuario";
  actions.appendChild(saveBtn);
  actions.appendChild(inviteBtn);
  actions.appendChild(deleteBtn);
  actions.appendChild(status);
  form.appendChild(actions);

  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const payload = {
      id: user.id,
      nombre: nombre.input.value.trim(),
      apellido: apellido.input.value.trim(),
      usuario: usuario.input.value.trim(),
      email: email.input.value.trim(),
      rol: rol.select.value,
      activo: activo.select.value,
      servicio: joinAdminServices(servicios.getSelectedServices()),
      registro_horario_activo: registroHorarioCheck.checked ? 1 : 0,
    };
    if (password.input.value.trim()) {
      payload.password = password.input.value.trim();
    }
    if (!payload.servicio) {
      status.textContent = "Selecciona al menos un servicio.";
      return;
    }
    status.textContent = "Guardando...";
    try {
      const data = await fetch("/api/usuarios_update", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      }).then((res) => res.json());
      if (data.error) {
        status.textContent = data.error;
        return;
      }
      status.textContent = "Guardado.";
      await loadUsuarios();
      renderUsuariosSelect();
      renderUsuariosTable();
      renderCompanyCards();
    } catch {
      status.textContent = "Error al guardar.";
    }
  });

  inviteBtn.addEventListener("click", async () => {
    status.textContent = "Enviando invitación...";
    try {
      const data = await fetch("/api/usuarios_invitar", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "same-origin",
        body: JSON.stringify({ id: user.id }),
      }).then((res) => res.json());
      if (data.error) {
        status.textContent = data.error;
        return;
      }
      status.textContent = data.sent
        ? "Invitación enviada."
        : "SMTP no configurado. Enlace copiado al portapapeles.";
      if (!data.sent && data.invite_link) {
        try { await navigator.clipboard?.writeText(data.invite_link); } catch {}
      }
    } catch {
      status.textContent = "Error al enviar invitación.";
    }
  });

  deleteBtn.addEventListener("click", async () => {
    if (!window.confirm("¿Eliminar este usuario?")) return;
    status.textContent = "Eliminando...";
    try {
      const data = await fetch("/api/usuarios_delete", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id: user.id }),
      }).then((res) => res.json());
      if (data.error) {
        status.textContent = data.error;
        return;
      }
      state.adminSelectedUserId = "";
      await loadUsuarios();
      renderUsuariosSelect();
      renderUsuariosTable();
      renderCompanyCards();
    } catch {
      status.textContent = "Error al eliminar.";
    }
  });

  adminUserDetail.appendChild(form);
};

