const loadFinHipotecasRegistradas = () => {
  if (!finCrmTable || !finCrmInfo) return;
  const empresa = state.empresas.find((e) => e.nombre === FIN_COMPANY);
  if (!empresa?.id) {
    finCrmTable.innerHTML = "<p class='muted'>Sin empresa.</p>";
    finCrmInfo.textContent = "";
    return;
  }
  populateAgendaClientes(finCrmClientes, finCrmClienteInput, finCrmClienteId);
  const q = finCrmSearch ? finCrmSearch.value.trim() : "";
  const params = new URLSearchParams({
    tabla: "hipotecas",
    empresa_id: empresa.id,
    q,
  });
  api(`/api/tabla?${params.toString()}`).then((data) => {
    const columns = data.columns || [];
    let rows = data.rows || [];
    const filtroCliente = finCrmClienteInput ? finCrmClienteInput.value.trim().toLowerCase() : "";
    if (filtroCliente) {
      const clienteIndex = columns.indexOf("cliente");
      if (clienteIndex >= 0) {
        rows = rows.filter((row) => String(row[clienteIndex] || "").toLowerCase().includes(filtroCliente));
      }
    }
    renderTableInto({ columns, rows }, finCrmTable, finCrmInfo, "Hipotecas");
  });
};

const loadFinInmobiliarias = () => {
  if (!finAsesorInmobiliaria) return;
  api("/api/fin_inmobiliarias").then((data) => {
    const list = (data.items || []).filter(Boolean);
    const current = finAsesorInmobiliaria.value;
    finAsesorInmobiliaria.innerHTML = "";
    finAsesorInmobiliaria.appendChild(createOption("", "Selecciona inmobiliaria"));
    list.forEach((item) => {
      finAsesorInmobiliaria.appendChild(createOption(item, item));
    });
    if (current) {
      const exists = Array.from(finAsesorInmobiliaria.options).some(
        (opt) => opt.value === current
      );
      if (!exists) {
        finAsesorInmobiliaria.appendChild(createOption(current, current));
      }
      finAsesorInmobiliaria.value = current;
    }
  });
};

const fillFinAsesoramientoForm = (row) => {
  if (!finAsesoramientoForm || !row) return;
  if (finAsesoramientoId) finAsesoramientoId.value = row.id || "";
  if (finAsesoramientoConvert) {
    finAsesoramientoConvert.disabled = !row.id;
  }
  const map = {
    inmobiliaria_asesor: "inmobiliaria_asesor",
    asesor: "asesor",
    fecha: "fecha",
    origen: "origen",
    estado: "estado",
    cliente1_nombre: "cliente1_nombre",
    cliente1_dni: "cliente1_dni",
    cliente1_telefono: "cliente1_telefono",
    cliente1_email: "cliente1_email",
    cliente1_fecha_nacimiento: "cliente1_fecha_nacimiento",
    cliente1_estado_civil: "cliente1_estado_civil",
    cliente1_regimen: "cliente1_regimen",
    cliente1_hijos: "cliente1_hijos",
    cliente1_profesion: "cliente1_profesion",
    cliente1_tipo_contrato: "cliente1_tipo_contrato",
    cliente1_tiempo_contrato: "cliente1_tiempo_contrato",
    cliente1_ingresos: "cliente1_ingresos",
    cliente1_patrimonio: "cliente1_patrimonio",
    cliente1_prestamos: "cliente1_prestamos",
    cliente1_prestamo_activo: "cliente1_prestamo_activo",
    cliente1_prestamo_entidad: "cliente1_prestamo_entidad",
    cliente1_prestamo_resto: "cliente1_prestamo_resto",
    cliente2_nombre: "cliente2_nombre",
    cliente2_dni: "cliente2_dni",
    cliente2_telefono: "cliente2_telefono",
    cliente2_email: "cliente2_email",
    cliente2_fecha_nacimiento: "cliente2_fecha_nacimiento",
    cliente2_estado_civil: "cliente2_estado_civil",
    cliente2_regimen: "cliente2_regimen",
    cliente2_hijos: "cliente2_hijos",
    cliente2_profesion: "cliente2_profesion",
    cliente2_tipo_contrato: "cliente2_tipo_contrato",
    cliente2_tiempo_contrato: "cliente2_tiempo_contrato",
    cliente2_ingresos: "cliente2_ingresos",
    cliente2_patrimonio: "cliente2_patrimonio",
    cliente2_prestamos: "cliente2_prestamos",
    cliente2_prestamo_activo: "cliente2_prestamo_activo",
    cliente2_prestamo_entidad: "cliente2_prestamo_entidad",
    cliente2_prestamo_resto: "cliente2_prestamo_resto",
    ingresos_conjuntos: "ingresos_conjuntos",
    entidades_financieras: "entidades_financieras",
    avalistas: "avalistas",
    aportacion_cv: "aportacion_cv",
    notas: "notas",
    notas_ocr: "notas_ocr",
  };
  const moneyFields = new Set([
    "cliente1_ingresos",
    "cliente2_ingresos",
    "ingresos_conjuntos",
    "aportacion_cv",
  ]);
  Object.entries(map).forEach(([field, key]) => {
    const el = finAsesoramientoForm.querySelector(`[name="${field}"]`);
    if (!el) return;
    if (field.includes("fecha") && row[key]) {
      el.value = normalizeDateInput(row[key]);
      return;
    }
    if (moneyFields.has(field)) {
      const num = toNumber(row[key]);
      el.value = num === null ? (row[key] !== null && row[key] !== undefined ? row[key] : "") : euroFormatter.format(num);
      return;
    }
    el.value = row[key] !== null && row[key] !== undefined ? row[key] : "";
  });
  if (row.id) {
    loadFinChecklist(row.id);
  }
};

const renderFinAsesorKpis = (empresaId) => {
  if (!finAsesorKpis || !empresaId) return;
  api(`/api/fin_kpis?empresa_id=${empresaId}`).then((data) => {
    const kpis = [
      { title: "Asesoramientos", value: numberFormatter.format(data.total || 0), note: "Total" },
      { title: "En estudio", value: numberFormatter.format(data.estados?.en_estudio || 0), note: "Pendientes" },
      { title: "Aprobados", value: numberFormatter.format(data.estados?.aprobado || 0), note: "OK" },
      { title: "Faltantes", value: numberFormatter.format(data.faltantes || 0), note: "Campos obligatorios" },
    ];
    finAsesorKpis.innerHTML = "";
    kpis.forEach((kpi) => {
      const card = document.createElement("div");
      card.className = "card";
      card.innerHTML = `
        <h3>${kpi.title}</h3>
        <div class="muted">${kpi.value}</div>
        <div class="muted">${kpi.note}</div>
      `;
      finAsesorKpis.appendChild(card);
    });
  });
};

const loadFinAlerts = (empresaId) => {
  if (!finAlertsTable || !finAlertsInfo || !empresaId) return;
  api(`/api/fin_alertas?empresa_id=${empresaId}`).then((data) => {
    const rows = data.items || [];
    if (!rows.length) {
      finAlertsTable.innerHTML = "<p class='muted'>Sin alertas activas.</p>";
      finAlertsInfo.textContent = "";
      return;
    }
    const table = document.createElement("table");
    const thead = document.createElement("thead");
    const trHead = document.createElement("tr");
    ["fecha", "cliente1", "estado", "alerta"].forEach((col) => {
      const th = document.createElement("th");
      th.textContent = formatHeader(col);
      trHead.appendChild(th);
    });
    thead.appendChild(trHead);
    table.appendChild(thead);
    const tbody = document.createElement("tbody");
    rows.forEach((row) => {
      const tr = document.createElement("tr");
      const alerta = row.alerta_tipo === "faltantes"
        ? `Faltan: ${(row.missing_fields || []).join(", ")}`
        : "Seguimiento pendiente";
      const values = [
        row.fecha || "-",
        row.cliente1_nombre || "-",
        row.estado || "-",
        alerta,
      ];
      values.forEach((value) => {
        const td = document.createElement("td");
        td.textContent = value === null ? "" : value;
        tr.appendChild(td);
      });
      tbody.appendChild(tr);
    });
    table.appendChild(tbody);
    finAlertsTable.innerHTML = "";
    finAlertsTable.appendChild(table);
    finAlertsInfo.textContent = `Mostrando ${rows.length} alertas.`;
  });
};

const loadFinChecklist = (asesoramientoId) => {
  if (!finChecklistTable || !finChecklistInfo) return;
  if (!asesoramientoId) {
    finChecklistTable.innerHTML = "<p class='muted'>Selecciona un asesoramiento.</p>";
    finChecklistInfo.textContent = "";
    return;
  }
  api(`/api/fin_checklist?asesoramiento_id=${asesoramientoId}`).then((data) => {
    const rows = data.rows || [];
    if (!rows.length) {
      finChecklistTable.innerHTML = "<p class='muted'>Checklist vacío.</p>";
      finChecklistInfo.textContent = "";
      return;
    }
    const table = document.createElement("table");
    const thead = document.createElement("thead");
    const trHead = document.createElement("tr");
    ["tarea", "estado", "responsable", "fecha límite"].forEach((col) => {
      const th = document.createElement("th");
      th.textContent = formatHeader(col);
      trHead.appendChild(th);
    });
    thead.appendChild(trHead);
    table.appendChild(thead);
    const tbody = document.createElement("tbody");
    rows.forEach((row) => {
      const tr = document.createElement("tr");
      const tdTask = document.createElement("td");
      tdTask.textContent = row.tarea || "-";
      tr.appendChild(tdTask);
      const tdEstado = document.createElement("td");
      const select = document.createElement("select");
      ["Pendiente", "En curso", "Hecho"].forEach((opt) => {
        const option = document.createElement("option");
        option.value = opt;
        option.textContent = opt;
        if ((row.estado || "") === opt) option.selected = true;
        select.appendChild(option);
      });
      select.addEventListener("change", () => {
        fetch("/api/fin_checklist_update", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            id: row.id,
            estado: select.value,
            empresa_nombre: FIN_COMPANY,
          }),
        }).catch(() => {});
      });
      tdEstado.appendChild(select);
      tr.appendChild(tdEstado);
      const tdResp = document.createElement("td");
      tdResp.textContent = row.responsable || "-";
      tr.appendChild(tdResp);
      const tdFecha = document.createElement("td");
      tdFecha.textContent = row.fecha_limite || "-";
      tr.appendChild(tdFecha);
      tbody.appendChild(tr);
    });
    table.appendChild(tbody);
    finChecklistTable.innerHTML = "";
    finChecklistTable.appendChild(table);
    finChecklistInfo.textContent = `Mostrando ${rows.length} tareas.`;
  });
};

const loadFinAsesoramientos = (empresaId) => {
  if (!finAsesoramientosTable || !finAsesoramientosInfo || !empresaId) return;
  const q = finAsesoramientosSearch ? finAsesoramientosSearch.value.trim() : "";
  const params = new URLSearchParams({ empresa_id: empresaId, q });
  api(`/api/fin_asesoramientos?${params.toString()}`).then((data) => {
    const rows = data.rows || [];
    state.finAsesoramientosRows = rows;
    renderFinAsesorKpisFromRows(rows);
    renderFinStageBoard(rows);
    if (!rows.length) {
      finAsesoramientosTable.innerHTML = "";
      const wrap = document.createElement("div");
      const msg = document.createElement("p");
      msg.className = "muted";
      msg.textContent = "Sin asesoramientos aún.";
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "secondary";
      btn.textContent = "Crear asesoramiento";
      btn.addEventListener("click", () => {
        try {
          if (finAsesoramientoForm) finAsesoramientoForm.reset();
          if (finAsesoramientoId) finAsesoramientoId.value = "";
          if (finAsesoramientoConvert) finAsesoramientoConvert.disabled = true;
          setHipotecaAltaView("asesoramiento");
          if (finAsesoramientoForm) {
            const dateInput = finAsesoramientoForm.querySelector('[name="fecha"]');
            if (dateInput && !dateInput.value) {
              dateInput.value = new Date().toISOString().slice(0, 10);
            }
            finAsesoramientoForm.scrollIntoView({ behavior: "smooth", block: "start" });
          }
        } catch (_) {}
      });
      wrap.appendChild(msg);
      wrap.appendChild(btn);
      finAsesoramientosTable.appendChild(wrap);
      finAsesoramientosInfo.textContent = "";
      loadFinAlerts(empresaId);
      selectFinAsesoramiento(null);
      return;
    }
    let selectedId = state.finSelectedAsesoramientoId;
    if (!selectedId || !rows.some((row) => row.id === selectedId)) {
      selectedId = rows[0]?.id || "";
    }
    const table = document.createElement("table");
    const thead = document.createElement("thead");
    const trHead = document.createElement("tr");
    [
      "fecha",
      "cliente1",
      "cliente2",
      "telefono",
      "ingresos",
      "estado",
      "faltantes",
      "asesor",
      "acciones",
    ].forEach((col) => {
      const th = document.createElement("th");
      th.textContent = formatHeader(col);
      trHead.appendChild(th);
    });
    thead.appendChild(trHead);
    table.appendChild(thead);
    const tbody = document.createElement("tbody");
    rows.forEach((row) => {
      const tr = document.createElement("tr");
      if (row.id === selectedId) {
        tr.classList.add("is-selected");
      }
      const telefono = row.cliente1_telefono || row.cliente2_telefono || "-";
      const ingresos = row.ingresos_conjuntos || row.cliente1_ingresos || "-";
      const values = [
        row.fecha || "-",
        row.cliente1_nombre || "-",
        row.cliente2_nombre || "-",
        telefono,
        ingresos,
        normalizeFinStage(row.estado),
        row.missing_count ? String(row.missing_count) : "-",
        row.asesor || row.inmobiliaria_asesor || "-",
      ];
      values.forEach((value, idx) => {
        const td = document.createElement("td");
        if (idx === 4) {
          const formatted = formatCell("ingresos_conjuntos", value);
          td.textContent = formatted === null ? "" : formatted;
        } else {
          td.textContent = value === null ? "" : value;
        }
        tr.appendChild(td);
      });
      const tdActions = document.createElement("td");
      tdActions.className = "inline-actions";
      const editBtn = document.createElement("button");
      editBtn.type = "button";
      editBtn.className = "secondary";
      editBtn.textContent = "Abrir";
      editBtn.addEventListener("click", () => {
        selectFinAsesoramiento(row);
        setHipotecaAltaView("asesoramiento");
        if (finAsesoramientoForm) {
          finAsesoramientoForm.scrollIntoView({ behavior: "smooth", block: "start" });
        }
      });
      const nextBtn = document.createElement("button");
      nextBtn.type = "button";
      nextBtn.textContent = "Siguiente";
      nextBtn.addEventListener("click", async () => {
        selectFinAsesoramiento(row);
        try {
          await createRecommendedFinAction();
          setHipotecaAltaView("agenda");
          const empresa = state.empresas.find((e) => e.nombre === FIN_COMPANY);
          if (empresa?.id) loadFinWorkflowActions(empresa.id);
        } catch (error) {
          window.alert(error.message || "No se pudo crear la siguiente tarea.");
        }
      });
      const convertBtn = document.createElement("button");
      convertBtn.type = "button";
      convertBtn.textContent = "Convertir";
      convertBtn.addEventListener("click", () => {
        const ok = window.confirm("¿Convertir este asesoramiento en hipoteca?");
        if (!ok) return;
        fetch("/api/fin_asesoramientos_convert", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            id: row.id,
            empresa_nombre: FIN_COMPANY,
          }),
        })
          .then((res) => res.json())
          .then((resp) => {
            if (resp.error) return;
            loadFinCrm();
          });
      });
      tdActions.appendChild(editBtn);
      tdActions.appendChild(nextBtn);
      tdActions.appendChild(convertBtn);
      tr.appendChild(tdActions);
      tbody.appendChild(tr);
    });
    table.appendChild(tbody);
    finAsesoramientosTable.innerHTML = "";
    finAsesoramientosTable.appendChild(table);
    finAsesoramientosInfo.textContent = `Mostrando ${rows.length} asesoramientos.`;
    loadFinAlerts(empresaId);
    const selectedRow = rows.find((row) => row.id === selectedId) || rows[0];
    selectFinAsesoramiento(selectedRow);
  });
};

const selectFinHipoteca = (row) => {
  state.finSelectedHipoteca = row || null;
  state.finSelectedHipotecaId = row?.id || "";
  renderFinSelectedHipoteca();
  const empresa = state.empresas.find((e) => e.nombre === FIN_COMPANY);
  if (empresa?.id) {
    loadFinHipotecaActions(empresa.id);
  }
};

const renderFinSelectedHipoteca = () => {
  if (!finHipotecaWorkflowStatus || !finSelectedHipotecaLabel) return;
  const row = state.finSelectedHipoteca;
  if (!row) {
    finSelectedHipotecaLabel.textContent = "Selecciona una hipoteca para planificar su operativa.";
    finHipotecaWorkflowStatus.innerHTML = "<p class='muted'>Sin operación seleccionada.</p>";
    if (finHipotecaAccionesTable) {
      finHipotecaAccionesTable.innerHTML = "<p class='muted'>Selecciona una hipoteca para ver sus acciones.</p>";
    }
    if (finHipotecaAccionesInfo) finHipotecaAccionesInfo.textContent = "";
    return;
  }
  const cliente = String(row.cliente || "").trim() || "Cliente";
  const banco = String(row.banco || "").trim() || "-";
  const estado = normalizeFinStage(row.estado || "Estudio");
  const asesor = String(row.asesor || "").trim() || "-";
  finSelectedHipotecaLabel.textContent = `${cliente} · ${estado}`;
  const telefono = String(row.telefono || "").trim();
  const email = String(row.email || "").trim();
  const fechaEncargo = String(row.fecha_encargo || "").trim() || "-";
  const openBtn = `<button type="button" class="secondary" data-fin-open-hipoteca>Abrir ficha</button>`;
  finHipotecaWorkflowStatus.innerHTML = `
    <div class="workspace-mini-kpi"><span>Estado</span><strong>${escapeHtml(estado)}</strong></div>
    <div class="workspace-mini-kpi"><span>Banco</span><strong>${escapeHtml(banco)}</strong></div>
    <div class="workspace-mini-kpi"><span>Fecha encargo</span><strong>${escapeHtml(fechaEncargo)}</strong></div>
    <div class="workspace-mini-kpi"><span>Asesor</span><strong>${escapeHtml(asesor)}</strong></div>
    ${telefono ? `<div class="workspace-mini-kpi"><span>Teléfono</span><strong>${escapeHtml(telefono)}</strong></div>` : ""}
    ${email ? `<div class="workspace-mini-kpi"><span>Email</span><strong>${escapeHtml(email)}</strong></div>` : ""}
    <div class="form-actions" style="margin-top:10px;">
      ${openBtn}
      <label style="margin-left:auto; display:flex; gap:8px; align-items:center;">
        <span class="muted">Cambiar estado</span>
        <select class="inline-input" data-fin-hipoteca-estado></select>
      </label>
    </div>
  `;
  const panel = finHipotecaWorkflowStatus;
  panel.querySelector("[data-fin-open-hipoteca]")?.addEventListener("click", () => openHipotecaFicha(row.id));
  const select = panel.querySelector("[data-fin-hipoteca-estado]");
  if (select) {
    select.innerHTML = "";
    FIN_STAGE_ORDER.forEach((opt) => {
      select.appendChild(createOption(opt, opt));
    });
    select.value = estado;
    select.addEventListener("change", async () => {
      try {
        await fetch("/api/hipotecas_update", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            id: row.id,
            estado: select.value,
            empresa_nombre: FIN_COMPANY,
          }),
        }).then((res) => res.json()).then((data) => {
          if (data?.error) throw new Error(data.error);
        });
        const empresa = state.empresas.find((e) => e.nombre === FIN_COMPANY);
        if (empresa?.id) {
          await loadFinHipotecasEstudio(empresa.id);
        }
      } catch (error) {
        window.alert(error.message || "No se pudo actualizar el estado.");
        select.value = estado;
      }
    });
  }
};

const loadFinHipotecaActions = (empresaId) => {
  if (!finHipotecaAccionesTable || !finHipotecaAccionesInfo || !empresaId) return;
  if (!state.finSelectedHipotecaId) {
    finHipotecaAccionesTable.innerHTML = "<p class='muted'>Selecciona una hipoteca para ver sus acciones.</p>";
    finHipotecaAccionesInfo.textContent = "";
    return;
  }
  const params = new URLSearchParams({
    servicio: "financiaciones",
    empresa_id: empresaId,
    related_id: state.finSelectedHipotecaId,
    related_tipo: "hipoteca",
  });
  api(`/api/acciones?${params.toString()}`).then((data) => {
    const rows = data.rows || [];
    if (!rows.length) {
      finHipotecaAccionesTable.innerHTML = "<p class='muted'>Sin acciones previstas para esta hipoteca.</p>";
      finHipotecaAccionesInfo.textContent = "Crea la primera acción para planificar la operativa.";
      return;
    }
    const table = document.createElement("table");
    const thead = document.createElement("thead");
    const headRow = document.createElement("tr");
    ["fecha", "hora", "tipo", "estado", "resultado", "acciones"].forEach((label) => {
      const th = document.createElement("th");
      th.textContent = formatHeader(label);
      headRow.appendChild(th);
    });
    thead.appendChild(headRow);
    table.appendChild(thead);
    const tbody = document.createElement("tbody");
    rows.forEach((row) => {
      const tr = document.createElement("tr");
      [row.fecha || "-", row.hora || "-", row.tipo || "-", row.estado || "-", row.resultado_cierre || "-"].forEach((value) => {
        const td = document.createElement("td");
        td.textContent = value;
        tr.appendChild(td);
      });
      const actionTd = document.createElement("td");
      actionTd.className = "inline-actions";
      const editBtn = document.createElement("button");
      editBtn.type = "button";
      editBtn.className = "secondary";
      editBtn.textContent = "Editar";
      editBtn.addEventListener("click", () => {
        openActionEditor({
          id: row.id,
          cliente_id: row.cliente_id || "",
          cliente: row.cliente || row.cliente_nombre || "",
          dateKey: row.fecha || "",
          time: row.hora || "",
          tipo: row.tipo || "",
          responsable: row.responsable || "",
          estado: row.estado || "",
          notas: row.notas || "",
          recordatorio_min: row.recordatorio_min || "",
          serviceId: row.servicio || "financiaciones",
          serviceLabel: SERVICE_LABELS[row.servicio] || "Financiaciones",
        });
      });
      actionTd.appendChild(editBtn);
      if (String(row.estado || "").toLowerCase() === "pendiente") {
        const options = getFinActionResults(row.tipo);
        if (options.length) {
          const select = document.createElement("select");
          select.className = "inline-input";
          select.appendChild(createOption("", "Resultado"));
          options.forEach((option) => {
            select.appendChild(createOption(option, option));
          });
          const closeBtn = document.createElement("button");
          closeBtn.type = "button";
          closeBtn.textContent = "Cerrar";
          closeBtn.addEventListener("click", async () => {
            if (!select.value) {
              window.alert("Selecciona un resultado para cerrar la cita o tarea.");
              return;
            }
            try {
              await saveFinActionResolution(row, select.value, "Hecho");
              loadFinHipotecaActions(empresaId);
            } catch (error) {
              window.alert(error.message || "No se pudo cerrar la acción.");
            }
          });
          actionTd.appendChild(select);
          actionTd.appendChild(closeBtn);
        }
      }
      tr.appendChild(actionTd);
      tbody.appendChild(tr);
    });
    table.appendChild(tbody);
    finHipotecaAccionesTable.innerHTML = "";
    finHipotecaAccionesTable.appendChild(table);
    finHipotecaAccionesInfo.textContent = `Mostrando ${rows.length} acciones.`;
  });
};

const loadFinHipotecasEstudio = async (empresaId) => {
  if (!finHipotecasEstudioTable || !finHipotecasEstudioInfo || !empresaId) return;
  const params = new URLSearchParams({ empresa_id: empresaId });
  const data = await api(`/api/fin_hipotecas_estudio?${params.toString()}`).catch(() => ({ rows: [] }));
  const rows = data.rows || [];
  state.finHipotecasEstudioRows = rows;
  if (!rows.length) {
    finHipotecasEstudioTable.innerHTML = "<p class='muted'>Sin hipotecas en estudio.</p>";
    finHipotecasEstudioInfo.textContent = "";
    selectFinHipoteca(null);
    return;
  }
  let selectedId = state.finSelectedHipotecaId;
  if (!selectedId || !rows.some((row) => row.id === selectedId)) {
    selectedId = rows[0]?.id || "";
  }
  const table = document.createElement("table");
  const thead = document.createElement("thead");
  const headRow = document.createElement("tr");
  ["encargo", "cliente", "banco", "estado", "asesor", "acciones"].forEach((label) => {
    const th = document.createElement("th");
    th.textContent = formatHeader(label);
    headRow.appendChild(th);
  });
  thead.appendChild(headRow);
  table.appendChild(thead);
  const tbody = document.createElement("tbody");
  rows.forEach((row) => {
    const tr = document.createElement("tr");
    if (row.id === selectedId) tr.classList.add("is-selected");
    [row.fecha_encargo || "-", row.cliente || "-", row.banco || "-", normalizeFinStage(row.estado || "Estudio"), row.asesor || "-"].forEach((value) => {
      const td = document.createElement("td");
      td.textContent = value === null ? "" : value;
      tr.appendChild(td);
    });
    const tdActions = document.createElement("td");
    tdActions.className = "inline-actions";
    const selectBtn = document.createElement("button");
    selectBtn.type = "button";
    selectBtn.className = "secondary";
    selectBtn.textContent = "Seleccionar";
    selectBtn.addEventListener("click", () => {
      selectFinHipoteca(row);
    });
    const openBtn = document.createElement("button");
    openBtn.type = "button";
    openBtn.className = "ghost";
    openBtn.textContent = "Ficha";
    openBtn.addEventListener("click", () => openHipotecaFicha(row.id));
    tdActions.appendChild(selectBtn);
    tdActions.appendChild(openBtn);
    tr.appendChild(tdActions);
    tr.addEventListener("click", () => selectFinHipoteca(row));
    tbody.appendChild(tr);
  });
  table.appendChild(tbody);
  finHipotecasEstudioTable.innerHTML = "";
  finHipotecasEstudioTable.appendChild(table);
  finHipotecasEstudioInfo.textContent = `Mostrando ${rows.length} hipotecas en estudio.`;
  const selectedRow = rows.find((row) => row.id === selectedId) || rows[0];
  selectFinHipoteca(selectedRow);
};

const bindMoneyInputs = (formEl) => {
  if (!formEl) return;
  const moneyInputs = formEl.querySelectorAll("input[data-money='1']");
  moneyInputs.forEach((input) => {
    if (input.dataset.boundMoney === "1") return;
    input.dataset.boundMoney = "1";
    input.addEventListener("focus", () => {
      const num = toNumber(input.value);
      if (num !== null) input.value = String(num);
    });
    input.addEventListener("blur", () => {
      const num = toNumber(input.value);
      if (num !== null) input.value = euroFormatter.format(num);
    });
  });
};

const bindIngresosConjuntos = (formEl) => {
  if (!formEl) return;
  const ingreso1 = formEl.querySelector('[name="cliente1_ingresos"]');
  const ingreso2 = formEl.querySelector('[name="cliente2_ingresos"]');
  const conjunto = formEl.querySelector('[name="ingresos_conjuntos"]');
  if (!ingreso1 || !ingreso2 || !conjunto) return;
  if (conjunto.dataset.boundIngresos === "1") return;
  conjunto.dataset.boundIngresos = "1";
  const update = () => {
    const n1 = toNumber(ingreso1.value);
    const n2 = toNumber(ingreso2.value);
    if (n1 === null && n2 === null) return;
    const sum = (n1 || 0) + (n2 || 0);
    if (!conjunto.value || conjunto.dataset.auto === "1") {
      conjunto.value = euroFormatter.format(sum);
      conjunto.dataset.auto = "1";
    }
  };
  ingreso1.addEventListener("blur", update);
  ingreso2.addEventListener("blur", update);
  conjunto.addEventListener("input", () => {
    conjunto.dataset.auto = "0";
  });
  update();
};

const bindLoanToggles = (formEl) => {
  if (!formEl) return;
  const toggles = formEl.querySelectorAll("[data-loan-toggle]");
  toggles.forEach((toggle) => {
    if (toggle.dataset.boundLoan === "1") return;
    toggle.dataset.boundLoan = "1";
    const key = toggle.dataset.loanToggle;
    const update = () => {
      const show = String(toggle.value || "").toLowerCase() === "si";
      formEl
        .querySelectorAll(`[data-loan-field="${key}"]`)
        .forEach((el) => {
          el.classList.toggle("hidden", !show);
        });
    };
    toggle.addEventListener("change", update);
    update();
  });
};

const extractLoanInfo = (text) => {
  if (!text) return { active: "", entidad: "", resto: "" };
  const cleaned = String(text).replace(/\s+/g, " ");
  const entidadList = Array.from(document.querySelectorAll("#bankList option")).map(
    (opt) => opt.value
  );
  let entidad = "";
  for (const name of entidadList) {
    if (name && cleaned.toLowerCase().includes(name.toLowerCase())) {
      entidad = name;
      break;
    }
  }
  const amounts = cleaned.match(/[0-9]{1,3}(?:[\\.,][0-9]{3})*(?:[\\.,][0-9]{2})?/g) || [];
  const resto = amounts.length ? amounts[amounts.length - 1] : "";
  return { active: "Si", entidad, resto };
};

const applyPrestamoFromOcr = (fields, prefix) => {
  const raw = fields[`${prefix}_prestamos`];
  if (!raw) return;
  const info = extractLoanInfo(raw);
  const form = finAsesoramientoForm;
  if (!form) return;
  const setValue = (name, value) => {
    const el = form.querySelector(`[name="${name}"]`);
    if (el && value !== undefined) el.value = value;
  };
  setValue(`${prefix}_prestamo_activo`, info.active);
  setValue(`${prefix}_prestamo_entidad`, info.entidad);
  setValue(`${prefix}_prestamo_resto`, info.resto);
};

const loadSegurosOportunidades = (empresaId) => {
  if (!segurosCrmOportunidades) {
    return;
  }
  if (!empresaId) {
    segurosCrmOportunidades.innerHTML = "<p class='muted'>Sin empresa.</p>";
    return;
  }
  const canGestoria = userCanAccessService("gestoria");
  const segurosParams = new URLSearchParams({ tabla: "seguros", empresa_id: empresaId });
  const gestoriaParams = new URLSearchParams({ tabla: "gestoria", empresa_id: empresaId });
  Promise.all([
    api(`/api/tabla?${segurosParams.toString()}`).catch(() => null),
    canGestoria ? api(`/api/tabla?${gestoriaParams.toString()}`).catch(() => null) : Promise.resolve(null),
  ]).then(([segurosData, gestoriaData]) => {
    if (!segurosData || !Array.isArray(segurosData.columns)) {
      segurosCrmOportunidades.innerHTML = "<p class='muted'>No se pudieron cargar oportunidades.</p>";
      return;
    }
    if (!gestoriaData || !Array.isArray(gestoriaData.columns)) {
      // Usuario solo seguros: no debe disparar error ni promesas rechazadas por falta de permisos.
      segurosCrmOportunidades.innerHTML = "<p class='muted'>Oportunidades disponibles al tener acceso a Gestoría.</p>";
      return;
    }
    const tomadorIndex = segurosData.columns.indexOf("tomador");
    const clienteIndex = gestoriaData.columns.indexOf("cliente");
    const tomadores = new Set(
      segurosData.rows.map((row) => (row[tomadorIndex] || "").trim()).filter(Boolean)
    );
    const candidatos = gestoriaData.rows
      .map((row) => (row[clienteIndex] || "").trim())
      .filter(Boolean);
    const oportunidades = candidatos.filter((name) => !tomadores.has(name));
    if (!oportunidades.length) {
      segurosCrmOportunidades.innerHTML = "<p class='muted'>Sin oportunidades pendientes.</p>";
      return;
    }
    const list = document.createElement("div");
    list.className = "inline-list";
    oportunidades.slice(0, 50).forEach((name) => {
      const row = document.createElement("div");
      row.className = "inline-row";
      row.innerHTML = `<div class="muted">${name}</div>`;
      list.appendChild(row);
    });
    segurosCrmOportunidades.innerHTML = "";
    segurosCrmOportunidades.appendChild(list);
  });
};

const FIN_STAGE_ORDER = [
  "Lead",
  "Asesoramiento",
  "Documentación",
  "Estudio",
  "Bancos",
  "Tasación",
  "FEIN / Acta",
  "Firma",
  "Convertido",
  "Descartada",
];

const FIN_ACTION_RESULT_OPTIONS = {
  "Primera llamada": ["Cita concertada", "No interesado", "Sin respuesta"],
  "Reunión de asesoramiento": ["Realizada", "Pendiente documentación", "No viable"],
  "Solicitud documentación": ["Completa", "Parcial", "No entregada"],
  "Estudio financiero": ["Viable", "Pendiente documentación", "No viable"],
  "Presentación bancaria": ["Presentada", "Pendiente completar", "No presentada"],
  "Seguimiento bancario": ["Tasación solicitada", "Aprobada", "Denegada", "Pendiente"],
  "Tasación": ["Tasación OK", "Incidencia", "Cancelada"],
  "FEIN / Acta": ["Firmable", "Pendiente", "Caducada"],
  "Firma hipoteca": ["Firmada", "Cancelada", "Pospuesta"],
};

const FIN_STAGE_ALIASES = new Map([
  ["en estudio", "Estudio"],
  ["estudio", "Estudio"],
  ["aprobado", "FEIN / Acta"],
  ["pendiente documentacion", "Documentación"],
  ["documentacion", "Documentación"],
  ["presentada a banco", "Bancos"],
  ["bancos", "Bancos"],
  ["tasacion", "Tasación"],
  ["fein", "FEIN / Acta"],
  ["fein / acta", "FEIN / Acta"],
  ["firma", "Firma"],
  ["convertido", "Convertido"],
  ["firmada", "Convertido"],
  ["descartado", "Descartada"],
  ["rechazado", "Descartada"],
  ["asesoramiento", "Asesoramiento"],
  ["lead", "Lead"],
]);

const normalizeFinStage = (value) => {
  const raw = String(value || "").trim();
  if (!raw) return "Lead";
  const normalized = normalizeSimple(raw);
  return FIN_STAGE_ALIASES.get(normalized) || raw;
};

const getFinActionResults = (actionType) => FIN_ACTION_RESULT_OPTIONS[String(actionType || "").trim()] || [];

const getFinRecommendedAction = (row) => {
  const stage = normalizeFinStage(row?.estado);
  const missing = Number(row?.missing_count || 0);
  if (missing > 0 && stage !== "Convertido" && stage !== "Descartada") {
    return {
      type: "Completar datos asesoramiento",
      hint: `Completar ${missing} campos obligatorios antes de seguir`,
    };
  }
  switch (stage) {
    case "Lead":
      return { type: "Primera llamada", hint: "Confirmar interés y concertar la primera cita" };
    case "Asesoramiento":
      return { type: "Reunión de asesoramiento", hint: "Recoger perfil económico y enfocar la operación" };
    case "Documentación":
      return { type: "Solicitud documentación", hint: "Pedir o rematar la documentación pendiente" };
    case "Estudio":
      return { type: "Estudio financiero", hint: "Validar viabilidad antes de enviar a banco" };
    case "Bancos":
      return { type: "Seguimiento bancario", hint: "Revisar respuesta de entidades y siguientes hitos" };
    case "Tasación":
      return { type: "Tasación", hint: "Controlar tasación, incidencias y resultado" };
    case "FEIN / Acta":
      return { type: "FEIN / Acta", hint: "Controlar FEIN, acta y estado pre-firma" };
    case "Firma":
      return { type: "Firma hipoteca", hint: "Preparar y cerrar la firma de escritura" };
    default:
      return null;
  }
};

const renderFinStageBoard = (rows = []) => {
  if (!hipotecaWorkflowStageBoard) return;
  const counts = new Map(FIN_STAGE_ORDER.map((stage) => [stage, 0]));
  rows.forEach((row) => {
    const stage = normalizeFinStage(row?.estado);
    counts.set(stage, (counts.get(stage) || 0) + 1);
  });
  hipotecaWorkflowStageBoard.innerHTML = "";
  FIN_STAGE_ORDER.forEach((stage) => {
    const card = document.createElement("button");
    card.type = "button";
    card.className = "fin-stage-card";
    if (state.finSelectedAsesoramiento && normalizeFinStage(state.finSelectedAsesoramiento.estado) === stage) {
      card.classList.add("active");
    }
    card.innerHTML = `
      <strong>${stage}</strong>
      <span>${numberFormatter.format(counts.get(stage) || 0)} expedientes</span>
    `;
    card.addEventListener("click", () => {
      if (finAsesoramientosSearch) {
        finAsesoramientosSearch.value = stage === "Lead" ? "" : stage;
        loadFinCrm();
      }
    });
    hipotecaWorkflowStageBoard.appendChild(card);
  });
};

const renderFinAsesorKpisFromRows = (rows = []) => {
  if (!finAsesorKpis) return;
  const total = rows.length;
  const docs = rows.filter((row) => normalizeFinStage(row?.estado) === "Documentación").length;
  const bancos = rows.filter((row) => ["Bancos", "Tasación", "FEIN / Acta", "Firma"].includes(normalizeFinStage(row?.estado))).length;
  const convertidos = rows.filter((row) => normalizeFinStage(row?.estado) === "Convertido").length;
  const faltantes = rows.filter((row) => Number(row?.missing_count || 0) > 0).length;
  const kpis = [
    { title: "Expedientes", value: numberFormatter.format(total), note: "Cartera total" },
    { title: "Documentación", value: numberFormatter.format(docs), note: "Pendiente de completar" },
    { title: "Bancos y firma", value: numberFormatter.format(bancos), note: "Tramitación avanzada" },
    { title: "Firmadas", value: numberFormatter.format(convertidos), note: "Convertidas en hipoteca" },
    { title: "Bloqueos", value: numberFormatter.format(faltantes), note: "Con campos obligatorios faltantes" },
  ];
  finAsesorKpis.innerHTML = "";
  kpis.forEach((item) => {
    const card = document.createElement("div");
    card.className = "card";
    card.innerHTML = `
      <h3>${item.title}</h3>
      <div class="muted">${item.value}</div>
      <div class="muted">${item.note}</div>
    `;
    finAsesorKpis.appendChild(card);
  });
};

const updateFinSelectedSummary = () => {
  if (!hipotecaWorkflowStatus || !finSelectedAsesoramientoLabel) return;
  const row = state.finSelectedAsesoramiento;
  if (!row) {
    finSelectedAsesoramientoLabel.textContent = "Selecciona un asesoramiento para trabajar su seguimiento.";
    hipotecaWorkflowStatus.innerHTML = "<p class='muted'>Sin expediente seleccionado.</p>";
    return;
  }
  const cliente2 = row.cliente2_nombre ? ` / ${row.cliente2_nombre}` : "";
  finSelectedAsesoramientoLabel.textContent = `${row.cliente1_nombre || "Cliente"}${cliente2} · ${normalizeFinStage(row.estado)}`;
  const missing = Array.isArray(row.missing_fields) ? row.missing_fields : [];
  const next = getFinRecommendedAction(row);
  hipotecaWorkflowStatus.innerHTML = `
    <div class="workspace-mini-kpi"><span>Estado</span><strong>${normalizeFinStage(row.estado)}</strong></div>
    <div class="workspace-mini-kpi"><span>Ingresos conjuntos</span><strong>${formatCell("ingresos_conjuntos", row.ingresos_conjuntos || row.cliente1_ingresos || 0) || "-"}</strong></div>
    <div class="workspace-mini-kpi"><span>Aportación</span><strong>${formatCell("aportacion_cv", row.aportacion_cv || 0) || "-"}</strong></div>
    <div class="workspace-mini-kpi"><span>Próximo paso</span><strong>${next?.type || "Sin sugerencia"}</strong></div>
    <div class="workspace-mini-kpi"><span>Bloqueos</span><strong>${missing.length ? missing.join(", ") : "Sin bloqueos"}</strong></div>
  `;
};

const syncFinAgendaContext = () => {
  const row = state.finSelectedAsesoramiento;
  if (finAgendaAsesoramientoId) {
    finAgendaAsesoramientoId.value = row?.id || "";
  }
  if (finAgendaClienteInput && row) {
    finAgendaClienteInput.value = row.cliente1_nombre || "";
  }
  if (finAgendaClienteId && row) {
    finAgendaClienteId.value = row.cliente1_id || "";
  }
};

const selectFinAsesoramiento = (row) => {
  state.finSelectedAsesoramiento = row || null;
  state.finSelectedAsesoramientoId = row?.id || "";
  if (row) {
    fillFinAsesoramientoForm(row);
  } else {
    if (finAsesoramientoForm) finAsesoramientoForm.reset();
    if (finAsesoramientoId) finAsesoramientoId.value = "";
    loadFinChecklist("");
  }
  updateFinSelectedSummary();
  syncFinAgendaContext();
  const empresa = state.empresas.find((item) => item.nombre === FIN_COMPANY);
  if (empresa?.id && (state.hipotecaAltaView || "dashboard") === "agenda") {
    loadFinWorkflowActions(empresa.id);
  }
  renderFinStageBoard(state.finAsesoramientosRows || []);
};

const saveFinActionResolution = async (row, result, estado = "Hecho") => {
  if (!row?.id) return;
  const payload = {
    id: row.id,
    empresa_nombre: FIN_COMPANY,
    estado,
    resultado_cierre: result || "",
  };
  const res = await fetch("/api/acciones_update", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  const data = await res.json();
  if (data.error) throw new Error(data.error);
};

const loadFinWorkflowActions = (empresaId) => {
  if (!finAgendaTable || !finAgendaInfo || !empresaId) return;
  if (!state.finSelectedAsesoramientoId) {
    finAgendaTable.innerHTML = "<p class='muted'>Selecciona un expediente en Workflow para ver su agenda.</p>";
    finAgendaInfo.textContent = "";
    return;
  }
  const params = new URLSearchParams({ servicio: "financiaciones", empresa_id: empresaId });
  if (state.finSelectedAsesoramientoId) {
    params.set("asesoramiento_id", state.finSelectedAsesoramientoId);
  }
  api(`/api/acciones?${params.toString()}`).then((data) => {
    const rows = data.rows || [];
    state.finAgendaRows = rows;
    if (!rows.length) {
      finAgendaTable.innerHTML = "<p class='muted'>Sin tareas ni citas para este expediente.</p>";
      finAgendaInfo.textContent = state.finSelectedAsesoramientoId ? "Crea el siguiente paso desde el expediente." : "";
      return;
    }
    const table = document.createElement("table");
    const thead = document.createElement("thead");
    const headRow = document.createElement("tr");
    ["fecha", "hora", "tipo", "cliente", "estado", "resultado", "acciones"].forEach((label) => {
      const th = document.createElement("th");
      th.textContent = formatHeader(label);
      headRow.appendChild(th);
    });
    thead.appendChild(headRow);
    table.appendChild(thead);
    const tbody = document.createElement("tbody");
    rows.forEach((row) => {
      const tr = document.createElement("tr");
      [row.fecha || "-", row.hora || "-", row.tipo || "-", row.cliente || "-", row.estado || "-", row.resultado_cierre || "-"].forEach((value) => {
        const td = document.createElement("td");
        td.textContent = value;
        tr.appendChild(td);
      });
      const actionTd = document.createElement("td");
      actionTd.className = "inline-actions";
      if (String(row.estado || "").toLowerCase() === "pendiente") {
        const options = getFinActionResults(row.tipo);
        if (options.length) {
          const select = document.createElement("select");
          select.className = "inline-input";
          select.appendChild(createOption("", "Resultado"));
          options.forEach((option) => {
            select.appendChild(createOption(option, option));
          });
          const closeBtn = document.createElement("button");
          closeBtn.type = "button";
          closeBtn.textContent = "Cerrar";
          closeBtn.addEventListener("click", async () => {
            if (!select.value) {
              window.alert("Selecciona un resultado para cerrar la cita o tarea.");
              return;
            }
            try {
              await saveFinActionResolution(row, select.value, "Hecho");
              loadFinCrm();
            } catch (error) {
              window.alert(error.message || "No se pudo cerrar la acción.");
            }
          });
          actionTd.appendChild(select);
          actionTd.appendChild(closeBtn);
        } else {
          const doneBtn = document.createElement("button");
          doneBtn.type = "button";
          doneBtn.textContent = "Hecho";
          doneBtn.addEventListener("click", async () => {
            try {
              await saveFinActionResolution(row, "", "Hecho");
              loadFinCrm();
            } catch (error) {
              window.alert(error.message || "No se pudo cerrar la tarea.");
            }
          });
          actionTd.appendChild(doneBtn);
        }
      } else {
        actionTd.textContent = row.resultado_cierre || row.estado || "-";
      }
      tr.appendChild(actionTd);
      tbody.appendChild(tr);
    });
    table.appendChild(tbody);
    finAgendaTable.innerHTML = "";
    finAgendaTable.appendChild(table);
    finAgendaInfo.textContent = `Mostrando ${rows.length} tareas/citas${state.finSelectedAsesoramientoId ? " del expediente seleccionado" : ""}.`;
  });
};

const createRecommendedFinAction = async () => {
  const empresa = state.empresas.find((item) => item.nombre === FIN_COMPANY);
  const row = state.finSelectedAsesoramiento;
  const next = getFinRecommendedAction(row);
  if (!empresa?.id || !row || !next) return;
  const payload = {
    empresa_nombre: FIN_COMPANY,
    servicio: "financiaciones",
    asesoramiento_id: row.id,
    cliente_id: row.cliente1_id || "",
    cliente_nombre: row.cliente1_nombre || "",
    fecha: new Date().toISOString().slice(0, 10),
    tipo: next.type,
    estado: "Pendiente",
    responsable: row.asesor || "",
    notas: next.hint,
  };
  const res = await fetch("/api/acciones", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  const data = await res.json();
  if (data.error) throw new Error(data.error);
};

const loadAcciones = (servicio, empresaId, container, infoEl) => {
  if (!container || !infoEl) {
    return;
  }
  container.dataset.service = servicio || "";
  const params = new URLSearchParams({ servicio, empresa_id: empresaId });
  api(`/api/acciones?${params.toString()}`).then((data) => {
    const rows = data.rows || [];
    const events = buildAgendaEvents(rows, servicio, SERVICE_LABELS[servicio] || servicio);
    renderAgendaCalendar(container, events, `Agenda · ${SERVICE_LABELS[servicio] || servicio}`);
    infoEl.textContent = `Mostrando ${rows.length} acciones.`;
  });
};

const loadClienteProfesional = (clienteId) => {
  if (!clienteProfesionalList) return;
  api(`/api/cliente_profesional?cliente_id=${clienteId}`).then((data) => {
    const rows = data.rows || [];
    if (!rows.length) {
      clienteProfesionalList.innerHTML = "<p class='muted'>Sin datos profesionales.</p>";
      return;
    }
    const table = document.createElement("table");
    const thead = document.createElement("thead");
    const trHead = document.createElement("tr");
    ["CNAE", "IAE", "Actividad", "IBAN", "Principal", "Accion"].forEach((col) => {
      const th = document.createElement("th");
      th.textContent = col;
      trHead.appendChild(th);
    });
    thead.appendChild(trHead);
    table.appendChild(thead);
    const tbody = document.createElement("tbody");
    rows.forEach((row) => {
      const tr = document.createElement("tr");
      ["cnae", "iae", "actividad", "iban"].forEach((key) => {
        const td = document.createElement("td");
        const input = document.createElement("input");
        input.value = row[key] || "";
        input.classList.add("inline-input");
        input.addEventListener("change", () => {
          saveClienteProfesionalField(row.id, key, input.value);
        });
        td.appendChild(input);
        tr.appendChild(td);
      });
      const principalTd = document.createElement("td");
      const principalSelect = document.createElement("select");
      principalSelect.classList.add("inline-input");
      principalSelect.appendChild(createOption("0", "No"));
      principalSelect.appendChild(createOption("1", "Sí"));
      principalSelect.value = String(row.principal || 0);
      principalSelect.addEventListener("change", () => {
        saveClienteProfesionalField(row.id, "principal", principalSelect.value);
      });
      principalTd.appendChild(principalSelect);
      tr.appendChild(principalTd);
      const actionTd = document.createElement("td");
      const del = document.createElement("button");
      del.type = "button";
      del.textContent = "Eliminar";
      del.addEventListener("click", () => {
        deleteClienteProfesional(row.id, clienteId);
      });
      actionTd.appendChild(del);
      tr.appendChild(actionTd);
      tbody.appendChild(tr);
    });
    table.appendChild(tbody);
    clienteProfesionalList.innerHTML = "";
    clienteProfesionalList.appendChild(table);
  });
};

