const fillGestoriaImportReviewForm = (row) => {
  if (!gestoriaImportReviewForm) return;
  const doc = row || null;
  const setValue = (name, value) => {
    const input = gestoriaImportReviewForm.querySelector(`[name="${name}"]`);
    if (input) input.value = value ?? "";
  };
  if (!doc) {
    gestoriaImportReviewForm.reset();
    if (gestoriaImportReviewStatus) gestoriaImportReviewStatus.textContent = "Selecciona un documento.";
    return;
  }
  setValue("estado_revision", doc.estado_revision || "REVISAR");
  setValue("tipo_detectado", doc.tipo_detectado || "compra");
  setValue("categoria_detectada", doc.categoria_detectada || "");
  setValue("cuenta_sugerida", doc.cuenta_sugerida || "");
  setValue("tercero_detectado", doc.tercero_detectado || doc.tercero_nombre || "");
  setValue("nif_detectado", doc.nif_detectado || "");
  setValue("numero_detectado", doc.numero_detectado || "");
  setValue("fecha_detectada", doc.fecha_detectada || "");
  setValue("base_detectada", doc.base_detectada ?? "");
  setValue("cuota_iva_detectada", doc.cuota_iva_detectada ?? "");
  setValue("total_detectado", doc.total_detectado ?? "");
  setValue("motivos_revision", doc.motivos_revision || "");
  if (gestoriaImportReviewStatus) {
    gestoriaImportReviewStatus.textContent = `Documento seleccionado: ${doc.archivo_nombre || doc.id}`;
  }
};

const renderGestoriaImportDocsTable = (rows = []) => {
  if (!gestoriaImportDocsTable) return;
  if (!rows.length) {
    gestoriaImportDocsTable.innerHTML = "<p class='muted'>Sin documentos en el lote seleccionado.</p>";
    if (gestoriaImportDocsInfo) gestoriaImportDocsInfo.textContent = "";
    state.gestoriaImportCurrentDocs = [];
    state.gestoriaImportSelectedDocumentoId = "";
    fillGestoriaImportReviewForm(null);
    return;
  }
  state.gestoriaImportCurrentDocs = rows;
  if (!rows.some((row) => row.id === state.gestoriaImportSelectedDocumentoId)) {
    state.gestoriaImportSelectedDocumentoId = rows[0]?.id || "";
  }
  const table = document.createElement("table");
  const thead = document.createElement("thead");
  const trHead = document.createElement("tr");
  ["Fecha", "Archivo", "Estado", "Categoría", "Tercero", "Número", "Total", "Factura", ""].forEach((col) => {
    const th = document.createElement("th");
    th.textContent = col;
    trHead.appendChild(th);
  });
  thead.appendChild(trHead);
  table.appendChild(thead);
  const tbody = document.createElement("tbody");
  rows.forEach((row) => {
    const tr = document.createElement("tr");
    if (row.id === state.gestoriaImportSelectedDocumentoId) tr.classList.add("active");
    const values = [
      row.fecha_detectada || "-",
      row.archivo_nombre || "-",
      row.estado_revision || "-",
      row.categoria_detectada || "-",
      row.tercero_detectado || row.tercero_nombre || "-",
      row.numero_detectado || row.factura_numero || "-",
      row.total_detectado ? euroFormatter.format(parseMoneyValue(row.total_detectado)) : "-",
      row.factura_numero || row.factura_id || "-",
    ];
    values.forEach((value) => {
      const td = document.createElement("td");
      td.textContent = value;
      tr.appendChild(td);
    });
    const actionTd = document.createElement("td");
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = row.id === state.gestoriaImportSelectedDocumentoId ? "secondary" : "ghost";
    btn.textContent = "Revisar";
    btn.addEventListener("click", () => {
      state.gestoriaImportSelectedDocumentoId = row.id;
      fillGestoriaImportReviewForm(row);
      renderGestoriaImportDocsTable(state.gestoriaImportCurrentDocs || []);
    });
    actionTd.appendChild(btn);
    tr.appendChild(actionTd);
    tbody.appendChild(tr);
  });
  table.appendChild(tbody);
  gestoriaImportDocsTable.innerHTML = "";
  gestoriaImportDocsTable.appendChild(table);
  fillGestoriaImportReviewForm(getGestoriaImportSelectedDoc());
  if (gestoriaImportDocsInfo) {
    const summary = rows.reduce(
      (acc, row) => {
        const key = String(row.estado_revision || "").toUpperCase();
        acc[key] = (acc[key] || 0) + 1;
        return acc;
      },
      {}
    );
    gestoriaImportDocsInfo.textContent = `Documentos: ${rows.length} · OK ${summary.OK || 0} · REVISAR ${summary.REVISAR || 0} · DUPLICADO ${summary.DUPLICADO || 0} · ERROR ${summary.ERROR || 0}`;
  }
};

const loadGestoriaImportLoteDocuments = (loteId) => {
  if (!loteId) {
    renderGestoriaImportDocsTable([]);
    return Promise.resolve();
  }
  state.gestoriaImportSelectedLoteId = loteId;
  const qs = new URLSearchParams({ lote_id: loteId });
  if (state.gestoriaImportEstadoFilter) qs.set("estado", state.gestoriaImportEstadoFilter);
  return api(`/api/gestoria_import_documentos?${qs.toString()}`)
    .then((data) => {
      renderGestoriaImportDocsTable(data.rows || []);
    })
    .catch(() => {
      if (gestoriaImportDocsTable) {
        gestoriaImportDocsTable.innerHTML = "<p class='muted'>No se pudieron cargar los documentos del lote.</p>";
      }
      if (gestoriaImportDocsInfo) gestoriaImportDocsInfo.textContent = "";
    });
};

const renderGestoriaImportLotesTable = (clienteId, rows = []) => {
  if (!gestoriaImportLotesTable) return;
  state.gestoriaImportCurrentLotes = rows;
  if (!rows.length) {
    gestoriaImportLotesTable.innerHTML = "<p class='muted'>Sin lotes de importación registrados.</p>";
    if (gestoriaImportLotesInfo) gestoriaImportLotesInfo.textContent = "";
    fillGestoriaImportSelectedLoteMeta(null);
    renderGestoriaImportDocsTable([]);
    return;
  }
  const exactRows = rows.filter((row) => String(row.cliente_id || "") === String(clienteId || ""));
  const unassignedRows = rows.filter((row) => !String(row.cliente_id || "").trim());
  const visibleRows = (exactRows.length ? exactRows : []).concat(
    unassignedRows.filter((row) => !exactRows.some((item) => item.id === row.id))
  ).slice(0, 12);
  const selectedId =
    visibleRows.some((row) => row.id === state.gestoriaImportSelectedLoteId)
      ? state.gestoriaImportSelectedLoteId
      : (visibleRows[0] && visibleRows[0].id) || "";
  const table = document.createElement("table");
  const thead = document.createElement("thead");
  const trHead = document.createElement("tr");
  ["Fecha", "Origen", "Estado", "Cliente", "Docs", "OK", "Revisar", "Error", ""].forEach((col) => {
    const th = document.createElement("th");
    th.textContent = col;
    trHead.appendChild(th);
  });
  thead.appendChild(trHead);
  table.appendChild(thead);
  const tbody = document.createElement("tbody");
  visibleRows.forEach((row) => {
    const tr = document.createElement("tr");
    if (row.id === selectedId) tr.classList.add("active");
    [
      row.created_at || "-",
      row.origen || "-",
      row.estado || "-",
      row.cliente || (row.cliente_id ? row.cliente_id : "Sin asignar"),
      row.total_documentos || 0,
      row.total_ok || 0,
      row.total_revisar || 0,
      row.total_error || 0,
    ].forEach((value) => {
      const td = document.createElement("td");
      td.textContent = String(value);
      tr.appendChild(td);
    });
    const actionTd = document.createElement("td");
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = row.id === selectedId ? "secondary" : "ghost";
    btn.textContent = "Ver";
    btn.addEventListener("click", () => {
      loadGestoriaImportLoteDocuments(row.id);
      renderGestoriaImportLotesTable(clienteId, rows);
    });
    actionTd.appendChild(btn);
    tr.appendChild(actionTd);
    tbody.appendChild(tr);
  });
  table.appendChild(tbody);
  gestoriaImportLotesTable.innerHTML = "";
  gestoriaImportLotesTable.appendChild(table);
  fillGestoriaImportSelectedLoteMeta(visibleRows.find((row) => row.id === selectedId) || null);
  if (gestoriaImportLotesInfo) {
    gestoriaImportLotesInfo.textContent = `Mostrando ${visibleRows.length} lotes${exactRows.length ? " del cliente" : " recientes de la empresa"}${unassignedRows.length ? " · incluye lotes sin cliente asignado" : ""}.`;
  }
  loadGestoriaImportLoteDocuments(selectedId);
};

const loadGestoriaClienteImportador = (clienteId) => {
  if (!gestoriaImportLotesTable) return;
  const empresa = state.empresas.find((item) => item.nombre === FINCAS_COMPANY);
  if (!clienteId || !empresa?.id) {
    gestoriaImportLotesTable.innerHTML = "<p class='muted'>Sin cliente o empresa seleccionada.</p>";
    if (gestoriaImportLotesInfo) gestoriaImportLotesInfo.textContent = "";
    fillGestoriaImportSelectedLoteMeta(null);
    renderGestoriaImportDocsTable([]);
    return;
  }
  api(`/api/gestoria_import_lotes?empresa_id=${encodeURIComponent(empresa.id)}`)
    .then((data) => {
      renderGestoriaImportLotesTable(clienteId, data.rows || []);
    })
    .catch(() => {
      gestoriaImportLotesTable.innerHTML = "<p class='muted'>No se pudo cargar la cola del importador.</p>";
      if (gestoriaImportLotesInfo) gestoriaImportLotesInfo.textContent = "";
      renderGestoriaImportDocsTable([]);
    });
};

const setGestoriaClienteLibroTab = (tabName = "diario") => {
  if (!gestoriaClienteLibrosTabs) return;
  const target = tabName || "diario";
  state.gestoriaClienteLibroTab = target;
  gestoriaClienteLibrosTabs.querySelectorAll(".tab").forEach((btn) => {
    btn.classList.toggle("active", btn.dataset.libroTab === target);
  });
  if (gestoriaClienteLibroDiarioPanel) gestoriaClienteLibroDiarioPanel.classList.toggle("hidden", target !== "diario");
  if (gestoriaClienteLibroMayorPanel) gestoriaClienteLibroMayorPanel.classList.toggle("hidden", target !== "mayor");
  if (gestoriaClienteLibroIvaPanel) gestoriaClienteLibroIvaPanel.classList.toggle("hidden", target !== "iva");
  if (gestoriaClienteLibroExcelPanel) gestoriaClienteLibroExcelPanel.classList.toggle("hidden", target !== "excel");
};

const renderSimpleTable = (container, columns, rows) => {
  if (!container) return;
  if (!rows.length) {
    container.innerHTML = "<p class='muted'>Sin datos.</p>";
    return;
  }
  const table = document.createElement("table");
  const thead = document.createElement("thead");
  const trHead = document.createElement("tr");
  columns.forEach((col) => {
    const th = document.createElement("th");
    th.textContent = col;
    trHead.appendChild(th);
  });
  thead.appendChild(trHead);
  table.appendChild(thead);
  const tbody = document.createElement("tbody");
  rows.forEach((row) => {
    const tr = document.createElement("tr");
    row.forEach((value) => {
      const td = document.createElement("td");
      td.textContent = value;
      tr.appendChild(td);
    });
    tbody.appendChild(tr);
  });
  table.appendChild(tbody);
  container.innerHTML = "";
  container.appendChild(table);
};

const toCsv = (rows) =>
  rows
    .map((row) =>
      row
        .map((cell) => {
          const text = String(cell ?? "");
          return /[",;\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
        })
        .join(";")
    )
    .join("\n");

const downloadCsvFile = (filename, content) => {
  const blob = new Blob([content], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
};

const buildPlantillaConversorRows = (diario = []) => {
  const grouped = new Map();
  diario.forEach((line) => {
    const key = String(line.asiento_id || "").trim() || `${line.fecha || ""}-${line.referencia || ""}`;
    if (!grouped.has(key)) grouped.set(key, []);
    grouped.get(key).push(line);
  });
  const rows = [];
  grouped.forEach((lines) => {
    if (!lines.length) return;
    const sample = lines[0];
    let base = 0;
    let ivaPct = 0;
    let ivaImporte = 0;
    let subcuentaTercero = "";
    let subcuentaGyI = "";
    lines.forEach((line) => {
      const cuenta = String(line.cuenta || "").trim();
      const debe = parseMoneyValue(line.debe);
      const haber = parseMoneyValue(line.haber);
      const impTipo = normalizeSimple(line.impuesto_tipo || "");
      if (!subcuentaTercero && cuenta.startsWith("4")) {
        subcuentaTercero = cuenta;
      }
      if (!subcuentaGyI && (cuenta.startsWith("6") || cuenta.startsWith("7"))) {
        subcuentaGyI = cuenta;
      }
      if (impTipo === "iva") {
        const tipoVenta = normalizeSimple(sample.tipo_factura || "") === "venta";
        ivaImporte += Math.abs(tipoVenta ? haber : debe);
        if (!ivaPct) {
          const pct = Number(line.impuesto_pct || 0) || 0;
          ivaPct = pct;
        }
      }
      if (subcuentaGyI === cuenta) {
        base += Math.abs(cuenta.startsWith("7") ? haber : debe);
      }
    });
    const total = Number(sample.factura_total || 0) || (base + ivaImporte);
    rows.push([
      sample.fecha || "",
      sample.factura_fecha || "",
      sample.factura_numero || sample.referencia || "",
      sample.concepto || "",
      subcuentaTercero || "",
      sample.tercero_nif || "",
      sample.tercero || "",
      "",
      "",
      "",
      "",
      base ? Number(base.toFixed(2)) : "",
      ivaPct ? Number(ivaPct.toFixed(2)) : "",
      ivaImporte ? Number(ivaImporte.toFixed(2)) : "",
      subcuentaGyI || "",
      total ? Number(total.toFixed(2)) : "",
    ]);
  });
  return rows;
};

const loadGestoriaClienteLibros = (clienteId) => {
  if (!clienteId || !gestoriaClienteLibroDiarioTable) return;
  const empresa = state.empresas.find((e) => e.nombre === FINCAS_COMPANY);
  if (!empresa) return;
  const qs = new URLSearchParams({ empresa_id: empresa.id, cliente_id: clienteId });
  api(`/api/gestoria_libros?${qs.toString()}`)
    .then((data) => {
      const diario = data.diario || [];
      const mayor = data.mayor || [];

      const diarioRows = diario.map((row) => [
        row.fecha || "-",
        row.referencia || "-",
        row.concepto || "-",
        row.tercero || "-",
        row.factura_numero || "-",
        row.cuenta || "-",
        row.descripcion || "-",
        row.debe ? euroFormatter.format(parseMoneyValue(row.debe)) : "-",
        row.haber ? euroFormatter.format(parseMoneyValue(row.haber)) : "-",
      ]);
      renderSimpleTable(
        gestoriaClienteLibroDiarioTable,
        ["Fecha", "Referencia", "Concepto", "Tercero", "Factura", "Cuenta", "Descripción", "Debe", "Haber"],
        diarioRows
      );
      if (gestoriaClienteLibroDiarioInfo) {
        gestoriaClienteLibroDiarioInfo.textContent = `Mostrando ${diarioRows.length} apuntes.`;
      }

      const mayorRows = mayor.map((row) => [
        row.cuenta || "-",
        row.debe ? euroFormatter.format(parseMoneyValue(row.debe)) : "-",
        row.haber ? euroFormatter.format(parseMoneyValue(row.haber)) : "-",
        row.saldo ? euroFormatter.format(parseMoneyValue(row.saldo)) : "-",
      ]);
      renderSimpleTable(
        gestoriaClienteLibroMayorTable,
        ["Cuenta", "Debe", "Haber", "Saldo"],
        mayorRows
      );
      if (gestoriaClienteLibroMayorInfo) {
        gestoriaClienteLibroMayorInfo.textContent = `Mostrando ${mayorRows.length} cuentas.`;
      }

      // El desglose IVA se deriva del libro diario (asientos/líneas), no de un origen externo.
      const byAsiento = new Map();
      diario.forEach((row) => {
        const key = row.asiento_id || `${row.fecha || ""}-${row.referencia || ""}`;
        if (!byAsiento.has(key)) byAsiento.set(key, []);
        byAsiento.get(key).push(row);
      });
      const ivaAgg = new Map();
      byAsiento.forEach((lines) => {
        const sample = lines[0] || {};
        const tipo = normalizeSimple(sample.tipo_factura || "") === "venta" ? "Venta" : "Compra";
        const ivaLines = lines.filter((l) => normalizeSimple(l.impuesto_tipo || "") === "iva");
        if (!ivaLines.length) return;
        const pct = Number(ivaLines[0].impuesto_pct || 0) || 0;
        let cuota = 0;
        ivaLines.forEach((line) => {
          const debe = parseMoneyValue(line.debe);
          const haber = parseMoneyValue(line.haber);
          cuota += Math.abs(tipo === "Venta" ? haber : debe);
        });
        let base = 0;
        lines.forEach((line) => {
          const cuenta = String(line.cuenta || "");
          if (tipo === "Compra" && cuenta.startsWith("6")) {
            base += Math.abs(parseMoneyValue(line.debe));
          }
          if (tipo === "Venta" && cuenta.startsWith("7")) {
            base += Math.abs(parseMoneyValue(line.haber));
          }
        });
        if (!base && pct > 0) {
          base = (cuota * 100) / pct;
        }
        const key = `${tipo}-${pct.toFixed(2)}`;
        if (!ivaAgg.has(key)) ivaAgg.set(key, { tipo, pct, base: 0, cuota: 0 });
        const acc = ivaAgg.get(key);
        acc.base += base;
        acc.cuota += cuota;
      });
      const ivaRowsData = Array.from(ivaAgg.values()).sort((a, b) => {
        if (a.tipo !== b.tipo) return a.tipo.localeCompare(b.tipo);
        return a.pct - b.pct;
      });
      const ivaRows = ivaRowsData.map((row) => [
        row.tipo,
        `${row.pct.toFixed(2)} %`,
        euroFormatter.format(row.base || 0),
        euroFormatter.format(row.cuota || 0),
        euroFormatter.format((row.base || 0) + (row.cuota || 0)),
      ]);
      renderSimpleTable(
        gestoriaClienteLibroIvaTable,
        ["Tipo", "% IVA", "Base imponible", "Cuota IVA", "Total"],
        ivaRows
      );
      if (gestoriaClienteLibroIvaInfo) {
        gestoriaClienteLibroIvaInfo.textContent = `Mostrando ${ivaRows.length} líneas de desglose IVA.`;
      }

      state.gestoriaClienteLibrosCache = {
        diarioRaw: diario,
        diarioRows,
        mayorRows,
        ivaRows,
        plantillaRows: buildPlantillaConversorRows(diario),
      };
    })
    .catch(() => {
      if (gestoriaClienteLibroDiarioTable) {
        gestoriaClienteLibroDiarioTable.innerHTML = "<p class='muted'>No se pudo cargar libro diario.</p>";
      }
      if (gestoriaClienteLibroMayorTable) {
        gestoriaClienteLibroMayorTable.innerHTML = "<p class='muted'>No se pudo cargar libro mayor.</p>";
      }
      if (gestoriaClienteLibroIvaTable) {
        gestoriaClienteLibroIvaTable.innerHTML = "<p class='muted'>No se pudo cargar desglose IVA.</p>";
      }
    });
};

const parseGestoriaRentaPayload = (row = {}) => {
  if (!row || typeof row !== "object") {
    return { notes: "", entries: [] };
  }
  if (Array.isArray(row.renta_entries)) {
    return {
      notes: String(row.renta_notes || "").trim(),
      entries: row.renta_entries.filter((item) => item && typeof item === "object"),
    };
  }
  const raw = String(row.renta_detalles || "").trim();
  if (!raw) {
    return { notes: "", entries: [] };
  }
  try {
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed)) {
      return { notes: "", entries: parsed };
    }
    if (parsed && typeof parsed === "object") {
      return {
        notes: String(parsed.notes || "").trim(),
        entries: Array.isArray(parsed.entries) ? parsed.entries : [],
      };
    }
  } catch {}
  return { notes: raw, entries: [] };
};

const formatRentaResult = (value) => {
  const num = Number(value);
  if (!Number.isFinite(num)) {
    return { text: "-", className: "neutral" };
  }
  return {
    text: euroFormatter.format(num),
    className: num < 0 ? "negative" : num > 0 ? "positive" : "neutral",
  };
};

const getSortedRentaEntries = (row = {}) =>
  (parseGestoriaRentaPayload(row).entries || [])
    .slice()
    .filter((item) => item && typeof item === "object")
    .sort((a, b) => String(b.ejercicio || "").localeCompare(String(a.ejercicio || "")));

const getSelectedRentaEntry = (row = {}) => {
  const entries = getSortedRentaEntries(row);
  if (!entries.length) {
    state.currentRentaEntryId = "";
    return null;
  }
  const selectedId =
    String(state.currentRentaEntryId || "").trim() && entries.some((entry) => entry.id === state.currentRentaEntryId)
      ? state.currentRentaEntryId
      : entries[0].id;
  state.currentRentaEntryId = selectedId;
  return entries.find((entry) => entry.id === selectedId) || entries[0];
};

const formatRentaCobro = (entry = {}) => {
  if (!entry || typeof entry !== "object") return "-";
  const cobrada = Number(entry.cobrada || 0) === 1;
  const forma = String(entry.forma_cobro || "").trim();
  if (!cobrada) return "Pendiente";
  return forma ? `Cobrada · ${forma}` : "Cobrada";
};

const normalizeRentaPresentacionStatus = (value) => {
  const text = normalizeSimple(value || "");
  if (text.includes("borr")) return "Borrador";
  if (text.includes("presen")) return "Presentada";
  return "Presentada";
};

const getRentaDniMeta = (entry = {}) => {
  const permanente = Number(entry?.dni_permanente || 0) === 1 || normalizeSimple(entry?.dni_caducidad || "") === "permanente";
  return {
    expedicion: formatCell("fecha", entry?.dni_expedicion || "") || entry?.dni_expedicion || "-",
    label: permanente ? "DNI permanente" : "Caducidad DNI",
    value: permanente
      ? "Permanente"
      : formatCell("fecha", entry?.dni_caducidad || "") || entry?.dni_caducidad || "-",
  };
};

const toggleGestoriaRentaPresentarButton = (entry = {}) => {
  if (!gestoriaRentaPresentarBtn) return;
  const visible = normalizeRentaPresentacionStatus(entry?.estado_presentacion || entry?.doc_status) === "Borrador";
  gestoriaRentaPresentarBtn.classList.toggle("hidden", !visible);
};

const fillGestoriaRentaDetailsForm = (row = {}) => {
  if (!gestoriaRentaDetallesForm) return;
  const payload = parseGestoriaRentaPayload(row);
  const entry = getSelectedRentaEntry(row);
  const setValue = (name, value) => {
    const el = gestoriaRentaDetallesForm.querySelector(`[name="${name}"]`);
    if (!el) return;
    el.value = value ?? "";
  };
  setValue("entry_ejercicio", entry?.ejercicio || "");
  setValue("estado_presentacion", normalizeRentaPresentacionStatus(entry?.estado_presentacion || entry?.doc_status || "Presentada"));
  setValue("related_relation_id", payload.related_relation_id || "");
  setValue("precio_servicio", entry?.precio_servicio ?? "");
  setValue("responsable", entry?.responsable || "");
  setValue("referencia_hacienda", entry?.referencia_hacienda || "");
  setValue("forma_cobro", entry?.forma_cobro || "");
  setValue("renta_detalles", entry?.gestion_notas || payload.notes || "");
  setValue("doc_id", entry?.doc_presentada_id || entry?.doc_borrador_id || "");
  if (gestoriaRentaDeclaracionConjunta) {
    gestoriaRentaDeclaracionConjunta.checked = Number(payload.declaracion_conjunta || 0) === 1;
  }
  if (gestoriaRentaCobrada) {
    gestoriaRentaCobrada.checked = Number(entry?.cobrada || 0) === 1;
  }
  if (gestoriaRentaDocumentoForm) {
    const docSetValue = (name, value) => {
      const el = gestoriaRentaDocumentoForm.querySelector(`[name="${name}"]`);
      if (!el) return;
      el.value = value ?? "";
    };
    docSetValue(
      "nombre",
      `Renta ${entry?.ejercicio || new Date().getFullYear()} · ${normalizeRentaPresentacionStatus(entry?.estado_presentacion || entry?.doc_status)}`
    );
    docSetValue("presentacion_fecha", entry?.presentacion_fecha || "");
    docSetValue("notas", entry?.gestion_notas || payload.notes || "");
  }
  toggleGestoriaRentaPresentarButton(entry || {});
};

const buildGestoriaRentaDetailsPayload = (formPayload = {}) => {
  const row = state.currentClienteGestoriaData || {};
  const current = parseGestoriaRentaPayload(row);
  const entries = getSortedRentaEntries(row);
  const selectedEntry = getSelectedRentaEntry(row);
  const selectedId = String(selectedEntry?.id || "").trim();
  const precioServicioRaw = String(formPayload.precio_servicio || "").trim();
  const precioServicio =
    precioServicioRaw === "" ? null : parseMoneyValue(precioServicioRaw);
  const updatedEntry = {
    ...(selectedEntry || {}),
    id: selectedId || randomId(),
    ejercicio: String(formPayload.entry_ejercicio || selectedEntry?.ejercicio || new Date().getFullYear()),
    cliente_nombre: selectedEntry?.cliente_nombre || state.currentClienteData?.nombre || "",
    cliente_nif: selectedEntry?.cliente_nif || state.currentClienteData?.nif || "",
    estado_presentacion: normalizeRentaPresentacionStatus(
      formPayload.estado_presentacion || selectedEntry?.estado_presentacion || selectedEntry?.doc_status || "Presentada"
    ),
    doc_status: normalizeRentaPresentacionStatus(
      formPayload.estado_presentacion || selectedEntry?.estado_presentacion || selectedEntry?.doc_status || "Presentada"
    ),
    precio_servicio: Number.isFinite(precioServicio) ? Number(precioServicio.toFixed(2)) : null,
    responsable: String(formPayload.responsable || "").trim(),
    referencia_hacienda: String(formPayload.referencia_hacienda || "").trim(),
    cobrada: gestoriaRentaCobrada?.checked ? 1 : 0,
    forma_cobro: String(formPayload.forma_cobro || "").trim(),
    doc_presentada_id: selectedEntry?.doc_presentada_id || "",
    doc_borrador_id: selectedEntry?.doc_borrador_id || "",
    gestion_notas: String(formPayload.renta_detalles || "").trim(),
  };
  const nextEntries = entries.length
    ? entries.map((entry) => (String(entry.id || "").trim() === selectedId ? updatedEntry : entry))
    : [updatedEntry];
  state.currentRentaEntryId = updatedEntry.id;
  const selectedRelationId = String(formPayload.related_relation_id || "").trim();
  const selectedRelation = (state.currentClienteRelaciones || []).find(
    (item) => String(item.id || "").trim() === selectedRelationId
  );
  return {
    notes: current.notes || "",
    entries: nextEntries,
    related_relation_id: selectedRelationId,
    related_cliente_id: selectedRelation ? selectedRelation.counterpart_id || "" : "",
    declaracion_conjunta: gestoriaRentaDeclaracionConjunta?.checked ? 1 : 0,
  };
};

const submitGestoriaRentaDocument = async (forcedStatus = "") => {
  if (!state.currentClienteId) {
    if (gestoriaRentaDocumentoStatus) gestoriaRentaDocumentoStatus.textContent = "Selecciona un cliente.";
    return;
  }
  const row = state.currentClienteGestoriaData || {};
  const entry = getSelectedRentaEntry(row);
  if (!entry?.id) {
    if (gestoriaRentaDocumentoStatus) gestoriaRentaDocumentoStatus.textContent = "Selecciona una campaña de renta.";
    return;
  }
  if (!gestoriaRentaDocumentoForm) return;
  if (gestoriaRentaDocumentoStatus) gestoriaRentaDocumentoStatus.textContent = "Subiendo...";
  const formData = new FormData(gestoriaRentaDocumentoForm);
  const payload = Object.fromEntries(formData.entries());
  payload.usuario = getCurrentUser();
  payload.empresa_nombre = FINCAS_COMPANY;
  payload.cliente_id = state.currentClienteId;
  payload.entry_id = entry.id;
  payload.ejercicio = entry.ejercicio || payload.entry_ejercicio || new Date().getFullYear();
  payload.estado_presentacion =
    forcedStatus || normalizeRentaPresentacionStatus(gestoriaRentaEstadoPresentacion?.value || entry.estado_presentacion || entry.doc_status || "Presentada");
  payload.precio_servicio = entry.precio_servicio ?? "";
  payload.responsable = entry.responsable || "";
  payload.cobrada = Number(entry.cobrada || 0) === 1 ? 1 : 0;
  payload.forma_cobro = entry.forma_cobro || "";
  payload.doc_id = String(gestoriaRentaDocId?.value || entry.doc_presentada_id || entry.doc_borrador_id || "").trim();
  const file =
    gestoriaRentaDocumentoFile &&
    gestoriaRentaDocumentoFile.files &&
    gestoriaRentaDocumentoFile.files.length
      ? gestoriaRentaDocumentoFile.files[0]
      : null;
  if (!file) {
    if (gestoriaRentaDocumentoStatus) gestoriaRentaDocumentoStatus.textContent = "Selecciona un archivo.";
    return;
  }
  try {
    const upload = await uploadFileToS3(file, "gestoria", gestoriaRentaDocumentoStatus);
    if (upload) {
      payload.doc_key = upload.key || "";
      payload.doc_url = upload.public_url || "";
    }
    const response = await fetch("/api/renta_campaign_document", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    }).then((res) => res.json());
    if (response.error) {
      throw new Error(response.error);
    }
    if (gestoriaRentaDocumentoStatus) {
      gestoriaRentaDocumentoStatus.textContent =
        payload.estado_presentacion === "Presentada" ? "Renta presentada y ficha actualizada." : "Borrador cargado.";
    }
    if (gestoriaRentaEstadoPresentacion) {
      gestoriaRentaEstadoPresentacion.value = payload.estado_presentacion;
    }
    if (gestoriaRentaDocumentoFile) {
      gestoriaRentaDocumentoFile.value = "";
    }
    loadClienteGestoria(state.currentClienteId);
  } catch (error) {
    if (gestoriaRentaDocumentoStatus) {
      gestoriaRentaDocumentoStatus.textContent = error?.message || "Error al guardar el documento.";
    }
  }
};

const renderGestoriaRentaDetail = (entry = {}) => {
  if (!gestoriaRentaDetail) return;
  if (!entry || typeof entry !== "object") {
    gestoriaRentaDetail.classList.add("hidden");
    gestoriaRentaDetail.innerHTML = "";
    return;
  }
  const detail = document.createElement("div");
  detail.className = "renta-detail-card";
  const title = document.createElement("h4");
  title.textContent = `Ficha renta ${entry.ejercicio || "2024"}`;
  detail.appendChild(title);
  const subtitle = document.createElement("p");
  subtitle.className = "muted";
  subtitle.textContent = formatNombreCliente(entry.cliente_nombre || "");
  detail.appendChild(subtitle);

  const result = formatRentaResult(entry.resultado_declaracion);
  const dniMeta = getRentaDniMeta(entry);
  const summary = document.createElement("div");
  summary.className = "renta-detail-grid";
  const rows = [
    ["DNI", entry.cliente_nif || "-"],
    ["Fecha expedición DNI", dniMeta.expedicion],
    [dniMeta.label, dniMeta.value],
    ["Fecha nacimiento", formatCell("fecha", entry.cliente_fecha_nacimiento || "") || entry.cliente_fecha_nacimiento || "-"],
    ["Estado civil", entry.estado_civil || "-"],
    ["Hijos", String(entry.hijos_count ?? "-")],
    ["Presentación", formatCell("fecha", entry.presentacion_fecha || "") || entry.presentacion_fecha || "-"],
    ["Estado campaña", normalizeRentaPresentacionStatus(entry.estado_presentacion || entry.doc_status || "Presentada")],
    ["Referencia AEAT", entry.referencia_hacienda || "-"],
    ["Casilla 505", entry.casilla_505 != null ? euroFormatter.format(parseMoneyValue(entry.casilla_505)) : "-"],
    ["Resultado declaración", result.text],
    ["Ingresos", entry.ingresos_principales_total != null ? euroFormatter.format(parseMoneyValue(entry.ingresos_principales_total)) : "-"],
    ["Precio servicio", entry.precio_servicio != null ? euroFormatter.format(parseMoneyValue(entry.precio_servicio)) : "-"],
    ["Responsable", entry.responsable || "-"],
    ["Cobro", formatRentaCobro(entry)],
    ["Dirección", entry.direccion || "-"],
    ["Población", [entry.codigo_postal, entry.poblacion, entry.provincia].filter(Boolean).join(" ") || "-"],
  ];
  rows.forEach(([label, value]) => {
    const item = document.createElement("div");
    item.className = "renta-detail-item";
    const k = document.createElement("div");
    k.className = "muted";
    k.textContent = label;
    const v = document.createElement("div");
    v.textContent = value;
    if (label === "Resultado declaración") {
      v.classList.add("renta-result", result.className);
    }
    item.appendChild(k);
    item.appendChild(v);
    summary.appendChild(item);
  });
  detail.appendChild(summary);

  const extra = document.createElement("div");
  extra.className = "inline-list";
  const pushRow = (label, value) => {
    if (!value || (Array.isArray(value) && !value.length)) return;
    const row = document.createElement("div");
    row.className = "inline-row";
    const left = document.createElement("div");
    left.className = "muted";
    left.textContent = label;
    const right = document.createElement("div");
    right.textContent = Array.isArray(value) ? value.join(" · ") : value;
    row.appendChild(left);
    row.appendChild(right);
    extra.appendChild(row);
  };
  pushRow("Cuentas", entry.cuentas_detectadas || []);
  pushRow("Pagadores", entry.pagadores_detectados || []);
  pushRow(
    "Propiedades",
    [
      entry?.patrimonio?.direccion_inmueble_principal || "",
      entry?.patrimonio?.referencia_catastral_principal || "",
    ].filter(Boolean)
  );
  pushRow("Préstamo", entry?.patrimonio?.prestamo_hipotecario_id || "");
  pushRow(
    "Hijos",
    (entry.hijos || []).map((child) =>
      [child.nombre || "", formatCell("fecha", child.fecha_nacimiento || "") || child.fecha_nacimiento || ""]
        .filter(Boolean)
        .join(" · ")
    )
  );
  pushRow("Archivos", entry.source_files || []);
  if (extra.childNodes.length) {
    detail.appendChild(extra);
  }
  gestoriaRentaDetail.innerHTML = "";
  gestoriaRentaDetail.appendChild(detail);
  gestoriaRentaDetail.classList.remove("hidden");
};

const renderGestoriaRentaCards = (row = {}) => {
  if (!gestoriaRentaCards) return;
  const entries = getSortedRentaEntries(row);
  if (!entries.length) {
    gestoriaRentaCards.innerHTML = "<p class='muted'>Sin campañas de renta importadas.</p>";
    if (gestoriaRentaDetail) {
      gestoriaRentaDetail.classList.add("hidden");
      gestoriaRentaDetail.innerHTML = "";
    }
    fillGestoriaRentaDetailsForm(row);
    return;
  }
  const grid = document.createElement("div");
  grid.className = "renta-cards-grid";
  const selectedId = getSelectedRentaEntry(row)?.id || entries[0].id;
  entries.forEach((entry) => {
    const dniMeta = getRentaDniMeta(entry);
    const card = document.createElement("button");
    card.type = "button";
    card.className = "renta-card";
    card.classList.toggle("is-selected", entry.id === selectedId);
    const split = splitNombreApellidos(formatNombreCliente(entry.cliente_nombre || ""), "Física");
    const result = formatRentaResult(entry.resultado_declaracion);
    card.innerHTML = `
      <div class="renta-card-top">
        <strong>${entry.ejercicio || "2024"}</strong>
        <span class="pill">${normalizeRentaPresentacionStatus(entry.estado_presentacion || entry.doc_status || "Presentada")}</span>
      </div>
      <h4>${split.apellidos || "-"}</h4>
      <div>${split.nombre || formatNombreCliente(entry.cliente_nombre || "") || "-"}</div>
      <div class="muted">${entry.cliente_nif || "-"}</div>
      <div class="renta-card-meta">
        <span>Exp. DNI: ${dniMeta.expedicion}</span>
        <span>${dniMeta.label}: ${dniMeta.value}</span>
        <span>Hijos: ${entry.hijos_count ?? 0}</span>
      </div>
      <div class="renta-card-meta">
        <span>Casilla 505</span>
        <strong>${entry.casilla_505 != null ? euroFormatter.format(parseMoneyValue(entry.casilla_505)) : "-"}</strong>
      </div>
      <div class="renta-card-meta">
        <span>Referencia AEAT</span>
        <strong>${entry.referencia_hacienda || "-"}</strong>
      </div>
      <div class="renta-card-meta">
        <span>Precio</span>
        <strong>${entry.precio_servicio != null ? euroFormatter.format(parseMoneyValue(entry.precio_servicio)) : "-"}</strong>
      </div>
      <div class="renta-card-meta">
        <span>${formatRentaCobro(entry)}</span>
        <strong>${entry.responsable || "Sin responsable"}</strong>
      </div>
      <div class="renta-result ${result.className}">${result.text}</div>
    `;
    card.addEventListener("click", () => {
      state.currentRentaEntryId = entry.id;
      renderGestoriaRentaCards(row);
    });
    grid.appendChild(card);
  });
  gestoriaRentaCards.innerHTML = "";
  gestoriaRentaCards.appendChild(grid);
  const selected = entries.find((entry) => entry.id === selectedId) || entries[0];
  renderGestoriaRentaDetail(selected);
  fillGestoriaRentaDetailsForm(row);
};

const renderGestoriaRentaCrmCards = (rows = []) => {
  if (!gestoriaCrmSummary) return;
  if (!Array.isArray(rows) || !rows.length) {
    gestoriaCrmSummary.innerHTML = "<p class='muted'>Sin clientes de renta con esos filtros.</p>";
    return;
  }
  const board = document.createElement("div");
  board.className = "gestoria-renta-board";
  rows.forEach((row) => {
    const entry = row?.renta_latest || {};
    const dniMeta = getRentaDniMeta(entry);
    const result = formatRentaResult(entry.resultado_declaracion);
    const casilla505 =
      entry.casilla_505 != null ? euroFormatter.format(parseMoneyValue(entry.casilla_505)) : "-";
    const ingresos =
      entry.ingresos_principales_total != null
        ? euroFormatter.format(parseMoneyValue(entry.ingresos_principales_total))
        : "-";
    const metaLocation = [row.poblacion, row.provincia].filter(Boolean).join(" · ") || "-";
    const card = document.createElement("article");
    card.className = "gestoria-renta-overview-card";
    card.tabIndex = 0;
    card.setAttribute("role", "button");
    card.innerHTML = `
      <div class="gestoria-renta-overview-top">
        <div>
          <strong>${entry.ejercicio || "2024"}</strong>
          <span class="crm-badge">${row.estado || "Alta"}</span>
        </div>
        <div class="muted">${row.doc_count || 0} PDF</div>
      </div>
      <h4>${formatNombreCliente(row.nombre || "") || "-"}</h4>
      <div class="muted">${row.nif || "-"}</div>
      <div class="gestoria-renta-overview-grid">
        <div>
          <span class="muted">Presentación</span>
          <strong>${formatCell("fecha", entry.presentacion_fecha || "") || entry.presentacion_fecha || "-"}</strong>
        </div>
        <div>
          <span class="muted">Estado</span>
          <strong>${normalizeRentaPresentacionStatus(entry.estado_presentacion || entry.doc_status || "Presentada")}</strong>
        </div>
        <div>
          <span class="muted">Casilla 505</span>
          <strong>${casilla505}</strong>
        </div>
        <div>
          <span class="muted">Referencia AEAT</span>
          <strong>${entry.referencia_hacienda || "-"}</strong>
        </div>
        <div>
          <span class="muted">Resultado</span>
          <strong class="renta-result ${result.className}">${result.text}</strong>
        </div>
        <div>
          <span class="muted">Ingresos</span>
          <strong>${ingresos}</strong>
        </div>
        <div>
          <span class="muted">Precio</span>
          <strong>${entry.precio_servicio != null ? euroFormatter.format(parseMoneyValue(entry.precio_servicio)) : "-"}</strong>
        </div>
        <div>
          <span class="muted">Cobro</span>
          <strong>${formatRentaCobro(entry)}</strong>
        </div>
      </div>
      <div class="gestoria-renta-overview-meta">
        <span>${entry.estado_civil || "Sin estado civil"}</span>
        <span>Hijos: ${entry.hijos_count ?? 0}</span>
        <span>Exp. DNI: ${dniMeta.expedicion}</span>
        <span>${dniMeta.label}: ${dniMeta.value}</span>
        <span>${entry.responsable || "Sin responsable"}</span>
        <span>${metaLocation}</span>
      </div>
    `;
    const openCliente = () => {
      const clienteId = String(row.cliente_id || "").trim();
      if (clienteId) {
        openClienteDetail(clienteId);
      }
    };
    card.addEventListener("click", openCliente);
    card.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        openCliente();
      }
    });

    const footer = document.createElement("div");
    footer.className = "gestoria-renta-overview-actions";

    const clienteBtn = document.createElement("button");
    clienteBtn.type = "button";
    clienteBtn.className = "secondary";
    clienteBtn.textContent = "Ver cliente";
    clienteBtn.addEventListener("click", (event) => {
      event.stopPropagation();
      openCliente();
    });
    footer.appendChild(clienteBtn);

    const previewDoc = row?.preview_doc || {};
    if (previewDoc.doc_key || previewDoc.doc_url) {
      const pdfBtn = document.createElement("button");
      pdfBtn.type = "button";
      pdfBtn.className = "secondary ghost";
      pdfBtn.textContent = "Ver PDF";
      pdfBtn.addEventListener("click", (event) => {
        event.stopPropagation();
        openS3File(previewDoc.doc_key || "", previewDoc.doc_url || "");
      });
      footer.appendChild(pdfBtn);
    }

    card.appendChild(footer);
    board.appendChild(card);
  });
  gestoriaCrmSummary.innerHTML = "";
  gestoriaCrmSummary.appendChild(board);
};

const loadClienteGestoria = (clienteId) => {
  if (!clienteGestoriaForm) return;
  api(`/api/cliente_gestoria?cliente_id=${clienteId}`).then((data) => {
    const row = data.row || {};
    state.currentClienteGestoriaData = row;
    const setValue = (name, value) => {
      const el = clienteGestoriaForm.querySelector(`[name="${name}"]`);
      if (!el) return;
      el.value = value || "";
    };
    const setCheck = (name, value) => {
      const el = clienteGestoriaForm.querySelector(`[name="${name}"]`);
      if (!el) return;
      el.checked = String(value || "0") === "1";
    };
    setValue("tipo_cliente", row.tipo_cliente || "");
    setCheck("mod_fiscal", row.mod_fiscal);
    setCheck("mod_laboral", row.mod_laboral);
    setCheck("mod_contable", row.mod_contable);
    setCheck("mod_renta", row.mod_renta);
    setCheck("mod_registro", row.mod_registro);
    setCheck("mod_trafico", row.mod_trafico);
    setCheck("mod_puntuales", row.mod_puntuales);
    if (gestoriaRentaDetallesForm) {
      if (gestoriaRentaRelacionSelect) {
        populateGestoriaRentaRelationOptions(
          state.currentClienteRelaciones || [],
          row.renta_related_relation_id || ""
        );
      }
      fillGestoriaRentaDetailsForm(row);
    }
    renderGestoriaRentaCards(row);
    if (gestoriaRentaInfo && Array.isArray(row.renta_entries) && row.renta_entries.length) {
      gestoriaRentaInfo.textContent = `Mostrando ${row.renta_entries.length} campañas de renta.`;
    }
    updateGestoriaModuleTabsFromForm();
  });
};

const loadGestoriaModelos = (clienteId) => {
  if (!gestoriaModelosTable) return;
  api(`/api/gestoria_modelos?cliente_id=${clienteId}`).then((data) => {
    const rows = data.rows || [];
    if (!rows.length) {
      gestoriaModelosTable.innerHTML = "<p class='muted'>Sin modelos asignados.</p>";
      return;
    }
    const readonly = state.currentPage === "cliente";
    const table = document.createElement("table");
    const thead = document.createElement("thead");
    const trHead = document.createElement("tr");
    ["modelo", "periodicidad", "proxima_fecha", "responsable", "estado", "notas"]
      .concat(readonly ? [] : ["accion"])
      .forEach((col) => {
      const th = document.createElement("th");
      th.textContent = formatHeader(col);
      trHead.appendChild(th);
    });
    thead.appendChild(trHead);
    table.appendChild(thead);
    const tbody = document.createElement("tbody");
    rows.forEach((row) => {
      const tr = document.createElement("tr");
      ["modelo", "periodicidad", "proxima_fecha", "responsable", "estado", "notas"].forEach((field) => {
        const td = document.createElement("td");
        if (readonly) {
          td.textContent = row[field] || "";
        } else if (field === "periodicidad" || field === "estado") {
          const select = document.createElement("select");
          const options =
            field === "periodicidad"
              ? ["Mensual", "Trimestral", "Anual", "Puntual"]
              : ["Pendiente", "En curso", "Presentado"];
          options.forEach((opt) => select.appendChild(createOption(opt, opt)));
          select.value = row[field] || options[0];
          select.addEventListener("change", () => {
            saveGestoriaModeloField(row.id, field, select.value);
          });
          td.appendChild(select);
        } else {
          const input = document.createElement("input");
          input.value = row[field] || "";
          if (field === "proxima_fecha") {
            input.type = "date";
          }
          input.addEventListener("change", () => {
            saveGestoriaModeloField(row.id, field, input.value);
          });
          td.appendChild(input);
        }
        tr.appendChild(td);
      });
      if (!readonly) {
        const actionTd = document.createElement("td");
        const del = document.createElement("button");
        del.type = "button";
        del.textContent = "Eliminar";
        del.addEventListener("click", () => {
          deleteGestoriaModelo(row.id, clienteId);
        });
        actionTd.appendChild(del);
        tr.appendChild(actionTd);
      }
      tbody.appendChild(tr);
    });
    table.appendChild(tbody);
    gestoriaModelosTable.innerHTML = "";
    gestoriaModelosTable.appendChild(table);
  });
};

