const runGestoriaFacturaOcr = async ({
  fileInput,
  tipoInput,
  statusEl,
  clienteId,
} = {}) => {
  if (!fileInput || !fileInput.files || !fileInput.files.length) {
    if (statusEl) statusEl.textContent = "Selecciona una factura (PDF/imagen).";
    return;
  }
  const file = fileInput.files[0];
  const dataUrl = await readFileAsDataUrl(file);
  const payload = {
    empresa_nombre: FINCAS_COMPANY,
    file_base64: dataUrl,
    filename: file.name || "",
    tipo_factura: tipoInput ? tipoInput.value : "compra",
    cliente_id: clienteId || "",
  };
  if (statusEl) statusEl.textContent = "Procesando OCR y asiento...";
  const res = await fetch("/api/gestoria_factura_ocr", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  const data = await res.json().catch(() => ({}));
  if (data?.error) {
    if (statusEl) statusEl.textContent = data.error;
    return;
  }
  if (statusEl) {
    const factura = data?.parsed?.numero || data?.factura_id || "";
    const asiento = data?.asiento_id || "";
    statusEl.textContent = `Factura ${factura} procesada. Asiento ${asiento}.`;
  }
  fileInput.value = "";
  loadGestoriaContabilidad();
  if (clienteId) {
    loadGestoriaClienteContaResultados(clienteId);
    loadGestoriaClienteLibros(clienteId);
  }
};

const updateCatalogoList = (datalist, rows) => {
  if (!datalist) return;
  datalist.innerHTML = "";
  rows.forEach((row) => {
    const opt = document.createElement("option");
    opt.value = row.codigo;
    opt.textContent = `${row.codigo} · ${row.descripcion}`;
    datalist.appendChild(opt);
  });
};

const loadCatalogo = (tipo, q = "") => {
  return api(`/api/catalogo?tipo=${tipo}&q=${encodeURIComponent(q)}`).then(
    (data) => data.rows || []
  );
};

const setSuggestText = (target, rows) => {
  if (!target) return;
  if (!rows || !rows.length) {
    target.textContent = "";
    return;
  }
  const line = rows
    .slice(0, 3)
    .map((row) => `${row.codigo} · ${row.descripcion}`)
    .join(" | ");
  target.textContent = `Sugerencias: ${line}`;
};

const setupCatalogoInputs = () => {
  const cnaeInput = clienteProfesionalCnaeForm?.querySelector('[name="cnae"]');
  const iaeInput = clienteProfesionalIaeForm?.querySelector('[name="iae"]');
  const actividadInput = clienteProfesionalActividadForm?.querySelector('[name="actividad"]');
  if (cnaeInput) {
    cnaeInput.addEventListener("input", () => {
      const q = cnaeInput.value.trim();
      loadCatalogo("cnae", q).then((rows) => {
        updateCatalogoList(cnaeCatalogo, rows);
        setSuggestText(cnaeSuggest, rows);
      });
    });
    cnaeInput.addEventListener("blur", () => {
      const codigo = cnaeInput.value.trim();
      if (!codigo) return;
      loadCatalogo("cnae", codigo).then((rows) => {
        const exact = rows.find((row) => row.codigo === codigo);
        if (exact && actividadInput && !actividadInput.value.trim()) {
          actividadInput.value = exact.descripcion;
        }
      });
    });
  }
  if (iaeInput) {
    iaeInput.addEventListener("input", () => {
      const q = iaeInput.value.trim();
      loadCatalogo("iae", q).then((rows) => {
        updateCatalogoList(iaeCatalogo, rows);
        setSuggestText(iaeSuggest, rows);
      });
    });
    iaeInput.addEventListener("blur", () => {
      const codigo = iaeInput.value.trim();
      if (!codigo) return;
      loadCatalogo("iae", codigo).then((rows) => {
        const exact = rows.find((row) => row.codigo === codigo);
        if (exact && actividadInput && !actividadInput.value.trim()) {
          actividadInput.value = exact.descripcion;
        }
      });
    });
  }
  if (actividadInput) {
    actividadInput.addEventListener("blur", () => {
      const texto = actividadInput.value.trim();
      if (!texto) return;
      api(`/api/catalogo_match?texto=${encodeURIComponent(texto)}`).then((data) => {
        const cnaeRows = data.cnae || [];
        const iaeRows = data.iae || [];
        setSuggestText(actividadSuggest, [
          ...cnaeRows.map((row) => ({ ...row, codigo: `CNAE ${row.codigo}` })),
          ...iaeRows.map((row) => ({ ...row, codigo: `IAE ${row.codigo}` })),
        ]);
        if (cnaeRows.length === 1 && cnaeInput && !cnaeInput.value.trim()) {
          cnaeInput.value = cnaeRows[0].codigo;
        }
        if (iaeRows.length === 1 && iaeInput && !iaeInput.value.trim()) {
          iaeInput.value = iaeRows[0].codigo;
        }
      });
    });
  }
};

const loadGestoriaFact = () => {
  if (!gestoriaFacturasTable) return;
  gestoriaFacturasTable.innerHTML =
    "<p class='muted'>Sin facturas cargadas. Se integrará en fase 2.</p>";
};

const loadAgendaGeneral = () => {
  if (!agendaGeneral) return;
  const fincas = state.empresas.find((e) => e.nombre === FINCAS_COMPANY);
  const fin = state.empresas.find((e) => e.nombre === FIN_COMPANY);
  const tasks = [];
  const allowed = state.currentUserServices || [];
  const allowService = (value) => {
    if (!allowed.length) return true;
    return allowed.includes(normalizeSimple(value));
  };
  if (fincas) {
    if (allowService("gestoria")) {
      tasks.push(api(`/api/acciones?servicio=gestoria&empresa_id=${fincas.id}`));
    }
    if (allowService("seguros")) {
      tasks.push(api(`/api/acciones?servicio=seguros&empresa_id=${fincas.id}`));
    }
  }
  if (fin) {
    if (allowService("financiaciones")) {
      tasks.push(api(`/api/acciones?servicio=financiaciones&empresa_id=${fin.id}`));
    }
  }
  if (!tasks.length) {
    agendaGeneral.innerHTML = "<p class='muted'>Sin empresas cargadas.</p>";
    return;
  }
  agendaGeneral.dataset.readonly = "1";
  Promise.all(tasks).then((responses) => {
    const allRows = responses.flatMap((data) => data.rows || []);
    const events = buildAgendaEvents(allRows, "", "");
    renderAgendaCalendar(agendaGeneral, events, "Agenda general");
  });
};

const parseMoneyValue = (value) => {
  const direct = Number(value);
  if (Number.isFinite(direct)) return direct;
  const normalized = String(value || "")
    .replace(/[€\s]/g, "")
    .replace(/\./g, "")
    .replace(",", ".");
  const parsed = Number(normalized);
  return Number.isFinite(parsed) ? parsed : 0;
};

const getTableRowsByEmpresa = async (tabla, empresaId, q = "") => {
  if (!tabla || !empresaId) return { columns: [], rows: [] };
  const params = new URLSearchParams({ tabla, empresa_id: empresaId });
  if (q) params.set("q", q);
  const data = await api(`/api/tabla?${params.toString()}`);
  return {
    columns: data?.columns || [],
    rows: data?.rows || [],
  };
};

const loadClienteHipotecasFicha = async (cliente = null, empresasActivas = []) => {
  if (!clienteHipotecaFicha) return;
  const clienteNombre = String(cliente?.nombre || "").trim();
  if (!clienteNombre) {
    clienteHipotecaFicha.innerHTML = "<p class='muted'>Sin nombre de cliente para buscar financiaciones.</p>";
    return;
  }
  const empresaByName = new Map((state.empresas || []).map((item) => [item.nombre, item.id]));
  let finEmpresaIds = (empresasActivas || [])
    .filter((row) => normalizeSimple(row.servicio || "") === "financiaciones")
    .map((row) => empresaByName.get(row.empresa))
    .filter(Boolean);
  if (!finEmpresaIds.length) {
    const fin = (state.empresas || []).find((item) => item.nombre === FIN_COMPANY);
    if (fin?.id) finEmpresaIds = [fin.id];
  }
  if (!finEmpresaIds.length) {
    clienteHipotecaFicha.innerHTML = "<p class='muted'>Sin empresa de financiaciones configurada.</p>";
    return;
  }
  try {
    const groups = await Promise.all(
      finEmpresaIds.map((empresaId) =>
        getTableRowsByEmpresa("hipotecas", empresaId, clienteNombre).catch(() => ({ columns: [], rows: [] }))
      )
    );
    const base = groups.find((item) => Array.isArray(item.columns) && item.columns.length) || { columns: [], rows: [] };
    const columns = base.columns || [];
    if (!columns.length) {
      clienteHipotecaFicha.innerHTML = "<p class='muted'>Sin financiaciones vinculadas.</p>";
      return;
    }
    const idIndex = columns.indexOf("id");
    const clienteIdx = columns.indexOf("cliente");
    const seen = new Set();
    const clienteKey = normalizeSimple(clienteNombre);
    const rows = groups
      .flatMap((item) => item.rows || [])
      .filter((row) => Array.isArray(row))
      .filter((row) => {
        const uniqueKey =
          idIndex >= 0 ? String(row[idIndex] || "").trim() : JSON.stringify(row);
        if (uniqueKey && seen.has(uniqueKey)) return false;
        if (uniqueKey) seen.add(uniqueKey);
        if (clienteIdx < 0) return true;
        return normalizeSimple(String(row[clienteIdx] || "")).includes(clienteKey);
      });
    if (!rows.length) {
      clienteHipotecaFicha.innerHTML = "<p class='muted'>Sin financiaciones vinculadas.</p>";
      return;
    }
    renderTableInto({ columns, rows }, clienteHipotecaFicha, null, "Hipotecas");
  } catch {
    clienteHipotecaFicha.innerHTML = "<p class='muted'>No se pudo cargar la ficha de financiaciones.</p>";
  }
};

