if (segurosOcrButton) {
  segurosOcrButton.addEventListener("click", () => {
    if (segurosOcrStatus) {
      segurosOcrStatus.textContent = "";
    }
    if (segurosOcrSaveStatus) {
      segurosOcrSaveStatus.textContent = "";
    }
    state.segurosOcrClienteId = "";
    state.segurosOcrParsedFields = {};
    setOcrClienteUi(getOcrClienteContext("alta"), { status: "" });
    if (!segurosOcrFile || !segurosOcrFile.files || !segurosOcrFile.files.length) {
      if (segurosOcrStatus) {
        segurosOcrStatus.textContent = "Selecciona un PDF.";
      }
      return;
    }
    const file = segurosOcrFile.files[0];
    if (!file.name.toLowerCase().endsWith(".pdf")) {
      if (segurosOcrStatus) {
        segurosOcrStatus.textContent = "El archivo debe ser PDF.";
      }
      return;
    }
    if (segurosOcrStatus) {
      segurosOcrStatus.textContent = "Procesando OCR...";
    }
    buildSegurosOcrPayload(file, segurosOcrStatus)
      .then(async (payload) => {
        if (!payload) {
          if (segurosOcrStatus) {
            segurosOcrStatus.textContent = "No se pudo preparar el PDF para OCR.";
          }
          return null;
        }
        try {
          return await runSegurosOcrDirectPayload(
            { ...payload, empresa_nombre: FINCAS_COMPANY, fast_mode: 1 },
            { timeoutMs: 180000 }
          );
        } catch (_directErr) {
          if (segurosOcrStatus) {
            segurosOcrStatus.textContent = "OCR directo lento. Reintentando en cola...";
          }
          const job = await startSegurosOcrJob({ ...payload, empresa_nombre: FINCAS_COMPANY });
          if (!job || job.error || !job.job_id) {
            throw new Error(job?.detail || job?.error || "No se pudo iniciar OCR.");
          }
          if (segurosOcrStatus) segurosOcrStatus.textContent = "OCR en cola...";
          const result = await pollOcrJob(job.job_id, (data) => {
            if (segurosOcrStatus && data.status === "processing") {
              segurosOcrStatus.textContent = "Procesando OCR...";
            }
          });
          return result;
        }
      })
      .then((data) => {
        if (!data) return;
        if (data.error) {
          if (segurosOcrStatus) {
            segurosOcrStatus.textContent = data.detail
              ? `${data.error} ${data.detail}`
              : data.error;
          }
          state.segurosOcrClienteId = "";
          state.segurosOcrParsedFields = {};
          return;
        }
        state.segurosOcrQuality = data.ocr_quality || null;
        fillSegurosOcrFields(data.fields || {});
        if (segurosOcrRaw) {
          segurosOcrRaw.value = (data.text || "").trim();
        }
        resolveOcrClienteMatch("alta", data.fields || {}).then(() => {
          if (state.segurosOcrClienteId) {
            if (segurosOcrSaveStatus) {
              segurosOcrSaveStatus.textContent =
                "Cliente detectado. Revisa datos y pulsa Guardar póliza.";
            }
          } else if (segurosOcrSaveStatus) {
            segurosOcrSaveStatus.textContent =
              "Revisa el cliente (DNI) antes de guardar la póliza.";
          }
        });
        if (segurosOcrStatus) {
          const lang = data.language ? ` (${data.language})` : "";
          const method = data.method ? ` · ${data.method}` : "";
          const docType = data.doc_type ? ` · ${data.doc_type}` : "";
          const calidad = data.ocr_quality?.calidad ? ` · ${data.ocr_quality.calidad}` : "";
          const fields = data.fields || {};
          const filled = Object.entries(fields)
            .filter(([, value]) => String(value || "").trim().length)
            .map(([key]) => key);
          if (filled.length) {
            segurosOcrStatus.textContent = `Datos extraídos${lang}${method}${docType}${calidad}: ${filled.join(", ")}.`;
          } else {
            segurosOcrStatus.textContent = `No se detectaron campos${lang}${method}${docType}${calidad}.`;
          }
        }
        if (seguroOcrEstado && data.doc_type) {
          if (data.doc_type === "presupuesto") {
            seguroOcrEstado.value = "Presupuesto";
          } else if (data.doc_type === "poliza") {
            seguroOcrEstado.value = "Contratada";
          }
        }
      })
      .catch((err) => {
        if (segurosOcrStatus) {
          segurosOcrStatus.textContent = err?.message || "No se pudo procesar el PDF.";
        }
        state.segurosOcrClienteId = "";
        state.segurosOcrQuality = null;
        state.segurosOcrParsedFields = {};
      });
  });
}

if (segurosBdtOcrButton) {
  segurosBdtOcrButton.addEventListener("click", () => {
    if (segurosBdtOcrStatus) segurosBdtOcrStatus.textContent = "";
    state.segurosBdtOcrClienteId = "";
    setOcrClienteUi(getOcrClienteContext("bdt"), { status: "" });
    if (!segurosBdtOcrFile || !segurosBdtOcrFile.files || !segurosBdtOcrFile.files.length) {
      if (segurosBdtOcrStatus) segurosBdtOcrStatus.textContent = "Selecciona un PDF.";
      return;
    }
    const file = segurosBdtOcrFile.files[0];
    if (!file.name.toLowerCase().endsWith(".pdf")) {
      if (segurosBdtOcrStatus) segurosBdtOcrStatus.textContent = "El archivo debe ser PDF.";
      return;
    }
    if (segurosBdtOcrStatus) segurosBdtOcrStatus.textContent = "Procesando OCR...";
    buildSegurosOcrPayload(file, segurosBdtOcrStatus)
      .then((payload) => {
        if (!payload) {
          if (segurosBdtOcrStatus) {
            segurosBdtOcrStatus.textContent = "No se pudo preparar el PDF para OCR.";
          }
          return null;
        }
        return startSegurosOcrJob({ ...payload, empresa_nombre: FINCAS_COMPANY });
      })
      .then(async (job) => {
        if (!job || job.error || !job.job_id) {
          if (segurosBdtOcrStatus) {
            segurosBdtOcrStatus.textContent = "OCR en cola falló. Reintentando en modo directo...";
          }
          return runSegurosOcrDirect(file, { empresa_nombre: FINCAS_COMPANY });
        }
        if (segurosBdtOcrStatus) segurosBdtOcrStatus.textContent = "OCR en cola...";
        try {
          const result = await pollOcrJob(job.job_id, (data) => {
            if (segurosBdtOcrStatus && data.status === "processing") {
              segurosBdtOcrStatus.textContent = "Procesando OCR...";
            }
          });
          return result;
        } catch (_err) {
          if (segurosBdtOcrStatus) {
            segurosBdtOcrStatus.textContent = "OCR asíncrono falló. Reintentando en modo directo...";
          }
          return runSegurosOcrDirect(file, { empresa_nombre: FINCAS_COMPANY });
        }
      })
      .then((data) => {
        if (!data) return;
        if (data.error) {
          if (segurosBdtOcrStatus) {
            segurosBdtOcrStatus.textContent = data.detail
              ? `${data.error} ${data.detail}`
              : data.error;
          }
          state.segurosBdtOcrClienteId = "";
          return;
        }
        fillSegurosBdtOcrFields(data.fields || {});
        resolveOcrClienteMatch("bdt", data.fields || {});
        if (segurosBdtOcrStatus && (data.doc_type || data.ocr_quality?.calidad)) {
          const docType = data.doc_type ? ` · ${data.doc_type}` : "";
          const calidad = data.ocr_quality?.calidad ? ` · ${data.ocr_quality.calidad}` : "";
          segurosBdtOcrStatus.textContent = `OCR listo${docType}${calidad}.`;
        }
        matchSegurosBdtFromFields().catch(() => {});
      })
      .catch((err) => {
        if (segurosBdtOcrStatus) {
          segurosBdtOcrStatus.textContent = err?.message || "No se pudo procesar el PDF.";
        }
        state.segurosBdtOcrClienteId = "";
      });
  });
}

