if (inmuebleActividadForm) {
  const tipoSelect = inmuebleActividadForm.querySelector('select[name="tipo"]');
  const resultSelect = inmuebleActividadForm.querySelector('select[name="resultado_cierre"]');
  if (tipoSelect) {
    tipoSelect.addEventListener("change", () => {
      syncInmuebleWorkflowForm();
    });
  }
  if (resultSelect) {
    resultSelect.addEventListener("change", () => {
      syncInmuebleWorkflowForm();
    });
  }

  if (inmuebleGeocodeBtn) {
    inmuebleGeocodeBtn.addEventListener("click", () => {
      runInmuebleGeocodeFromUi();
    });
  }
  syncInmuebleWorkflowForm();
  inmuebleActividadForm.addEventListener("submit", (event) => {
    event.preventDefault();
    if (!state.currentInmuebleId) {
      if (inmuebleActividadStatus) {
        inmuebleActividadStatus.textContent = "Selecciona un inmueble.";
      }
      return;
    }
    if (inmuebleActividadStatus) {
      inmuebleActividadStatus.textContent = "Guardando...";
    }
    const formData = new FormData(inmuebleActividadForm);
    const payload = Object.fromEntries(formData.entries());
    const tipo = String(payload.tipo || "").trim();
    const estado = String(payload.estado || "").trim() || "Pendiente";
    const requiredResults = INMO_WORKFLOW_RESULT_OPTIONS[tipo];
    if (!requiredResults) {
      payload.resultado_cierre = "";
      payload.estado_siguiente = "";
    } else if (estado.toLowerCase() === "pendiente") {
      payload.resultado_cierre = "";
      payload.estado_siguiente = "";
    } else if (!String(payload.resultado_cierre || "").trim()) {
      if (inmuebleActividadStatus) {
        inmuebleActividadStatus.textContent = "Esta cita debe cerrarse con resultado.";
      }
      return;
    } else if (!requiredResults.includes(String(payload.resultado_cierre || "").trim())) {
      if (inmuebleActividadStatus) {
        inmuebleActividadStatus.textContent = "El resultado no es válido para este tipo de cita.";
      }
      return;
    }
    Object.assign(
      payload,
      resolveClienteFromInput(inmuebleActividadClienteInput, inmuebleActividadClienteId)
    );
    payload.empresa_nombre = resolveCrmInmoEmpresaNombre();
    payload.servicio = "inmobiliaria";
    payload.inmueble_id = state.currentInmuebleId;
    fetch("/api/acciones", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    })
      .then((res) => res.json())
      .then((data) => {
        if (inmuebleActividadStatus) {
          inmuebleActividadStatus.textContent = data.error || "Guardado.";
        }
        if (!data.error) {
          inmuebleActividadForm.reset();
          syncInmuebleWorkflowForm();
          const empresa = resolveCrmInmoEmpresa();
          if (empresa) {
            loadInmuebleActividad(state.currentInmuebleId, empresa.id);
          }
        }
      })
      .catch(() => {
        if (inmuebleActividadStatus) {
          inmuebleActividadStatus.textContent = "Error al guardar.";
        }
      });
  });
}

if (inmuebleDocsForm) {
  inmuebleDocsForm.addEventListener("submit", async (event) => {
    event.preventDefault();
    if (!state.currentInmuebleId) {
      if (inmuebleDocsStatus) {
        inmuebleDocsStatus.textContent = "Selecciona un inmueble.";
      }
      return;
    }
    const files = Array.from(inmuebleDocsFile?.files || []).filter(Boolean);
    if (!files.length) {
      if (inmuebleDocsStatus) {
        inmuebleDocsStatus.textContent = "Selecciona un archivo.";
      }
      return;
    }
    const tipo = String(inmuebleDocsForm.querySelector('[name="tipo"]')?.value || "").trim();
    const nombreBase = String(inmuebleDocsForm.querySelector('[name="nombre"]')?.value || "").trim();

    const uploadOne = async (file, index) => {
      const maxInline = 2_000_000;
      const payload = {
        inmueble_id: state.currentInmuebleId,
        empresa_nombre: resolveCrmInmoEmpresaNombre(),
        usuario: getCurrentUser(),
        tipo,
        nombre: files.length === 1 && nombreBase ? nombreBase : file.name,
      };
      try {
        if (file.size > maxInline) {
          try {
            if (inmuebleDocsStatus) inmuebleDocsStatus.textContent = `Subiendo ${index + 1}/${files.length} (S3)...`;
            const upload = await uploadFileToS3(file, `inmuebles/${state.currentInmuebleId}`, inmuebleDocsStatus);
            if (upload?.key) {
              payload.s3_key = upload.key;
            } else {
              payload.file_base64 = await fileToBase64(file);
            }
          } catch (err) {
            payload.file_base64 = await fileToBase64(file);
          }
        } else {
          if (inmuebleDocsStatus) inmuebleDocsStatus.textContent = `Subiendo ${index + 1}/${files.length}...`;
          payload.file_base64 = await fileToBase64(file);
        }
      } catch (err) {
        throw new Error(err?.message || "No se pudo leer el archivo.");
      }
      if (inmuebleDocsStatus) inmuebleDocsStatus.textContent = `Registrando ${index + 1}/${files.length}...`;
      const res = await fetch("/api/inmueble_docs", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok || data?.error) {
        throw new Error(data?.error || "Error al subir.");
      }
      return data;
    };

    try {
      for (let i = 0; i < files.length; i += 1) {
        await uploadOne(files[i], i);
      }
      if (inmuebleDocsStatus) inmuebleDocsStatus.textContent = `Subida completada (${files.length}).`;
      inmuebleDocsForm.reset();
      loadInmuebleDocs(state.currentInmuebleId);
    } catch (err) {
      if (inmuebleDocsStatus) inmuebleDocsStatus.textContent = err?.message || "Error al subir.";
    }
  });
}

