if (gestoriaClienteLibroExcelBtn) {
  gestoriaClienteLibroExcelBtn.addEventListener("click", async () => {
    const clienteId = String(state.currentClienteId || "").trim();
    const empresa = state.empresas.find((e) => e.nombre === FINCAS_COMPANY);
    if (!clienteId || !empresa?.id) {
      if (gestoriaClienteLibroExcelStatus) {
        gestoriaClienteLibroExcelStatus.textContent = "Cliente o empresa no disponible.";
      }
      return;
    }
    try {
      const qs = new URLSearchParams({ empresa_id: empresa.id, cliente_id: clienteId });
      const resp = await fetch(`/api/gestoria_excel_plantilla?${qs.toString()}`, {
        credentials: "same-origin",
      });
      if (resp.ok) {
        const blob = await resp.blob();
        const cd = resp.headers.get("Content-Disposition") || "";
        const match = cd.match(/filename=\"?([^\";]+)\"?/i);
        const filename =
          (match && match[1]) ||
          `plantilla_conversor_asientos_${new Date().toISOString().slice(0, 10)}.xlsx`;
        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
        if (gestoriaClienteLibroExcelStatus) {
          gestoriaClienteLibroExcelStatus.textContent = "Excel generado.";
        }
        return;
      }
    } catch (_) {}

    // Fallback CSV si el backend no puede generar XLSX.
    const cache = state.gestoriaClienteLibrosCache || {};
    const plantillaRows = cache.plantillaRows || [];
    if (!plantillaRows.length) {
      if (gestoriaClienteLibroExcelStatus) {
        gestoriaClienteLibroExcelStatus.textContent = "No hay datos para exportar.";
      }
      return;
    }
    const rows = [
      [
        "FECHA ASIENTO",
        "FECHA FACTURA",
        "Nº FACTURA",
        "CONCEPTO",
        "SUBCUENTA",
        "NIF",
        "NOMBRE",
        "DOMICILIO",
        "LOCALIDAD",
        "PROVINCIA",
        "CODIGO POSTAL",
        "BASE IMPONIBLE",
        "% IVA",
        "IMPORTE IVA",
        "SUBCUENTA GASTOS/INGRESOS",
        "IMPORTE (TOTAL)",
      ],
      ...plantillaRows,
    ];
    const clienteNombre = normalizeSimple(state.currentClienteData?.nombre || "cliente").replace(/\s+/g, "_");
    const filename = `plantilla_conversor_asientos_${clienteNombre || "cliente"}_${new Date().toISOString().slice(0, 10)}.csv`;
    downloadCsvFile(filename, toCsv(rows));
    if (gestoriaClienteLibroExcelStatus) {
      gestoriaClienteLibroExcelStatus.textContent = "Plantilla generada en CSV (fallback).";
    }
  });
}

const formatInmobiliariaDuplicateSummary = (duplicates = []) =>
  duplicates
    .slice(0, 5)
    .map((item) => {
      const label = item?.label || item?.direccion || "Registro existente";
      const reasons = Array.isArray(item?.reasons) ? item.reasons.join(", ") : "";
      return `- ${label}${reasons ? ` · ${reasons}` : ""}`;
    })
    .join("\n");

const submitInmobiliariaWithDuplicateCheck = async ({
  endpoint,
  payload,
  statusEl,
  successMessage,
  onSuccess,
}) => {
  const postPayload = async (allowDuplicate = false) => {
    const res = await fetch(endpoint, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        ...payload,
        ...(allowDuplicate ? { allow_duplicate: "1" } : {}),
      }),
    });
    let data = null;
    try {
      data = await res.json();
    } catch (_) {
      data = null;
    }
    return { res, data };
  };

  let { res, data } = await postPayload(false);
  if (res.status === 409 && data?.code === "duplicate_detected") {
    const duplicateText = formatInmobiliariaDuplicateSummary(data?.duplicates || []);
    if (statusEl) {
      statusEl.textContent = duplicateText
        ? `Posible duplicado detectado. ${duplicateText.replace(/\n/g, " | ")}`
        : "Posible duplicado detectado.";
    }
    const confirmed = window.confirm(
      `Se han detectado posibles duplicados:\n\n${duplicateText || "- Registro similar existente"}\n\n¿Quieres guardar de todos modos?`
    );
    if (!confirmed) {
      return { duplicateCancelled: true, data };
    }
    ({ res, data } = await postPayload(true));
  }

  if (!res.ok || data?.error) {
    throw new Error(data?.error || `HTTP ${res.status}`);
  }
  if (statusEl) {
    statusEl.textContent = successMessage;
  }
  if (typeof onSuccess === "function") {
    onSuccess(data);
  }
  return { ok: true, data };
};


